window.HUB_DETAIL={"by":{"clement-of-rome":{"extract":"Clement of Rome, also known as Pope Clement I, was the Bishop of Rome in the late first century. He is considered to be the first of the Apostolic Fathers of the Church.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/04012c.htm","kind":"about"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Clement%20of%20Rome%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Clement_of_Rome","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Clemens_Romanus.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"ignatius-of-antioch":{"extract":"Ignatius of Antioch, also known as Ignatius Theophorus, was an early Christian writer and the Patriarch of Antioch. While en route to Rome, where he was to be killed, Ignatius wrote a series of letters. This correspondence forms a central part of a later collection of works by the Apostolic Fathers. He is considered one of the three most important of these, together with Clement of Rome and Polycarp. Although the authenticity of his letters has been questioned, they continue to serve as an example of early Christian theology, and address important topics including ecclesiology, the sacraments,","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/07644a.htm","kind":"about"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/58969","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Ignatius%20of%20Antioch%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ignatius_of_Antioch","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Hosios_Loukas_%28south_west_chapel%2C_south_side%29_-_Ignatios.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"polycarp-of-smyrna":{"extract":"Polycarp was a Christian bishop of Smyrna. According to the Martyrdom of Polycarp, he died a martyr, bound and burned at the stake, then stabbed when the fire failed to consume his body. Polycarp is regarded as a saint and Church Father in the Eastern Orthodox Church, the Catholic Church, Oriental Orthodox Churches, Lutheranism, and Anglicanism.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/12219b.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/polycarp","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/58967","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Polycarp%20of%20Smyrna%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Polycarp","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Polycarp_of_Smyrna2.jpg","license":"CC0","artist":"PravoslavnyChristianin","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","pd":1}},"papias-of-hierapolis":{"extract":"Papias or Papias of Hierapolis was a Greek Apostolic Father, Bishop of Hierapolis, and author who lived c. AD 65 – c. 140. He is mainly known for gathering oral stories about Jesus and his disciples from John the Elder and the daughters of Philip. Papias compiled these in the Exposition of the Sayings of the Lord, of which brief excerpts appear in the works of Irenaeus of Lyons and Eusebius of Caesarea. A scholarly consensus dates his work to around 110 AD They are considered an important early source on Christian oral tradition and especially on the origins of the canonical Gospels.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/11457c.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/papias","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/58972","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Papias%20of%20Hierapolis%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Papias_of_Hierapolis","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Papias.png","license":"Public domain","artist":"Michel Wolgemut, Wilhelm Pleydenwurff (Text: Hartmann Schedel )","pd":1}},"hermas":{"extract":"The Shepherd of Hermas, sometimes just called The Shepherd, is a Christian literary work of the late first half of the second century, considered a valuable book by many Christians, but not considered canonical scripture by the early Church Fathers such as Irenaeus. The Shepherd was popular among Christians in the 2nd, 3rd, and 4th centuries. It is found in the Codex Sinaiticus. The Muratorian fragment identifies the author of The Shepherd as Hermas, the brother of Pope Pius I. The Muratorian fragment also explicitly states that The Shepherd of Hermas is useful for private reading but not to b","qidWork":"Q898808","links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/07268b.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/hermas","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Hermas%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/The_Shepherd_of_Hermas","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Codex_Tchacos_p33.jpg","license":"Public domain","artist":"WolfgangRieger","pd":1}},"justin-martyr":{"extract":"Justin Martyr, also known as Justin the Philosopher, was an early Christian apologist and philosopher. The First Apology, his most well-known text, passionately defends the morality of the Christian life and provides various arguments to convince the Roman emperor Antoninus Pius to abandon persecution of the Church. Justin also indicates that historical manifestations of the Logos predated Christ's incarnation, and that many historical Greek philosophers were unknowing Christians.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/08580c.htm","kind":"about"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Justin%20Martyr%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Justin_Martyr","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Saint_Justin_Martyr_by_Theophanes_the_Cretan.jpg","license":"Public domain","artist":"Theophanes the Cretan","pd":1}},"irenaeus-of-lyons":{"extract":"Irenaeus of Lyon was a Greek bishop in the second century, noted for his role in guiding and expanding Christian communities in the southern regions of present-day France and, more widely, for the development of Christian theology by opposing Gnostic interpretations of Christian Scripture and defending orthodoxy. Originating from Smyrna, he had seen and heard the preaching of Polycarp, who in turn was said to have heard John the Evangelist.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/08130b.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/irenaeus","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Irenaeus%20of%20Lyons%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Irenaeus","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Saint_irenee_saint_irenee.jpg","license":"Public domain","artist":"Lucien Bégule","pd":1}},"athenagoras-of-athens":{"extract":"Athenagoras was an Ante-Nicene Church Father, a Christian apologist who lived during the second half of the 2nd century of whom little is known for certain, besides that he was Athenian, a philosopher, and a convert to Christianity.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/02042b.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/athenagoras","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Athenagoras%20of%20Athens%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Athenagoras_of_Athens","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Greek_Icon_of_Saint_Athenagoras_of_Athens.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"theophilus-of-antioch":{"extract":"Theophilus of Antioch was Patriarch of Antioch from 169 until 183. He succeeded Eros of Antioch c. 169, and was succeeded by Maximus I c. 183, according to Henry Fynes Clinton, but these dates are only approximations. His death probably occurred between 183 and 185.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/14625a.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/theophilus","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Theophilus%20of%20Antioch%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Theophilus_of_Antioch","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Theophilus_Antiochenus.png","license":"Public domain","artist":"William Cave","pd":1}},"tatian":{"extract":"Tatian of Adiabene, or Tatian the Syrian or Tatian the Assyrian, was an Assyrian Christian writer and theologian of the 2nd century.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/14464b.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/tatian","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Tatian%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Tatian","kind":"about"}]},"clement-of-alexandria":{"extract":"Titus Flavius Clemens, also known as Clement of Alexandria, was a Christian theologian and philosopher who taught at the Catechetical School of Alexandria. Among his pupils were Origen and Alexander of Jerusalem. A convert to Christianity, he was an educated man who was familiar with classical Greek philosophy and literature. As his three major works demonstrate, Clement was influenced by Hellenistic philosophy to a greater extent than any other Christian thinker of his time, and in particular, by Plato and the Stoics. His secret works, which exist only in fragments, suggest that he was famili","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/04045a.htm","kind":"about"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/56466","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Clement%20of%20Alexandria%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Clement_of_Alexandria","kind":"about"}],"isidoreFolder":"Clement of Alexandria, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Clement_alexandrin.jpg","license":"Public domain","artist":"André Thévet","pd":1}},"tertullian":{"extract":"Tertullian was a prolific early Christian author from Carthage in the Roman province of Africa. He was the first Christian author to produce an extensive corpus of Latin Christian literature and was an early Christian apologist and a polemicist against what he viewed as heresy, including Gnosticism.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/14520c.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/tertullian","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Tertullian%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Tertullian","kind":"about"}],"isidoreFolder":"Tertullian","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Tertullian2.png","license":"Public domain","artist":"André Thevet","pd":1}},"hippolytus-of-rome":{"extract":"Hippolytus of Rome was one of the most important Christian thinkers of the second and third centuries, though his provenance, identity, and corpus remain elusive to scholars and historians. Suggested communities include Rome, Palestine, Egypt, Anatolia, and other regions of the Middle East. The best historians of literature in the ancient church, including Eusebius and Jerome, openly admit they cannot name where Hippolytus the biblical commentator and theologian served in leadership. They had read his works but did not possess evidence of his community. Photios I of Constantinople describes hi","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/07360c.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/hippolytus","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Hippolytus%20of%20Rome%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hippolytus_of_Rome","kind":"about"}],"isidoreFolder":"Hippolytus","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Statue_of_Saint_.Hippolytus_%28cropped%29.jpg","license":"CC BY-SA 4.0","artist":"Dobroš © Dana Stehlíková","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3d/Statue_of_Saint_.Hippolytus_%28cropped%29.jpg/330px-Statue_of_Saint_.Hippolytus_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"origen":{"extract":"Origen of Alexandria, also known as Origen Adamantius, was an early Christian theologian and ascetic. He was a prolific writer who wrote roughly 2,000 treatises in multiple branches of theology, including textual criticism, biblical exegesis and hermeneutics, homiletics, and spirituality. He was one of the most influential and controversial figures in early Christian theology, apologetics, and asceticism. He has been described by John Anthony McGuckin as \"the greatest genius the early church ever produced\".","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/11306b.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/origen","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/53332","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Origen%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Origen","kind":"about"}],"isidoreFolder":"Origen","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Origen3.jpg","license":"Public domain","pd":1}},"cyprian-of-carthage":{"extract":"Cyprian was a bishop of Carthage and an early Christian writer of Berber descent, many of whose Latin works are extant. He is recognized as a saint in the Western and Eastern churches.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/04583b.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/cyprian","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Cyprian%20of%20Carthage%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Cyprian","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Cyprian_von_Karthago2.jpg","license":"Public domain","artist":"The original uploader was Bwag at German Wikipedia","pd":1}},"novatian":{"extract":"Novatian was a scholar, priest, and theologian. He is considered to have been an antipope between 251 and 258. Some Greek authors give his name as Novatus, who was an African presbyter.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/11138a.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/novatian","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Novatian%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Novatian","kind":"about"}]},"gregory-thaumaturgus":{"extract":"Gregory Thaumaturgus or Gregory the Miracle-Worker, also known as Gregory of Neocaesarea, was a Christian bishop of the 3rd century. He has been canonized as a saint in the Catholic and Orthodox Churches.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/07015a.htm","kind":"about"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Gregory%20Thaumaturgus%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gregory_Thaumaturgus","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Grigorii_chudotvoretz.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"dionysius-of-alexandria":{"extract":"Dionysius the Great was the 14th Pope and Patriarch of Alexandria from 28 December 248 until his death on 22 March 264. Most information known about him comes from a large corpus of correspondence. Only one complete letter survives; the remaining letters are excerpted in the works of Eusebius.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/05011a.htm","kind":"about"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/38337","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Dionysius%20of%20Alexandria%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Dionysius_of_Alexandria","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Dionisii_alek.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"methodius-of-olympus":{"extract":"Methodius of Olympus was an early Christian bishop, ecclesiastical author, and martyr. Today, he is honored as a saint and Church Father; the Catholic Church commemorates his feast on June 20.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/methodius","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Methodius%20of%20Olympus%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Methodius_of_Olympus","kind":"about"}],"isidoreFolder":"Methodius of Olympus, St., -311","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Methodius_of_Olympus.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"lactantius":{"extract":"Lucius Caecilius Firmianus Lactantius was an early Christian author who became an advisor to Roman emperor Constantine I, guiding his Christian religious policy in its initial stages of emergence, and a tutor to his son Crispus. His most important work is the Institutiones Divinae, an apologetic treatise intended to establish the reasonableness and truth of Christianity to pagan critics.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/08736a.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/lactantius","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Lactantius%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Lactantius","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Lactantius.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"arnobius-of-sicca":{"extract":"Arnobius was an early Christian apologist of Berber origin during the reign of Diocletian (284–305).","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/01746c.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/arnobius","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Arnobius%20of%20Sicca%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Arnobius","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:%D0%90%D1%80%D0%BD%D0%BE%D0%B1%D0%B8%D0%B9_%D0%A1%D1%82%D0%B0%D1%80%D1%88%D0%B8%D0%B9_-Arnobius_of_Sicca.jpg","license":"Public domain","artist":"Schedel H.","pd":1}},"minucius-felix":{"extract":"Marcus Minucius Felix was a Roman legal practitioner and one of the earliest Latin apologists for Christianity.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/10336a.htm","kind":"about"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Minucius%20Felix%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Marcus_Minucius_Felix","kind":"about"}]},"eusebius-of-caesarea":{"extract":"Eusebius of Caesarea, also known as Eusebius Pamphilius, was a historian of Christianity, exegete, and Christian polemicist from the Roman province of Syria Palaestina. In about AD 314 he became the bishop of Caesarea Palaestina.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/05617b.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/eusebius","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Eusebius%20of%20Caesarea%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Eusebius","kind":"about"}],"isidoreFolder":"Eusebius of Caesarea","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Eusebius_of_Caesarea_Rabbula_Gospels_Icon.jpg","license":"Public domain","artist":"Unknown, the art is from the 6th Century AD","pd":1}},"athanasius-of-alexandria":{"extract":"Athanasius I of Alexandria, also called Athanasius the Great, Athanasius the Confessor, or, among Coptic Christians, Athanasius the Apostolic, was a Christian theologian and the 20th Patriarch of Alexandria. His intermittent episcopacy spanned 45 years.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/02035a.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/athanasius","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/35906","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Athanasius%20of%20Alexandria%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Athanasius_of_Alexandria","kind":"about"}],"isidoreFolder":"Athanasius, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Fethiye_Camii%2C_parekklesion%2C_diakonikon%2C_mosaics%2C_Istanbul%2C_Turkey_-_South_wall%2C_St._Athanasius%2C_detail_of_upper_half_-_MSBZ004_BF_T_F_027_B_-_Dumbarton_Oaks.jpg","license":"CC0","artist":"Byzantine Institute staff","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","pd":1}},"hilary-of-poitiers":{"extract":"Hilary of Poitiers or St Hilarius was Bishop of Poitiers and a Doctor of the Church. He was sometimes referred to as the \"Hammer of the Arians\" and the \"Athanasius of the West\". His name comes from the Latin word for happy or cheerful. Prior to his conversion to Christianity, Hilary married someone, and then fathered Abra of Poitiers, a nun and saint who became known for her charity.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/07349b.htm","kind":"about"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/25706","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Hilary%20of%20Poitiers%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hilary_of_Poitiers","kind":"about"}],"isidoreFolder":"Hilary of Poitiers, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Hilaryofpoitiers.jpg","license":"Public domain","artist":"Richard de Montbaston et collaborateurs.","pd":1}},"ephrem-the-syrian":{"extract":"Ephrem the Syrian, also known as Ephraem the Deacon, Ephrem of Edessa or Aprem of Nisibis was a prominent Christian theologian and writer who is revered as one of the most notable hymnographers and authors of Syriac literature in Eastern Christianity. He was born in Nisibis, served as a deacon and later lived in Edessa.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/05498a.htm","kind":"about"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Ephrem%20the%20Syrian%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ephrem_the_Syrian","kind":"about"}],"isidoreFolder":"Ephraem, Syrus, Saint, 303-373","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Mor_Ephrem_icon.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"cyril-of-jerusalem":{"extract":"Cyril of Jerusalem was a theologian of the Early Church. About the end of AD 350, he succeeded Maximus as Bishop of Jerusalem, but was exiled on more than one occasion due to the enmity of Acacius of Caesarea, and the policies of various emperors. Cyril left important writings documenting the instruction of catechumens and the order of the Liturgy in his day.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/04595b.htm","kind":"about"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Cyril%20of%20Jerusalem%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Cyril_of_Jerusalem","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Saint_Cyril_of_Jerusalem.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"basil-the-great":{"extract":"Basil of Caesarea, also called Saint Basil the Great, was an early Christian prelate. He served as Bishop of Caesarea Mazaca in Cappadocia from 370 until his death in 379. He was an influential theologian who supported the Nicene Creed and opposed heresies within the early Christian church such as Arianism and Apollinarianism.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/02330b.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/basil","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Basil%20the%20Great%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Basil_of_Caesarea","kind":"about"}],"isidoreFolder":"Basil the Great, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Basil_of_Caesarea.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"gregory-of-nazianzus":{"extract":"Gregory of Nazianzus, also known as  Saint Gregory the Theologian or Gregory Nazianzen, was an early Roman Christian theologian and prelate who served as Archbishop of Constantinople from 380 to 381. He is widely considered the most accomplished rhetorical stylist of the patristic age. As a classically trained orator and philosopher, he infused Hellenism into the early Church, establishing the paradigm of Byzantine theologians and church officials.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/07010b.htm","kind":"about"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Gregory%20of%20Nazianzus%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gregory_of_Nazianzus","kind":"about"}],"isidoreFolder":"Gregory of Naziansus, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Gregor-Chora_%28cropped%29.jpg","license":"Copyrighted free use","artist":"Author unknown"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Gregor-Chora_%28cropped%29.jpg/330px-Gregor-Chora_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"gregory-of-nyssa":{"extract":"Gregory of Nyssa, also known as Gregory Nyssen, was an early Christian theologian who served as the bishop of Nyssa from 372 to 376 and from 378 until his death in 394. He is venerated as a saint in Eastern Orthodoxy, the Catholic Church, Oriental Orthodox Churches, Anglicanism, and Lutheranism. Gregory, his elder brother Basil of Caesarea, and their friend Gregory of Nazianzus are collectively known as the Cappadocian Fathers.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/07016a.htm","kind":"about"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Gregory%20of%20Nyssa%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gregory_of_Nyssa","kind":"about"}],"isidoreFolder":"Gregory of Nyssa, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Gregory_of_Nyssa.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"ambrose-of-milan":{"extract":"Ambrose of Milan, canonized as Saint Ambrose, was a Roman theologian, statesman, preacher, and Bishop of Milan from 374 until his death. Trained in rhetoric and law, he served as Roman civil governor of Aemilia-Liguria at Milan before being unexpectedly chosen as bishop by popular acclamation in 374. His preaching, ecclesiastical activity, and writings made him one of the most influential Christian figures of the 4th century.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/01383c.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/ambrose","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/25543","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Ambrose%20of%20Milan%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ambrose","kind":"about"}],"isidoreFolder":"Ambrose, St., c. 340-397","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:AmbroseOfMilan_%28cropped%29.jpg","license":"Public domain","pd":1}},"jerome":{"extract":"Jerome of Stridon, also known as Hieronymus, was an early Christian priest, confessor, theologian, translator, and historian; he is commonly known as Saint Jerome.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/08341a.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/jerome","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jerome%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jerome","kind":"about"}],"isidoreFolder":"Jerome, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:MatthiasStom-SaintJerome-Nantes.jpg","license":"Public domain","artist":"Matthias Stom","pd":1}},"john-chrysostom":{"extract":"John Chrysostom was a Church Father who served as Archbishop of Constantinople. He is known for his preaching and public speaking, particularly on the poor, his Divine Liturgy of Saint John Chrysostom, and his ascetic sensibilities.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/08452b.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/chrysostom","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/51945","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22John%20Chrysostom%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Chrysostom","kind":"about"}],"isidoreFolder":"Chrysostom, John, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Johnchrysostom.jpg","license":"Public domain","pd":1}},"augustine-of-hippo":{"extract":"Augustine of Hippo, also well-known as Saint Augustine, was a Christian theologian and philosopher from Thagaste, Numidia Cirtensis and the Bishop of Hippo Regius. He is generally regarded as one of the most influential philosophers in the history of the Western world, and is viewed as one of the most important Church Fathers of the Latin Church in the Patristic Period.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/02084a.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/augustine","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/1156","kind":"read"},{"label":"Augustinus.it Opera Omnia","url":"https://www.augustinus.it/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Augustine%20of%20Hippo%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Augustine_of_Hippo","kind":"about"},{"label":"Augustinus.it (archived copy, if the site is down)","url":"https://web.archive.org/web/20261005034602/https://www.augustinus.it/","kind":"site"}],"isidoreFolder":"Augustine, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Saint_Augustine_by_Philippe_de_Champaigne.jpg","license":"Public domain","artist":"Philippe de Champaigne","pd":1}},"cyril-of-alexandria":{"extract":"Cyril of Alexandria was a Christian theologian and Patriarch of Alexandria from 412 to 444.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/cyril","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Cyril%20of%20Alexandria%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Cyril_of_Alexandria","kind":"about"}],"isidoreFolder":"Cyril of Alexandria, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Chora-Kirche_2013-03-21zh_%28cropped%29.jpg","license":"CC BY-SA 4.0","artist":"Rabe!","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/Chora-Kirche_2013-03-21zh_%28cropped%29.jpg/330px-Chora-Kirche_2013-03-21zh_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"leo-the-great":{"extract":"Pope Leo I, also known as Leo the Great, was Bishop of Rome from 29 September 440 until his death on 10 November 461.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/09154b.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/leo","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Leo%20the%20Great%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pope_Leo_I","kind":"about"}],"isidoreFolder":"Leo the Great, Pope St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Herrera_mozo_San_Le%C3%B3n_magno_Lienzo._%C3%93valo._164_x_105_cm._Museo_del_Prado.png","license":"Public domain","artist":"Francisco Herrera the Younger","pd":1}},"peter-chrysologus":{"extract":"Peter Chrysologus was an Italian Christian prelate who served as Bishop of Ravenna from about 433 until his death. He is known as the \"Doctor of Homilies\" for the concise but theologically rich reflections he delivered during his time as the Bishop of Ravenna.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Peter%20Chrysologus%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Peter_Chrysologus","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Saint_Peter_Chrysologus.jpg","license":"Public domain","artist":"School of Guercino","pd":1}},"ambrosiaster":{"extract":"Ambrosiaster or Pseudo-Ambrose is the name given to the unknown author of a commentary on the epistles of Saint Paul, written some time between 366 and 384 AD. The name \"Ambrosiaster\" in Latin means \"would-be Ambrose\". Various conjectures have been made as to Ambrosiaster's true identity, and several other works have been attributed to the same author, with varying degrees of certainty.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Ambrosiaster%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ambrosiaster","kind":"about"}],"isidoreFolder":"Ambrosiaster"},"rufinus-of-aquileia":{"extract":"Tyrannius Rufinus, also called Rufinus of Aquileia, was an early Christian monk, philosopher, historian, and theologian who worked to translate Greek patristic material, especially the work of Origen, into Latin.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/rufinus","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Rufinus%20of%20Aquileia%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Tyrannius_Rufinus","kind":"about"}],"isidoreFolder":"Rufinus of Aquileia","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Rufinus_Aquileiensis.jpg","license":"Public domain","artist":"Bloemaert, Frederick (Bloemaert, Frederick) From: 1614— To: 1669","pd":1}},"sulpicius-severus":{"extract":"Sulpicius Severus was a Christian writer and native of Aquitania, in what is now France. He is known for his chronicle of sacred history, as well as his biography of Saint Martin of Tours.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/14332a.htm","kind":"about"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Sulpicius%20Severus%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Sulpicius_Severus","kind":"about"}]},"paulinus-of-nola":{"extract":"Paulinus of Nola born Pontius Meropius Anicius Paulinus, was a Roman poet, writer, senator, and bishop. He attained the ranks of suffect consul and governor of Campania, but, prompted by the counsels of his Hispanic wife Therasia of Nola and by the assassination of the emperor Gratian, abandoned his career and was baptized as a Christian. Later, probably after Therasia's death, he became bishop of Nola in Campania. While there, he wrote poems in honor of his predecessor Saint Felix and corresponded with other Christian leaders throughout the empire. He is credited with the introduction of bell","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Paulinus%20of%20Nola%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Paulinus_of_Nola","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Linzer_Dom_-_Fenster_-_Paulinus_von_Nola.jpg","license":"CC BY-SA 3.0","artist":"Wolfgang Sauber","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Linzer_Dom_-_Fenster_-_Paulinus_von_Nola.jpg/330px-Linzer_Dom_-_Fenster_-_Paulinus_von_Nola.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"prudentius":{"extract":"Aurelius Prudentius Clemens was a Roman Christian poet, born in the Roman province of Tarraconensis in 348. He probably died in the Iberian Peninsula some time after 405, possibly around 413. The place of his birth is uncertain, but it may have been Caesaraugusta (Zaragoza), Tarraco (Tarragona), or Calagurris (Calahorra).","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/prudentius","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/5755","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Prudentius%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Prudentius","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:BLAdd24199PrudentiusFol11v.jpg","license":"Public domain","pd":1}},"vincent-of-lerins":{"extract":"Vincent of Lérins was a Gallic monk and author of early Christian writings. One example was the Commonitorium, c. 434, which offers guidance in the orthodox teaching of Christianity. Suspected of semi-Pelagianism, he opposed the Augustinian model of grace and was probably the recipient of Prosper of Aquitaine's Responsiones ad Capitula Objectionum Vincentianarum. His feast day is celebrated on 24 May.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/15439b.htm","kind":"about"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Vincent%20of%20L%C3%A9rins%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Vincent_of_L%C3%A9rins","kind":"about"}],"isidoreFolder":"Vincent of Lerins, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Icon_of_St_Vincent_of_Lerins_by_Bojan_Teodosijevi%C4%87.jpg","license":"CC BY 4.0","artist":"Bojan Teodosijević","licenseUrl":"https://creativecommons.org/licenses/by/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/Icon_of_St_Vincent_of_Lerins_by_Bojan_Teodosijevi%C4%87.jpg/330px-Icon_of_St_Vincent_of_Lerins_by_Bojan_Teodosijevi%C4%87.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"prosper-of-aquitaine":{"extract":"Prosper of Aquitaine, also called Prosper Tiro, was a Christian writer and disciple of Augustine of Hippo, and the first continuator of Jerome's Universal Chronicle. Particularly, Prosper is identified with the (later) axiom 'lex orandi, lex credendi, lex vivendi'—'the law [or those things] we pray is the law we believe is the law we live.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Prosper%20of%20Aquitaine%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Prosper_of_Aquitaine","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Aquit%C3%A1niai_Szent_Prosper.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"theodoret-of-cyrrhus":{"extract":"Theodoret of Cyrus or Cyrrhus was a notable theologian of the School of Antioch, biblical commentator, and bishop of Cyrrhus (423–457). He participated in several 5th-century Christological controversies within the Eastern Roman Church that resulted in various ecumenical acts and schisms. Theodoret wrote against Cyril of Alexandria's Twelve Anathemas, which were sent to Nestorius, and did not condemn Nestorius until the Council of Chalcedon. Selected writings by Theodoret directed against Cyril formed part of the subject matter of the Three Chapters Controversy and were condemned posthumously ","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/14574b.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/theodoret","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Theodoret%20of%20Cyrrhus%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Theodoret","kind":"about"}],"isidoreFolder":"Theodoret of Cyrus","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Theodoret_of_Cyr_%28in_A._Thevet1584%29.png","license":"CC BY-SA 4.0","artist":"Jutory","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/Theodoret_of_Cyr_%28in_A._Thevet1584%29.png/330px-Theodoret_of_Cyr_%28in_A._Thevet1584%29.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"socrates-scholasticus":{"extract":"Socrates of Constantinople, also known as Socrates Scholasticus, was a 5th-century Greek Christian church historian, a contemporary of Sozomen and Theodoret.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/14118b.htm","kind":"about"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Socrates%20Scholasticus%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Socrates_of_Constantinople","kind":"about"}]},"sozomen":{"extract":"Salamanes Hermias Sozomenos, also known as Sozomen, was a Byzantine Empire era lawyer and historian of the Christian Church.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/14165c.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/sozomen","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Sozomen%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Sozomen","kind":"about"}]},"aphrahat":{"extract":"Aphrahat, venerated as Saint Aphrahat the Persian, was a third-century Syriac Christian author of Iranian descent from the Sasanian Empire, who composed a series of twenty-three expositions or homilies on points of Christian doctrine and practice. All his known works, the Demonstrations, come from later on in his life. He was an ascetic and celibate, and was almost definitely a son of the covenant. He may have been a bishop, and later Syriac tradition places him at the head of Mar Mattai Monastery near Mosul in what is now northern Iraq. He was a near contemporary to the slightly younger Ephre","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/01593c.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/aphrahat","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Aphrahat%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Aphrahat","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Les_Vies_des_P%C3%A8res_des_d%C3%A9serts_d%27Orient_-_leur_doctrine_spirituelle_et_leur_discipline_monastique_%281886%29_%2814590545527%29.jpg","license":"No restrictions","artist":"Internet Archive Book Images","licenseUrl":"https://www.flickr.com/commons/usage/","pd":1}},"epiphanius-of-salamis":{"extract":"Epiphanius of Salamis was the bishop of Salamis, Cyprus, at the end of the 4th century. He is considered a saint and a Church Father by the Eastern Orthodox, Catholic Churches, and some Presbyterians. He gained a reputation as a strong defender of orthodoxy. He is best known for composing the Panarion, a compendium of eighty heresies, which also included pagan religions and philosophical systems. There has been much controversy over how many of the quotations attributed to him by the Byzantine Iconoclasts were actually by him. Regardless of this, he was clearly strongly against some contempora","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/epiphanius","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Epiphanius%20of%20Salamis%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Epiphanius_of_Salamis","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Epiphanius-Kosovo.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"john-cassian":{"extract":"John Cassian, also known as John the Ascetic and John Cassian the Roman, was a Christian monk and theologian celebrated in both the Western and Eastern churches for his mystical writings. Cassian is noted for his role in bringing the ideas and practices of early Christian monasticism to the medieval West.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/03404a.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/cassian","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22John%20Cassian%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Cassian","kind":"about"}],"isidoreFolder":"Cassian, John, 360-435","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:John_Cassian.jpeg","license":"Public domain","artist":"Author unknown","pd":1}},"antony-the-great":{"extract":"Anthony the Great was a Christian monk from Egypt, revered since his death as a saint. He is distinguished from other saints named Anthony, such as Anthony of Padua, by various epithets: Anthony of Egypt, Anthony the Abbot, Anthony of the Desert, Anthony the Anchorite, Anthony the Hermit, and Anthony of Thebes. For his importance among the Desert Fathers and to all later Christian monasticism, he is also known as the Father of All Monks. His feast day is celebrated on 17 January among the Eastern Orthodox and Catholic churches and on Tobi 22 in the Coptic calendar.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Antony%20the%20Great%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Anthony_the_Great","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Saint_Anthony_%28Damaskinos%29.png","license":"Public domain","artist":"Michael Damaskinos","pd":1}},"pachomius":{"extract":"Pachomius, also known as Saint Pachomius the Great, is generally recognized as the founder of Christian cenobitic monasticism. \nIn the Vita Pachumii, his name is recorded as Pachumius (Παχούμιος). Coptic churches celebrate his feast day on 9 May, and Eastern Orthodox and Catholic churches mark his feast on 15 May or 28 May. In Lutheranism, he is remembered as a renewer of the church, along with his contemporary, Anthony of Egypt on 17 January.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Pachomius%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pachomius_the_Great","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:StPakhom.jpg","license":"Public domain","pd":1}},"evagrius-ponticus":{"extract":"Evagrius Ponticus ; also called Evagrius the Solitary, was a Christian monk and ascetic from Heraclea, a city on the coast of Bithynia in Asia Minor. One of the most influential theologians in the late fourth-century church, he was well known as a thinker, polished speaker, and gifted writer. He left a promising ecclesiastical career in Constantinople and traveled to Jerusalem, where in 383 AD he became a monk at the monastery of Rufinus and Melania the Elder. He then went to Egypt and spent the remaining years of his life in Nitria and Kellia, marked by years of asceticism and writing. He was","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Evagrius%20Ponticus%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Evagrius_Ponticus","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Evagrius.jpg","license":"Public domain","artist":"Davidfmurphy at English Wikipedia","pd":1}},"macarius-of-egypt":{"extract":"Macarius of Egypt was an Egyptian Christian monk and grazer hermit. He is also known as Macarius the Elder or Macarius the Great.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Macarius%20of%20Egypt%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Macarius_of_Egypt","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Saint_Macarius_the_Egyptian.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"palladius-of-galatia":{"extract":"Palladius of Galatia was a Christian chronicler and the bishop of Helenopolis in Bithynia. He was a devoted disciple of Saint John Chrysostom. He is best remembered for his work, the Lausiac History. He was also the author of the Dialogue on the Life of Chrysostom.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Palladius%20of%20Galatia%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Palladius_of_Galatia","kind":"about"}]},"moses-the-black":{"extract":"Moses the Black, also known as Moses the Strong, Moses the Robber, and Moses the Nubian, was a Nubian ascetic hieromonk in Egypt in the fourth century AD, and a Desert Father. He is highly venerated in the Eastern Orthodox Church and the Oriental Orthodox Churches. According to stories about him, he converted from a life of crime to one of asceticism. He is mentioned in Sozomen's Ecclesiastical History, written about 70 years after Moses's death.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Moses%20the%20Black%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Moses_the_Black","kind":"about"}]},"syncletica-of-alexandria":{"extract":"Syncletica of Alexandria was a Christian saint, ascetic, anchorite, and Desert Mother from Roman Egypt in the 4th century AD. She is the subject of The Life of Syncletica, a Greek hagiography purportedly by Athanasius of Alexandria but not published until 450; and the Alphabetical and Systematic Apophthegmata, which included 28 of her sayings and teachings. She died at the age of 80, after a three-year-long illness from mouth cancer.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Syncletica%20of%20Alexandria%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Syncletica_of_Alexandria","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Righteous_Syncletica_of_Alexandria_%28Menologion_of_Basil_II%29.jpg","license":"Public domain","artist":"Authors of Menologion of Basil II (circa 985 AC, Constantinople), Byzantine manuscript illuminators : Pantoleon with Georgios, Michael the Younger, Michael of Blachernae, Symeon, Symeon of…","pd":1}},"john-climacus":{"extract":"John Climacus, also known as John of the Ladder, John Scholasticus and John Sinaites, was a 6th–7th century Christian monk at the monastery on Mount Sinai. He is revered as a saint by the Eastern Orthodox Church and Catholic Church.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/climacus","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22John%20Climacus%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Climacus","kind":"about"}],"isidoreFolder":"Climacus, John","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Lestvichnik.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"benedict-of-nursia":{"extract":"Benedict of Nursia, often known as Saint Benedict, was an Italian monk and the founder of the Order of Saint Benedict. He is famed in the Catholic Church, the Eastern Orthodox Church, the Lutheran Churches, the Anglican Communion, and Old Catholic Churches. In 1964, Pope Paul VI declared Benedict a patron saint of Europe.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/benedict","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Benedict%20of%20Nursia%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Benedict_of_Nursia","kind":"about"}],"isidoreFolder":"Benedict, St., Abbot of Monte Cassino","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Memling%2C_Trittico_di_Benedetto_Portinari%2C_San_Benedetto.jpg","license":"Public domain","artist":"Hans Memling","pd":1}},"boethius":{"extract":"Anicius Manlius Severinus Boethius, commonly known simply as Boethius, was a Roman senator, consul, magister officiorum, polymath, historian, and philosopher of the Early Middle Ages. He was a central figure in the translation of the Greek classics into Latin, a precursor to the Scholastic movement, and, along with Cassiodorus, one of the two leading Christian scholars of the 6th century. The local cult of Boethius in the Diocese of Pavia was sanctioned by the Sacred Congregation of Rites in 1883, confirming the diocese's custom of honoring him on 23 October.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/boethius","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/4992","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Boethius%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Boethius","kind":"about"}],"isidoreFolder":"Boethius, Anicius Manlius Severinus","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Boethius.jpeg","license":"Public domain","artist":"Author unknown","pd":1}},"cassiodorus":{"extract":"Magnus Aurelius Cassiodorus Senator, commonly known as Cassiodorus, was a Roman statesman, scholar, and writer who served in the administration of Theodoric the Great, king of the Ostrogoths. Senator was part of his surname, not his rank. In his later years, he devoted himself to Christian learning and founded the Vivarium monastery, where he worked extensively during the final decades of his life.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/8135","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Cassiodorus%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Cassiodorus","kind":"about"}],"isidoreFolder":"Cassiodorus","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Gesta_Theodorici_-_Flavius_Magnus_Aurelius_Cassiodorus_%28c_485_-_c_580%29.jpg","license":"Public domain","artist":"Fulda workshop","pd":1}},"pseudo-dionysius-the-areopagite":{"extract":"Pseudo-Dionysius the Areopagite, Dionysius the Pseudo-Areopagite or Pseudo-Denys is the pseudonymous name used by a Syrian or Greek monk, Christian theologian and Neoplatonic philosopher of the late 5th to early 6th century, who wrote a set of works known as the Corpus Areopagiticum or Corpus Dionysiacum. Through his writing in Mystical Theology, he has been identified as the \"progenitor of apophatic or negative theology.\"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Pseudo-Dionysius%20the%20Areopagite%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pseudo-Dionysius_the_Areopagite","kind":"about"}],"isidoreFolder":"Dionysius the Areopogita, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Plotin.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"gregory-the-great":{"extract":"Pope Gregory I, commonly known as Saint Gregory the Great, was the 64th Bishop of Rome from 3 September 590 until his death on 12 March 604.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/06780a.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/gregory","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Gregory%20the%20Great%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pope_Gregory_I","kind":"about"}],"isidoreFolder":"Gregory the Great, Pope St., O.S.B. (480-547)","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Gregory_the_Great_with_the_Holy_Spirit.jpg","license":"CC0","artist":"British Library","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","pd":1}},"gregory-of-tours":{"extract":"Gregory of Tours was a Gallo-Roman historian and Bishop of Tours during the Merovingian period and is known as the \"father of French history\".","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/57745","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Gregory%20of%20Tours%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gregory_of_Tours","kind":"about"}]},"isidore-of-seville":{"extract":"Isidore of Seville was a Hispano-Roman scholar, theologian and archbishop of Seville. He is widely regarded, in the words of the 19th-century historian Charles Forbes René de Montalembert, as \"the last scholar of the ancient world\".","qidWork":null,"links":[{"label":"isidore.co (named for him)","url":"https://isidore.co/calibre","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Isidore%20of%20Seville%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Isidore_of_Seville","kind":"about"}],"isidoreFolder":"Isidore of Seville, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Isidor_von_Sevilla.jpeg","license":"Public domain","artist":"Bartolomé Esteban Murillo","pd":1}},"maximus-the-confessor":{"extract":"Maximus the Confessor, also spelled Maximos, otherwise known as Maximus the Theologian and Maximus of Constantinople, was a Christian monk, theologian, and Neoplatonic scholar.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Maximus%20the%20Confessor%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Maximus_the_Confessor","kind":"about"}]},"columbanus":{"extract":"Columbanus was an Irish missionary notable for founding a number of monasteries after 590 in the Frankish and Lombard kingdoms, most notably Luxeuil Abbey in present-day France and Bobbio Abbey in present-day Italy. Columbanus taught an Irish monastic rule and penitential practices for those repenting of sins, which emphasised private confession to a priest, followed by penances imposed by the priest in reparation for the sins. Columbanus is one of the earliest identifiable Hiberno-Latin writers.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Columbanus%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Columbanus","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:San_Colombano.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"bede-the-venerable":{"extract":"Bede, OSB, also known as the Venerable Bede or Bede the Venerable, was an English Benedictine monk, author and scholar. He was one of the best known writers during the Early Middle Ages, and his most famous work, Ecclesiastical History of the English People, gained him the title \"The Father of English History\". He served at the monastery of St Peter and its companion monastery of St Paul in the Kingdom of Northumbria of the Angles.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/39416","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Bede%20the%20Venerable%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Bede","kind":"about"}],"isidoreFolder":"Bede, Venerable, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:E-codices_bke-0047_001v_medium_%28cropped%29.jpg","license":"Public domain","artist":"http://www.e-codices.unifr.ch/de/bke/0047/1v","pd":1}},"john-of-damascus":{"extract":"John of Damascus or John Damascene, born Yūḥana ibn Manṣūr ibn Sarjūn, was a Christian monk, priest, hymnographer, and apologist. He was born and raised in Damascus c. AD 675 or AD 676; the precise date and place of his death is not known, though tradition places it at his monastery, Mar Saba, near Jerusalem, on 4 December AD 749. A polymath whose fields of interest and contribution included law, theology, philosophy, and music, he was given the by-name of Chrysorroas. He wrote works expounding the Christian faith, and composed hymns which are still used both liturgically in Eastern Christian ","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/08459b.htm","kind":"about"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22John%20of%20Damascus%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_of_Damascus","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Athonite_Fresco_Icon_of_Saint_John_of_Damascus.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"alcuin-of-york":{"extract":"Alcuin of York, also called Ealhwine, Alhwin, or Alchoin, was an Anglo-Saxon scholar, clergyman, poet, and teacher from York, Northumbria, who was active in the Carolingian Empire in the 8th century. He was born around 735 and became the student of Archbishop Ecgbert at York. At the invitation of Charlemagne, he became a leading scholar and teacher at the Carolingian court, where he remained a figure in the 780s and 790s. Before that, he was also a court chancellor in Aachen. \"The most learned man anywhere to be found\", according to Einhard's Life of Charlemagne, he is considered among the mos","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Alcuin%20of%20York%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alcuin","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Raban-Maur_Alcuin_Otgar.jpg","license":"Public domain","artist":"Fulda","pd":1}},"rabanus-maurus":{"extract":"Rabanus Maurus Magnentius, also known as Hrabanus or Rhabanus, was a Frankish Benedictine monk, theologian, poet, encyclopedist and military writer who became archbishop of Mainz in East Francia. He was the author of the encyclopaedia De rerum naturis. He also wrote treatises on education and grammar and commentaries on the Bible. He was one of the most prominent teachers and writers of the Carolingian age, and was called \"Praeceptor Germaniae\", or \"the teacher of Germany\". In the most recent edition of the Roman Martyrology, his feast is given as 4 February and he is qualified as a Saint ('sa","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Rabanus%20Maurus%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Rabanus_Maurus","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Raban-Maur_Alcuin_Otgar.jpg","license":"Public domain","artist":"Fulda","pd":1}},"john-scotus-eriugena":{"extract":"John Scotus Eriugena, also known as Johannes Scotus Erigena, John the Scot or John the Irish-born, was an Irish Neoplatonic philosopher, theologian and poet of the Early Middle Ages. Bertrand Russell dubbed him \"the most astonishing person of the ninth century\". The Stanford Encyclopedia of Philosophy states that he \"is the most significant Irish intellectual of the early monastic period. He is generally recognized to be both the outstanding philosopher of the Carolingian era and of the whole period of Latin philosophy stretching from Boethius to Anselm\".","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22John%20Scotus%20Eriugena%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Scotus_Eriugena","kind":"about"}]},"paschasius-radbertus":{"extract":"Paschasius Radbertus (785–865) was a Carolingian theologian and the abbot of Corbie, a monastery in Picardy founded in 657 or 660 by the queen regent Bathilde with a founding community of monks from Luxeuil Abbey. His most well-known and influential work is an exposition on the nature of the Eucharist written around 831, entitled De Corpore et Sanguine Domini. He was canonized in 1073 by Pope Gregory VII. His feast day is 26 April.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Paschasius%20Radbertus%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Paschasius_Radbertus","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Abbatiale_Saint-Pierre_de_Corbie%2C_int%C3%A9rieur%2C_Paschase_Radbert_3.jpg","license":"CC BY-SA 4.0","artist":"Bycro","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/Abbatiale_Saint-Pierre_de_Corbie%2C_int%C3%A9rieur%2C_Paschase_Radbert_3.jpg/330px-Abbatiale_Saint-Pierre_de_Corbie%2C_int%C3%A9rieur%2C_Paschase_Radbert_3.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"gregory-of-narek":{"extract":"Grigor Narekatsi was an Armenian mystical and lyrical poet, monk, and theologian. He is venerated as a saint in the Armenian Apostolic and Catholic Churches and was declared a Doctor of the Church by Pope Francis in 2015.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Gregory%20of%20Narek%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gregory_of_Narek","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Grigor_Narekatsi_1.jpg","license":"Public domain","artist":"MarshallBagramyan","pd":1}},"peter-damian":{"extract":"Peter Damian was an Italian reforming Benedictine monk and cardinal in the circle of Pope Leo IX. Dante placed him in one of the highest circles of Paradiso as a great predecessor of Francis of Assisi and he was declared a Doctor of the Church on 27 September 1828. His feast day is 21 February.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/damian","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Peter%20Damian%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Peter_Damian","kind":"about"}],"isidoreFolder":"Damian, St. Peter","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Peter_Damian_bust.JPG","license":"CC BY 2.5","artist":"Srnec at English Wikipedia","licenseUrl":"https://creativecommons.org/licenses/by/2.5"},"img":"https://upload.wikimedia.org/wikipedia/commons/4/4e/Peter_Damian_bust.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled"},"anselm-of-canterbury":{"extract":"Anselm of Canterbury, also known as Anselm of Aosta after his birthplace and Anselm of Bec after his monastery, was a Benedictine abbot, philosopher and theologian who served as Archbishop of Canterbury from 1093 to 1109.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/anselm","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Anselm%20of%20Canterbury%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Anselm_of_Canterbury","kind":"about"}],"isidoreFolder":"Anselm, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Anselm_of_Canterbury%2C_seal.svg","license":"Public domain","artist":"Anselm_of_Canterbury,_seal.jpg : The original uploader was Srnec at English Wikipedia . derivative work: MLWatts","pd":1}},"bernard-of-clairvaux":{"extract":"Bernard of Clairvaux, O.Cist., venerated as Saint Bernard, was an abbot, mystic, co-founder of the Knights Templar, and a major leader in the reform of the Benedictines through the nascent Cistercian Order.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/bernard","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/9821","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Bernard%20of%20Clairvaux%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Bernard_of_Clairvaux","kind":"about"}],"isidoreFolder":"Bernard of Clairvaux, St., 1115-1153","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:San_Bernardo%2C_de_Juan_Correa_de_Vivar_%28Museo_del_Prado%29.jpg","license":"Public domain","pd":1}},"hugh-of-saint-victor":{"extract":"Hugh of Saint Victor was a German canon regular and a leading theologian and writer on mystical theology.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/hugh","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Hugh%20of%20Saint%20Victor%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hugh_of_Saint_Victor","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Hugostv.jpg","license":"Public domain","artist":"Bender235","pd":1}},"richard-of-saint-victor":{"extract":"Richard of Saint Victor was a Medieval Scottish philosopher and theologian and one of the most influential religious thinkers of his time. A canon regular, he was a prominent mystical theologian, and was prior of the famous Augustinian Abbey of Saint Victor in Paris from 1162 until his death in 1173.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/richard","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Richard%20of%20Saint%20Victor%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Richard_of_Saint_Victor","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Hugostv.jpg","license":"Public domain","artist":"Bender235","pd":1}},"peter-lombard":{"extract":"Peter Lombard was an Italian scholastic theologian, Bishop of Paris, and author of the Sentences, which became the standard medieval textbook of theology.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Peter%20Lombard%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Peter_Lombard","kind":"about"}],"isidoreFolder":"Lombardi, magistri Petri (Parisiensis episcopi)","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:PeterLombar01Medieval.png","license":"Public domain","artist":"Peter Lombard","pd":1}},"hildegard-of-bingen":{"extract":"Hildegard of Bingen, also known as the \"Sibyl of the Rhine\", was a German Benedictine abbess and polymath, active during the High Middle Ages as a writer, composer, philosopher, mystic, visionary, and as a medical writer. She is one of the best-known composers of sacred monophony, as well as the most recorded in modern history. A number of scholars have considered her to be the founder of scientific natural history in Germany.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Hildegard%20of%20Bingen%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hildegard_of_Bingen","kind":"about"}],"isidoreFolder":"Hildegard von Bingen, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Hildegard_von_Bingen.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"aelred-of-rievaulx":{"extract":"Aelred of Rievaulx, also known as Ailred, Ælred, or Æthelred; was an English Cistercian monk and writer who served as Abbot of Rievaulx from 1147 until his death. He is venerated by the Catholic Church as a saint and by some Anglicans.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/aelred","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Aelred%20of%20Rievaulx%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Aelred_of_Rievaulx","kind":"about"}],"isidoreFolder":"Aelred of Rievaulx","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:De_Speculo_Caritatis.jpeg","license":"Public domain","artist":"Elredo de Rieval, posiblemente","pd":1}},"william-of-saint-thierry":{"extract":"William of Saint-Thierry, O. Cist was a twelfth-century Benedictine, theologian and mystic from Liège who became abbot of Saint-Thierry in France, and later joined the Cistercian Order.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22William%20of%20Saint-Thierry%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/William_of_Saint-Thierry","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Signy-l%27Abbaye_%28Ardennes%29_%C3%A9glise%2C_vitrail_13.JPG","license":"CC0","artist":"Havang(nl)","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","pd":1}},"gratian":{"extract":"The Decretum Gratiani, also known as the Concordia discordantium canonum or Concordantia discordantium canonum or simply as the Decretum, is a collection of Catholic canon law compiled and written in the 12th century as a legal textbook by the jurist known as Gratian. It forms the first part of the collection of six legal texts, which together became known as the Corpus Juris Canonici.","qidWork":"Q1182119","links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Gratian%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Decretum_Gratiani","kind":"about"}],"isidoreFolder":"Gratian","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Cambrige%2C_Fitzwilliam_Museum_Ms._262_fol._71v_Decretum_-_Tree_of_Affinity.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"francis-of-assisi":{"extract":"Giovanni di Pietro di Bernardone, known as Saint Francis of Assisi, was an Italian mystic, poet and Catholic friar who founded the religious order of the Franciscans.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Francis%20of%20Assisi%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Francis_of_Assisi","kind":"about"}],"isidoreFolder":"Francis of Assisi, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:StFrancis_part.jpg","license":"Public domain","artist":"Parzi","pd":1}},"dominic-de-guzman":{"extract":"Dominic de Guzmán, almost exclusively known as Saint Dominic, was a Castilian religious priest and the founder of the Order of Preachers (Dominicans). He is the patron saint of astronomers and natural scientists, and he and the Dominicans are traditionally credited with spreading and popularizing the rosary.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Dominic%20de%20Guzm%C3%A1n%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Dominic_de_Guzm%C3%A1n","kind":"about"}],"isidoreFolder":"Dominic de Guzman, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:SaintDominic.jpg","license":"Public domain","artist":"Claudio Coello","pd":1}},"clare-of-assisi":{"extract":"Chiara Offreduccio, known as Clare of Assisi, is an Italian saint who was one of the first followers of Francis of Assisi.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Clare%20of%20Assisi%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Clare_of_Assisi","kind":"about"}],"isidoreFolder":"Clare, of Assisi, Saint, 1194-1253","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:SDamiano-Clara.jpg","license":"Public domain","artist":"Gunnar Bach Pedersen","pd":1}},"anthony-of-padua":{"extract":"Anthony of Padua or Anthony of Lisbon was a Portuguese Catholic priest and member of the Order of Friars Minor.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Anthony%20of%20Padua%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Anthony_of_Padua","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Francisco_de_Zurbar%C3%A1n_-_Sto_Antonio_de_Padua.jpg","license":"Public domain","artist":"Francisco de Zurbarán","pd":1}},"albert-the-great":{"extract":"Albertus Magnus, also known as Saint Albert the Great, Albert of Swabia, Albert von Bollstadt, or Albert of Cologne, was a German Dominican friar, philosopher, scientist, and bishop. He is considered one of the greatest medieval philosophers and thinkers.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/albert","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Albert%20the%20Great%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Albertus_Magnus","kind":"about"}],"isidoreFolder":"Albertus Magnus, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Vicente_salvador_gomez-san_alberto.jpg","license":"Public domain","artist":"Vicente Salvador Gómez","pd":1}},"thomas-aquinas":{"extract":"Thomas Aquinas was an Italian Dominican friar and priest, theologian, and philosopher. He is considered one of the most influential thinkers in the history of Catholic theology and Western philosophy. He is the father of a school of thought known as Thomism.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/aquinas","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/7489","kind":"read"},{"label":"isidore.co Aquinas in English","url":"https://isidore.co/aquinas/","kind":"site"},{"label":"Corpus Thomisticum (Latin)","url":"https://www.corpusthomisticum.org/","kind":"site"},{"label":"Aquinas Institute (Latin/English)","url":"https://aquinas.cc/la/en/~ST.I","kind":"site"},{"label":"Summa Theologiae — New Advent","url":"https://www.newadvent.org/summa/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Thomas%20Aquinas%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Thomas_Aquinas","kind":"about"}],"isidoreFolder":"Aquinas, St. Thomas","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:St-thomas-aquinasFXD.jpg","license":"Public domain","artist":"Carlo Crivelli","pd":1}},"bonaventure":{"extract":"Bonaventure was an Italian Catholic Franciscan bishop, cardinal, scholastic theologian and philosopher.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/bonaventure","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Bonaventure%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Bonaventure","kind":"about"}],"isidoreFolder":"Bonaventure of Bagnoregio, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Fran%C3%A7ois%2C_Claude_%28dit_Fr%C3%A8re_Luc%29_-_Saint_Bonaventure.jpg","license":"Public domain","artist":"Claude François","pd":1}},"robert-grosseteste":{"extract":"Robert Grosseteste, also known as Robert Greathead or Robert of Lincoln, was an English statesman, scholastic philosopher, theologian, scientist and Bishop of Lincoln. He was born of humble parents in Suffolk, but the association with the village of Stradbroke is a post-medieval tradition. Upon his death, he was revered as a saint in England, but attempts to procure a formal canonisation failed. A. C. Crombie called him \"the real founder of the tradition of scientific thought in medieval Oxford, and in some ways, of the modern English intellectual tradition\". As a theologian, however, he contr","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Robert%20Grosseteste%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Robert_Grosseteste","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Grosseteste_bishop.jpg","license":"Public domain","artist":"Unknown 14th century scribe","pd":1}},"roger-bacon":{"extract":"Roger Bacon, also known by the scholastic accolade Doctor Mirabilis, was a medieval English polymath, philosopher, scientist, theologian and Franciscan friar who placed considerable emphasis on the study of nature through empiricism. Intertwining his Catholic faith with scientific thinking, Roger Bacon is considered one of the greatest polymaths of the medieval period.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/49923","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Roger%20Bacon%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Roger_Bacon","kind":"about"}]},"ramon-llull":{"extract":"Ramon Llull, sometimes anglicized as Raymond Lully, was a Catholic philosopher, theologian, poet, missionary, apologist and former knight, born in Palma de Mallorca. He invented a philosophical system known as the Art, conceived as a type of universal logic to prove the truth of Christian doctrine to interlocutors of all faiths and nationalities. The Art consists of a set of general principles and combinatorial operations. It is illustrated with diagrams.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/42156","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Ramon%20Llull%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ramon_Llull","kind":"about"}],"isidoreFolder":"Llull, Ramon, 1232_-1316","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Francisco_Ribalta_-_Ramon_Llull_-_Google_Art_Project.jpg","license":"Public domain","artist":"Francesc Ribalta","pd":1}},"duns-scotus":{"extract":"John Duns Scotus was a Scottish Catholic priest and Franciscan friar, university professor, philosopher and theologian. He is considered among the most important philosopher-theologians in Western Christendom during the last part of the medieval period, together with Thomas Aquinas, Bonaventure and William of Ockham. The intellectual tradition derived from Scotus's work is called Scotism.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/scotus","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Duns%20Scotus%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Duns_Scotus","kind":"about"}],"isidoreFolder":"Duns Scotus, John, ca. 1266-1308","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Dr._Duns_Scotus_and_the_Immaculate_Conception%3B_attr._Manuel_Pereira_de_Brito%2C_c._1700.jpg","license":"Public domain","artist":"Manuel Pereira de Brito, c. 1700","pd":1}},"william-of-ockham":{"extract":"William of Ockham or Occam was an English Franciscan friar, scholastic philosopher and theologian. He is considered to be one of the major figures of medieval thought and was at the centre of the major intellectual and political controversies of the 14th century. The nominalists of the fifteenth century regarded him as one of the founders of their movement. He is widely known for Occam's razor, the methodological principle that bears his name. He produced significant works on logic, physics and theology. Ockham is remembered in the Church of England with a commemoration corresponding to the co","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/william","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22William%20of%20Ockham%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/William_of_Ockham","kind":"about"}],"isidoreFolder":"Ockham, William","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:William_of_Ockham.png","license":"CC BY-SA 3.0","artist":"self-created (Moscarlop)","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},"img":"https://upload.wikimedia.org/wikipedia/commons/7/70/William_of_Ockham.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled"},"jacobus-de-voragine":{"extract":"Jacobus de Voragine, OP was an Italian chronicler and archbishop of Genoa. He was the author, or more accurately the compiler, of the Golden Legend, a collection of the legendary lives of the greater saints of the medieval church that was one of the most popular religious works of the Middle Ages.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/voragine","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/43921","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jacobus%20de%20Voragine%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jacobus_de_Voragine","kind":"about"}],"isidoreFolder":"de Voragine, Jacobus, O.P_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:PalazzoTrinci010_%28cropped%29.jpg","license":"Public domain","artist":"Georges Jansoone ( JoJan )","pd":1}},"dante-alighieri":{"extract":"Dante Alighieri, widely known mononymously as Dante, was an Italian poet, writer, and philosopher. His Divine Comedy, originally called Comedìa and later christened Divina by Giovanni Boccaccio, is widely considered one of the most important poems of the Middle Ages and the greatest literary work in the Italian language.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/507","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Dante%20Alighieri%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Dante_Alighieri","kind":"about"}],"isidoreFolder":"Alighieri, Dante","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Bargello_-_Kapelle_Fresko_2a.jpg","license":"CC BY-SA 3.0","artist":"Wolfgang Sauber","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/Bargello_-_Kapelle_Fresko_2a.jpg/330px-Bargello_-_Kapelle_Fresko_2a.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"mechthild-of-magdeburg":{"extract":"Mechthild of Magdeburg, a Beguine, was a Catholic Christian mystic of the Middle Ages whose book, Das fließende Licht der Gottheit, is a compendium of visions, prayers, dialogues and mystical accounts. She was the first mystic to write in Low German.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/mechthild","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/37912","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Mechthild%20of%20Magdeburg%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mechthild_of_Magdeburg","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Merazhofen_Pfarrkirche_Chorgest%C3%BChl_links_Mechthild.jpg","license":"CC BY 3.0","artist":"Photo: Andreas Praefcke","licenseUrl":"https://creativecommons.org/licenses/by/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d3/Merazhofen_Pfarrkirche_Chorgest%C3%BChl_links_Mechthild.jpg/330px-Merazhofen_Pfarrkirche_Chorgest%C3%BChl_links_Mechthild.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"gertrude-the-great":{"extract":"Gertrude the Great or Gertrude of Helfta was a German Benedictine nun and mystic who was a member of the Monastery of Helfta. While herself a Benedictine, she had strong ties to the Cistercian Order; her monastery in Helfta is currently run by Cistercian nuns.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Gertrude%20the%20Great%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gertrude_the_Great","kind":"about"}],"isidoreFolder":"Gertrude the Great, St., O.S.B_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Santa_Giustina_%28Padua%29_-_Ecstasy_of_St._Gertrude_by_Pietro_Liberi.jpg","license":"Public domain","artist":"Didier Descouens","pd":1}},"angela-of-foligno":{"extract":"Angela of Foligno was an Italian Franciscan tertiary who became known as a mystic from her extensive writings about her mystical revelations. Due to the respect those writings engendered in the Catholic Church she became known as Theologorum Magistra, as first used by Maximilian Sandaeus, later cited by Bollandus in the Acta Sanctorum.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/54012","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Angela%20of%20Foligno%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Angela_of_Foligno","kind":"about"}],"isidoreFolder":"Angela of Foligno, Bl., 1248_-1309","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Angela_of_Foligno_1.jpg","license":"Public domain","artist":"XVIIth century print","pd":1}},"meister-eckhart":{"extract":"Eckhart von Hochheim, commonly known as Meister Eckhart, was a German Catholic priest, theologian, philosopher and mystic. He was born near Gotha in the Landgraviate of Thuringia in the Holy Roman Empire. He was a member of the Dominican Order.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/eckhart","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Meister%20Eckhart%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Meister_Eckhart","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Meister_Eckhart_base_copie.jpg","license":"CC BY-SA 4.0","artist":"Andrea di Bonaiuto","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0d/Meister_Eckhart_base_copie.jpg/330px-Meister_Eckhart_base_copie.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"johannes-tauler":{"extract":"Johannes Tauler OP was a German mystic, a Catholic priest and a theologian. He belonged to the Dominican order. Tauler was known as one of the most important Rhineland mystics. He promoted a certain neo-platonist dimension in the Dominican spirituality of his time.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/tauler","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Johannes%20Tauler%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Johannes_Tauler","kind":"about"}],"isidoreFolder":"Tauler, Johannes, O.P., c. 1300-1361","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:St-Pierre-le-Jeune_protestant-Tauler_%283x4_cropped%29.jpg","license":"CC BY-SA 3.0","artist":"Ji-Elle","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/St-Pierre-le-Jeune_protestant-Tauler_%283x4_cropped%29.jpg/330px-St-Pierre-le-Jeune_protestant-Tauler_%283x4_cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"henry-suso":{"extract":"Henry Suso, OP was a German Dominican friar and the most popular vernacular writer of the fourteenth century. An important author in both Latin and Middle High German, he is also notable for defending Meister Eckhart's legacy after Eckhart was posthumously condemned for heresy in 1329. He died in Ulm on 25 January 1366, and was beatified by the Catholic Church in 1831.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/suso","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Henry%20Suso%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Henry_Suso","kind":"about"}],"isidoreFolder":"Suso, Henry, O.P., 1290-1365","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Heinrich_Suso_Gem%C3%A4lde_1601.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"john-of-ruysbroeck":{"extract":"John of Ruusbroec or Jan van Ruusbroec, sometimes modernized Ruysbroeck, was an Augustinian canon and one of the most important of the medieval mystics of the Low Countries. Some of his main literary works include The Kingdom of the Divine Lovers, The Twelve Beguines, The Spiritual Espousals, A Mirror of Eternal Blessedness, The Little Book of Enlightenment, and The Sparkling Stone. Some of his letters also survive, as well as several short sayings. He wrote in the Middle Dutch vernacular, the language of the common people of the Low Countries, rather than in Latin, the language of the Catholi","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22John%20of%20Ruysbroeck%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_of_Ruusbroec","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Jan_Van_Ruysbroeck.jpg","license":"Public domain","artist":"The original uploader was Polylerus at English Wikipedia","pd":1}},"catherine-of-siena":{"extract":"Caterina di Jacopo di Benincasa, TOSD, known as Catherine of Siena, was an Italian Catholic mystic and diplomat who engaged in papal and Italian politics through extensive letter-writing and advocacy. Canonised in 1461, she is revered as a saint and as a Doctor of the Church due to her extensive theological authorship. She is also considered to have influenced Italian literature.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/catherine","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/2456","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Catherine%20of%20Siena%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Catherine_of_Siena","kind":"about"}],"isidoreFolder":"Caterina da Siena, Santa, T.O.P_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Giovanni_Battista_Tiepolo_096.jpg","license":"Public domain","artist":"Giovanni Battista Tiepolo","pd":1}},"bridget-of-sweden":{"extract":"Bridget of Sweden, OSsS, also known as Birgitta Birgersdotter and Birgitta of Vadstena, was a Swedish Catholic mystic and the founder of the Bridgettines. Outside Sweden, she was also known as the Princess of Nericia. She was the mother of Catherine of Vadstena.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Bridget%20of%20Sweden%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Bridget_of_Sweden","kind":"about"}],"isidoreFolder":"Birgitta of Sweden, St. (1303-1373)","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Heliga_Birgitta_p%C3%A5_ett_altarsk%C3%A5p_i_Salems_kyrka_retouched.png","license":"Public domain","artist":"Heliga_Birgitta_på_ett_altarskåp_i_Salems_kyrka.jpg : Hermann Rode (late 15th century) derivative work: Bea o","pd":1}},"julian-of-norwich":{"extract":"Julian of Norwich, also known as Juliana of Norwich, the Lady Julian, Dame Julian or Mother Julian, was a medieval English Catholic anchoress. Her writings, now known as Revelations of Divine Love, are the earliest surviving English-language works attributed to a woman. They are also the only surviving English-language works by an anchoress.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/julian","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/47157","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Julian%20of%20Norwich%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Julian_of_Norwich","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Statue_of_Dame_Julian_crop.jpg","license":"CC0","artist":"User:Poliphilo","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","pd":1}},"walter-hilton":{"extract":"Walter Hilton, Can. Reg. was an English Augustinian mystic, whose works gained influence in 15th-century England and Wales. He is commemorated by the Church of England and by the Episcopal Church in the United States.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/hilton","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Walter%20Hilton%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Walter_Hilton","kind":"about"}],"isidoreFolder":"Hilton, Walter"},"richard-rolle":{"extract":"Richard Rolle was an English hermit, mystic, and religious writer. He is also known as Richard Rolle of Hampole or de Hampole, since at the end of his life he lived near a Cistercian nunnery in Hampole, now in South Yorkshire. In many ways, he can be considered the first English author due to the reported influence of his vernacular works starting soon after his death and continuing for centuries. Indeed, until the nineteenth century northern English medieval religious texts were regularly mis-attributed to him because of his ongoing authority.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/rolle","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/31618","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Richard%20Rolle%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Richard_Rolle","kind":"about"}],"imgCredit":{"page":"https://en.wikipedia.org/wiki/File:Richard_Rolle_%28colour%29.jpg","license":"PD","pd":1}},"the-cloud-of-unknowing-author":{"extract":"The Cloud of Unknowing is an anonymous work of Christian mysticism written in Middle English in the latter half of the 14th century. The text is written as guide from a teacher to a student, with the message that God cannot be understood via reason or intellect, but only through love: “By love may He be gotten and holden, but never through thought.” To achieve this goal, the text recommends cultivation of two mental states: “The cloud of forgetting”, and “the cloud of unknowing”.","qidWork":"Q1217629","links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22The%20Cloud%20of%20Unknowing%20author%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/The_Cloud_of_Unknowing","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:The_Cloud_of_Unknowing_%28Harley_2373_%29.jpg","license":"Public domain","artist":"the \" Cloud author \"","pd":1}},"thomas-a-kempis":{"extract":"Thomas à Kempis was a German-Dutch Catholic canon regular of the Augustinians and the author of The Imitation of Christ, one of the best known Christian devotional books. His name means \"Thomas of Kempen\", Kempen, Germany, being his home town.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/kempis","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/682","kind":"read"},{"label":"Imitation of Christ — CCEL","url":"https://ccel.org/ccel/kempis/imitation","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Thomas%20%C3%A0%20Kempis%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Thomas_%C3%A0_Kempis","kind":"about"}],"isidoreFolder":"Thomas a Kempis","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Thomas_von_Kempen_JS.JPG","license":"Public domain","artist":"zeitgenössischer Maler","pd":1}},"jean-gerson":{"extract":"Jean Charlier de Gerson was a French Roman Catholic scholar, educator, reformer, and poet, Chancellor of the University of Paris, a guiding influence of the conciliar movement and one of the most prominent theologians at the Council of Constance. He was one of the first thinkers to develop what would later come to be called natural rights theory, and was also one of the first individuals to defend Joan of Arc and proclaim her supernatural vocation as authentic.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/gerson","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/53019","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jean%20Gerson%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jean_Gerson","kind":"about"}],"imgCredit":{"page":"https://en.wikipedia.org/wiki/File:Jean_Gerson_%281714%29.jpg","license":"Public domain","artist":"Bernard Picart (Life time: 1673–1733)","pd":1}},"nicholas-of-cusa":{"extract":"Nicholas of Cusa, also referred to as Nicholas of Kues and Nicolaus Cusanus, was a German Catholic bishop and polymath active as a philosopher, theologian, jurist, mathematician, and astronomer. One of the first German proponents of Renaissance humanism, he made spiritual and political contributions to European culture. A notable example of this is his mystical or spiritual writings on \"learned ignorance\", as well as his participation in power struggles between Rome and the German states of the Holy Roman Empire.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Nicholas%20of%20Cusa%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Nicholas_of_Cusa","kind":"about"}],"isidoreFolder":"Nicholas of Cusa","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Nicholas_of_Cusa.jpg","license":"Public domain","artist":"Master of the Life of the Virgin","pd":1}},"catherine-of-genoa":{"extract":"Catherine of Genoa was an Italian saint and mystic, known for her work among the sick and the poor and remembered because of various writings describing both these actions and her mystical experiences. She was a member of the noble Fieschi family, and spent most of her life and her means serving the sick, especially during the plague which ravaged Genoa in 1497 and 1501. She died in that city in 1510.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Catherine%20of%20Genoa%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Catherine_of_Genoa","kind":"about"}],"isidoreFolder":"Caterina da Genova, Santa","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Saint_Catherine_of_Genoa._Painting..jpg","license":"CC BY-SA 4.0","artist":"Denys3200","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1b/Saint_Catherine_of_Genoa._Painting..jpg/330px-Saint_Catherine_of_Genoa._Painting..jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"vincent-ferrer":{"extract":"Vincent Ferrer, OP was a Valencian Dominican friar who gained acclaim as a preacher, missionary and logician. After supporting Antipope Benedict XIII during the Western Schism, Ferrer travelled to preach across Western Europe and the British Isles. His preaching has been credited in some sources as converting 25,000 Jews to Catholicism. Other sources indicate that it involved support for coercive means, such as the forcible conversion of synagogues into churches. He was canonized in 1455.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Vincent%20Ferrer%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Vincent_Ferrer","kind":"about"}],"isidoreFolder":"Ferrer, St. Vincent, O.P. (1350-1419)","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Joan_de_Joanes_-_St_Vincent_Ferrer_-_WGA12062.jpg","license":"Public domain","artist":"Juan de Juanes","pd":1}},"bernardino-of-siena":{"extract":"Bernardino of Siena, OFM, was an Italian Catholic priest and Franciscan missionary preacher in the Republic of Siena. He was a systematizer of scholastic economics.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Bernardino%20of%20Siena%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Bernardino_of_Siena","kind":"about"}],"isidoreFolder":"Bernardino da Siena, O.F.M., san","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Saint_Bernardino_of_Siena.PNG","license":"Public domain","artist":"Jacopo Bellini","pd":1}},"antoninus-of-florence":{"extract":"Antoninus of Florence was an Italian Dominican friar who served as Archbishop of Florence in the 15th century. He is venerated as a saint in the Catholic Church.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Antoninus%20of%20Florence%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Antoninus_of_Florence","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Sant%27antonino_pierozzi_%28cropped%29.jpg","license":"CC BY-SA 4.0","artist":"Sailko","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8e/Sant%27antonino_pierozzi_%28cropped%29.jpg/330px-Sant%27antonino_pierozzi_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"denis-the-carthusian":{"extract":"Denis the Carthusian, also known as Denys van Leeuwen, Denis Ryckel, Dionysius van Rijkel, Dionysius Carthusianus, Denys le Chartreux, was a Roman Catholic theologian and mystic.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Denis%20the%20Carthusian%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Denis_the_Carthusian","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Adriaen_Millaert_-_Portrait_of_Denis_the_Carthusian.jpg","license":"Public domain","artist":"Adriaen Millaert","pd":1}},"girolamo-savonarola":{"extract":"Girolamo Savonarola, OP, also referred to as Jerome Savonarola, was an Italian ascetic Dominican friar from Ferrara and a preacher active in Renaissance Florence. He became known for his prophecies of civic glory, his advocacy of the destruction of secular art and culture, and his calls for Christian renewal. He denounced clerical corruption, despotic rule, and the exploitation of the poor.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/57530","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Girolamo%20Savonarola%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Girolamo_Savonarola","kind":"about"}],"isidoreFolder":"Savonarola, Girolamo, O.P., 1452-1498","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Savonarola_%28cropped%29.jpg","license":"Public domain","artist":"Fra Bartolomeo","pd":1}},"thomas-cajetan":{"extract":"Thomas Cajetan, also known as Gaetanus or Cajetanus, commonly Tommaso de Vio or Thomas de Vio, was an Italian philosopher, theologian, the Master of the Order of Preachers 1508 to 1518, and cardinal from 1517 until his death. He was a leading theologian of his day who is now best known as the spokesman for Catholic opposition to the teachings of Martin Luther and the Protestant Reformation while he was the Pope's legate in Augsburg, and among Catholics for his extensive commentary on the Summa Theologiae of St. Thomas Aquinas.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Thomas%20Cajetan%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Thomas_Cajetan","kind":"about"}],"isidoreFolder":"Cajetan, Tommaso de Vio, O.P_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Kardinal_Cajetan_und_Luther%2C_von_Francesco_Salviati_%28cropped%29.jpg","license":"Public domain","artist":"Francesco de' Rossi (+ 1563)","pd":1}},"thomas-more":{"extract":"Sir Thomas More, venerated in the Catholic Church as a martyr and saint, was an English lawyer, judge, social philosopher, author, statesman, theologian and Renaissance humanist. He also served Henry VIII as Lord Chancellor from October 1529 to May 1532. He wrote Utopia, published in 1516, which describes the political system of an imaginary island state.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/more","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Thomas%20More%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Thomas_More","kind":"about"}],"isidoreFolder":"More, St. Thomas","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Hans_Holbein%2C_the_Younger_-_Sir_Thomas_More_-_Google_Art_Project.jpg","license":"Public domain","artist":"Hans Holbein the Younger","pd":1}},"john-fisher":{"extract":"John Fisher was an English Catholic prelate who served as Bishop of Rochester from 1504 to 1535 and as chancellor of the University of Cambridge. He is honoured as a martyr and saint by the Catholic Church.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22John%20Fisher%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Fisher","kind":"about"}],"isidoreFolder":"Fisher, St. John","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:San_Juan_Fisher_Obispo_de_Rochester_y_M%C3%A1rtir.jpg","license":"Public domain","artist":"Hans Holbein the Younger","pd":1}},"erasmus-of-rotterdam":{"extract":"Desiderius Erasmus Roterodamus, commonly known in English as Erasmus of Rotterdam or simply Erasmus, was a Dutch humanist, theologian, and philosopher. He was, through his writings and translations, one of the most influential scholars of the Northern Renaissance and a major figure of Western culture.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/erasmus","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Erasmus%20of%20Rotterdam%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Erasmus","kind":"about"}],"isidoreFolder":"Erasmus, Desiderius","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Holbein-erasmus.jpg","license":"Public domain","artist":"Hans Holbein the Younger","pd":1}},"ignatius-of-loyola":{"extract":"Ignatius of Loyola was a Spanish Basque Catholic priest and theologian, who, with six companions, founded the religious order of the Society of Jesus (Jesuits), and became its first Superior General, in Paris in 1541.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/ignatius","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/26561","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Ignatius%20of%20Loyola%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ignatius_of_Loyola","kind":"about"}],"isidoreFolder":"Ignatius of Loyola, St., S.J_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Ignatius_Loyola.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"francis-xavier":{"extract":"Francis Xavier, venerated as Saint Francis Xavier, was a Navarrese cleric and missionary. He co-founded the Society of Jesus and, as a representative of the Portuguese Empire, led the first Christian mission to Japan.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Francis%20Xavier%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Francis_Xavier","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Franciscus_de_Xabier.jpg","license":"Public domain","pd":1}},"peter-faber":{"extract":"Peter Faber, SJ was a Savoyard Catholic priest, theologian and co-founder of the Society of Jesus, along with Ignatius of Loyola and Francis Xavier. Pope Francis announced his canonization in 2013.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Peter%20Faber%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Peter_Faber","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Pierre_Favre%281%29.jpg","license":"Public domain","artist":"The original uploader was Bwag at German Wikipedia","pd":1}},"francisco-de-vitoria":{"extract":"Francisco de Vitoria, also known as Francisco de Victoria, was a Spanish Catholic philosopher, theologian, and jurist of Renaissance Spain. He is the founder of the tradition in philosophy known as the School of Salamanca, which laid the groundwork for early free-market economics and individual rights, influencing the development of libertarian thought. Vitoria's work on natural law and the freedom of exchange contributed to later Austrian School economists' emphasis on the moral basis for voluntary commerce. Although less known than others of his kind, he has been considered one of the most i","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Francisco%20de%20Vitoria%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Francisco_de_Vitoria","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Franciscodevictoria.jpg","license":"CC BY 2.0","artist":"Raúl Hernández González Seguir Francisco de Vitoria 3 Detalles de la fachada de la iglesia del convento de San Esteban, los Dominicos, en Salamanca. Estatua de Francisco de Vitoria","licenseUrl":"https://creativecommons.org/licenses/by/2.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/ba/Franciscodevictoria.jpg/330px-Franciscodevictoria.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"domingo-de-soto":{"extract":"Domingo de Soto was a Spanish Dominican priest and Scholastic theologian and naturalist born in Segovia (Spain), and died in Salamanca (Spain), at the age of 66. He is best known as one of the founders of international law and of the Spanish Thomistic philosophical and theological movement known as the School of Salamanca.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Domingo%20de%20Soto%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Domingo_de_Soto","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:DOMINGO_DE_SOTO016_%283x4_cropped%29.JPG","license":"CC BY-SA 4.0","artist":"Vicente Alcober Bosch, Valencia (España)","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/DOMINGO_DE_SOTO016_%283x4_cropped%29.JPG/330px-DOMINGO_DE_SOTO016_%283x4_cropped%29.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"melchior-cano":{"extract":"Melchor Cano was a Spanish Scholastic theologian. Cano's most important theological work was his posthumously published De locis theologicis, a major contribution to the New Scholasticism of the School of Salamanca.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Melchior%20Cano%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Melchor_Cano","kind":"about"}],"isidoreFolder":"Melchior, Cano, O.P., 1509-1560","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Melchor_Cano.jpg","license":"Public domain","artist":"Boix, Esteban (1774-ca. 1828) por dibujo de José Camarón Bonanat","pd":1}},"john-of-avila":{"extract":"John of Ávila was a Spanish priest, preacher, scholastic author, and religious mystic, who has been declared a saint and Doctor of the Church by the Catholic Church. He is called the \"Apostle of Andalusia\", for his extensive ministry in that region.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22John%20of%20%C3%81vila%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_of_%C3%81vila","kind":"about"}],"isidoreFolder":"Juan de Avila, San","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Attributed_to_el_Greco_-_Portrait_of_Juan_de_%C3%81vila_-_Google_Art_Project.jpg","license":"Public domain","artist":"Workshop of El Greco","pd":1}},"peter-of-alcantara":{"extract":"Peter of Alcántara, OFM was a Spanish Franciscan friar who was canonized in 1669.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Peter%20of%20Alc%C3%A1ntara%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Peter_of_Alc%C3%A1ntara","kind":"about"}],"isidoreFolder":"Peter de Alcantara, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Clevelandart_2009.81.jpg","license":"CC0","artist":"Pedro de Mena","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","pd":1}},"teresa-of-avila":{"extract":"Teresa of Ávila, religious name Teresa of Jesus, was a Carmelite nun, prominent Spanish mystic and spiritual reformer.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/teresa","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/2651","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Teresa%20of%20%C3%81vila%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Teresa_of_%C3%81vila","kind":"about"}],"isidoreFolder":"Avila, Teresa de, Santa, 1515-1582","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Santa_Teresa_de_Jes%C3%BAs_%28Museo_del_Prado%29.jpg","license":"Public domain","artist":"Eduardo Balaca","pd":1}},"john-of-the-cross":{"extract":"St. John of the Cross was a Spanish Catholic priest, mystic, and Carmelite friar. He is a major figure of the Counter-Reformation in Spain, and he is one of the 38 Doctors of the Church.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22John%20of%20the%20Cross%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_of_the_Cross","kind":"about"}],"isidoreFolder":"Juan de la Cruz, San","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Zurbar%C3%A1n_%28atribuido%29-John_of_the_Cross-1656.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"louis-of-granada":{"extract":"Louis of Granada was a Spanish Dominican friar, theologian, writer and preacher. His beatification process has been long open with the Holy See, with his current status being venerable.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Louis%20of%20Granada%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Louis_of_Granada","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Libro_de...memorables_varones%2C_1886_%22Fray_Luis_de_Granada%22_%283816813545%29.jpg","license":"CC BY 2.0","artist":"Fondo Antiguo de la Biblioteca de la Universidad de Sevilla from Sevilla, España","licenseUrl":"https://creativecommons.org/licenses/by/2.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Libro_de...memorables_varones%2C_1886_%22Fray_Luis_de_Granada%22_%283816813545%29.jpg/330px-Libro_de...memorables_varones%2C_1886_%22Fray_Luis_de_Granada%22_%283816813545%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"peter-canisius":{"extract":"Peter Canisius was a Dutch Jesuit priest known for his strong support for the Catholic faith during the Protestant Reformation in Germany, Austria, Bohemia, Moravia, Switzerland and the British Isles. The restoration of the Catholic Church in Germany is largely attributed to the work there of the Jesuits, which Canisius led. He is venerated in the Catholic Church as a saint and as a Doctor of the Church.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Peter%20Canisius%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Peter_Canisius","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Saint_Petrus_Canisius.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"charles-borromeo":{"extract":"Charles Borromeo was an Italian Catholic prelate who served as Archbishop of Milan from 1564 to 1584. He was made a cardinal in 1560.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Charles%20Borromeo%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Charles_Borromeo","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Carlo_Borromeo.jpg","license":"Public domain","artist":"Giovanni Ambrogio Figino","pd":1}},"philip-neri":{"extract":"Philip Neri, born Filippo Romolo Neri, pronounced [fiˈlippo ˈrɔːmolo ˈneːri] was an Italian Catholic priest who founded the Congregation of the Oratory, a society of secular clergy dedicated to pastoral care and charitable work. He is sometimes referred to as the \"Second Apostle of Rome\" after Peter the Apostle, and sometimes as the \"Third Apostle of Rome\", after Peter and Paul the Apostle. Neri's spiritual mission emphasised personal holiness and direct service to others, particularly through the education of young people and care for the poor and sick. His work played a significant role in t","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Philip%20Neri%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Philip_Neri","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:FNeri.gif","license":"Public domain","artist":"Sebastiano Conca","pd":1}},"robert-bellarmine":{"extract":"Robert Bellarmine was an Italian Jesuit and a cardinal of the Catholic Church. He was canonized a saint in 1930 and named Doctor of the Church, one of only 27 at the time. He was one of the most important figures in the Counter-Reformation.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/bellarmine","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Robert%20Bellarmine%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Robert_Bellarmine","kind":"about"}],"isidoreFolder":"Bellarmine, St. Robert, S.J., 1542-1621","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Portret_van_kardinaal_Robertus_Bellarminus%2C_onbekend%2C_schilderij%2C_Museum_Plantin-Moretus_%28Antwerpen%29_-_MPM_V_IV_110_%28cropped%29.jpg","license":"CC0","artist":"Author unknown","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","pd":1}},"francisco-suarez":{"extract":"Francisco Suárez was a Spanish Jesuit priest, philosopher and theologian, one of the leading figures of the School of Salamanca movement. His work is considered a turning point in the history of second scholasticism, marking the transition from its Renaissance to its Baroque phases. According to Christopher Shields and Daniel Schwartz, \"figures as distinct from one another in place, time, and philosophical orientation as Leibniz, Grotius, Pufendorf, Schopenhauer and Heidegger, all found reason to cite him as a source of inspiration and influence.\"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Francisco%20Su%C3%A1rez%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Francisco_Su%C3%A1rez","kind":"about"}],"isidoreFolder":"Suarez, Francisco, S.J., 1548-1617","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Suarez_LOC_hec.13754_%28cropped%29.jpg","license":"Public domain","artist":"Harris & Ewing Collection","pd":1}},"luis-de-molina":{"extract":"Luis de Molina was a Spanish Jesuit Catholic priest, jurist, economist and theologian renowned for his contributions to philosophy and economics within the framework of the second scholasticism.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/molina","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Luis%20de%20Molina%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Luis_de_Molina","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Molina_-_De_Justitia_et_jure%2C_1759_-_272.tif","license":"Public domain","artist":"Molina, Luis de","pd":1}},"domingo-banez":{"extract":"Domingo Báñez was a Spanish Dominican and Scholastic theologian and a member of the later School of Salamanca. The qualifier Mondragonensis is sometimes attached to his name and seems to refer to the birthplace of his father, Juan Báñez, at Mondragón in Guipúzcoa.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Domingo%20B%C3%A1%C3%B1ez%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Domingo_B%C3%A1%C3%B1ez","kind":"about"}],"isidoreFolder":"Banez, Domingo, O.P_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Ba%C3%B1ez_-_Decisiones_de_Iure_%26_Iustitia%2C_1595_-_035.tif","license":"Public domain","artist":"Fondazione Mansutti","pd":1}},"cesare-baronius":{"extract":"Cesare Baronio, known more commonly as Caesar Baronius[a] CO, was an Italian Oratorian, cardinal and historian of the Catholic Church. His best-known works are his Annales Ecclesiastici, which appeared in 12 folio volumes (1588–1607). He is a candidate for sainthood, having been declared venerable in 1745 by then-Pope Benedict XIV.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Cesare%20Baronius%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Caesar_Baronius","kind":"about"}],"isidoreFolder":"Baronio, Cesare, 1538-1607","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Portret_van_kardinaal_Baronius%2C_onbekend%2C_schilderij%2C_Museum_Plantin-Moretus_%28Antwerpen%29_-_MPM_V_IV_111_%28cropped%29.jpg","license":"CC0","artist":"Author unknown","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","pd":1}},"lawrence-of-brindisi":{"extract":"Lawrence of Brindisi, born Giulio Cesare Russo, was an Italian Catholic priest, theologian and member of the Order of Friars Minor Capuchin. An accomplished linguist, in addition to his native Italian, Lawrence could read and speak Latin, Hebrew, Greek, German, Czech, Spanish, and French fluently. Lawrence was ordained a priest at the age of 23. Lawrence was beatified on 1 June 1783 and canonized as a saint on 8 December 1881.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Lawrence%20of%20Brindisi%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Lawrence_of_Brindisi","kind":"about"}],"isidoreFolder":"Lawrence of Brindisi, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:San_Lorenzo_da_Brindisi.jpg","license":"Public domain","pd":1}},"francis-de-sales":{"extract":"Francis de Sales was a Catholic prelate from Savoy who served as Bishop of Geneva from 1602 to 1622. He became noted for his deep faith and his gentle approach to the religious divisions in his land resulting from the Protestant Reformation. He is known also for his writings on the topics of spiritual direction and spiritual formation, particularly the Introduction to the Devout Life and the Treatise on the Love of God. He was a member of the Oratory of Saint Philip Neri, a tertiary of the Order of Minims, and was canonized in 1665.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/40914","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Francis%20de%20Sales%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Francis_de_Sales","kind":"about"}],"isidoreFolder":"de Sales, Francis, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Ch%C3%A2teau_de_Bussy-Rabutin_-_Saint_Fran%C3%A7ois_de_Sales%2C_%C3%A9v%C3%AAque_de_Gen%C3%A8ve_%28bgw19_0375%29_%28cropped%29.jpg","license":"Public domain","artist":"Benjamin Gavaudo","pd":1}},"jane-frances-de-chantal":{"extract":"Jane Frances de Chantal, VHM was a French Catholic noble widow and nun who was beatified in 1751 and canonized in 1767. She founded the Order of the Visitation of Holy Mary. The religious order accepted women who were rejected by other orders because of poor health or age.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jane%20Frances%20de%20Chantal%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jane_Frances_de_Chantal","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Sainte_Jeanne-Fran%C3%A7oise_Fr%C3%A9myot_de_Chantal.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"lorenzo-scupoli":{"extract":"Francesco Scupoli, better known by his religious name Lorenzo Scupoli, was a Neapolitan Catholic priest, most notable for his authorship of The Spiritual Combat, an important work in 16th-century Catholic spirituality.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Lorenzo%20Scupoli%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Lorenzo_Scupoli","kind":"about"}],"isidoreFolder":"Scupoli, Lorenzo","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Laurentius_Scupulus.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"edmund-campion":{"extract":"Edmund Campion, SJ was an English Jesuit priest and martyr. While conducting an underground ministry in officially Anglican England, Campion was arrested by priest hunters. Convicted of high treason, he was hanged, drawn and quartered at Tyburn. Campion was beatified by Pope Leo XIII in 1886 and canonised in 1970 by Pope Paul VI as one of the Forty Martyrs of England and Wales. His feast day is celebrated on 1 December.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/4855","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Edmund%20Campion%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Edmund_Campion","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Edmundus_Campion.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"robert-southwell":{"extract":"Robert Southwell, SJ, also Saint Robert Southwell, was an English Catholic priest of the Jesuit Order. He was also an author of Christian poetry in Elizabethan English, and a clandestine missionary in Elizabethan England.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Robert%20Southwell%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Robert_Southwell_(priest)","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Robert_Southwell.JPG","license":"Public domain","artist":"Author unknown","pd":1}},"alphonsus-rodriguez":{"extract":"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Alphonsus%20Rodriguez%22","kind":"search"}]},"pierre-de-berulle":{"extract":"Pierre de Bérulle was a French Catholic priest, cardinal and statesman in 17th-century France. He was the founder of the French school of spirituality and counted among his disciples Vincent de Paul and Francis de Sales, although both developed significantly different spiritual theologies. He was also founder of the Oratory of Jesus.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Pierre%20de%20B%C3%A9rulle%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pierre_de_B%C3%A9rulle","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:CardinaldeBerulle.jpg","license":"Public domain","artist":"Philippe de Champaigne","pd":1}},"vincent-de-paul":{"extract":"Vincent de Paul, CM was a French Catholic priest who dedicated himself to serving the poor and is best known for founding the Congregation of the Mission and the Daughters of Charity.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Vincent%20de%20Paul%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Vincent_de_Paul","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Simon_Fran%C3%A7ois_de_Tours_-_Portrait_Vincent_de_Paul_%284x5_cropped%29.jpeg","license":"Public domain","artist":"Simon François de Tours (1606-1671)","pd":1}},"john-eudes":{"extract":"John Eudes, CIM was a French Catholic priest and the founder of both the Order of Our Lady of Charity in 1641 and Congregation of Jesus and Mary, also known as the Eudists, in 1643. He was also a professed member of the Oratory of Jesus until 1643.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22John%20Eudes%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Eudes","kind":"about"}],"isidoreFolder":"Eudes, St. Jean","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:JeanEudes.png","license":"Public domain","artist":"Unidentified painter","pd":1}},"jean-jacques-olier":{"extract":"Jean-Jacques Olier, S.S. was a French Catholic priest and the founder of the Sulpicians. He also helped to establish the Société Notre-Dame de Montréal, which organised the settlement of a new town called Ville-Marie in the colony of New France.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jean-Jacques%20Olier%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jean-Jacques_Olier","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:J.J._Olier.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"blaise-pascal":{"extract":"Blaise Pascal was a French mathematician, physicist, inventor, philosopher, and Catholic writer.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/pascal","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/7913","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Blaise%20Pascal%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Blaise_Pascal","kind":"about"}],"isidoreFolder":"Pascal, Blaise","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Blaise_Pascal_Versailles%2C_circa_1690.JPG","license":"Public domain","artist":"Unknown; a copy of the painting of François II Quesnel, which was made for Gérard Edelinck en 1691","pd":1}},"jacques-benigne-bossuet":{"extract":"Jacques-Bénigne Lignel Bossuet was a French Catholic prelate and theologian who served as Bishop of Meaux from 1681 until his death in 1704. Renowned for his sermons, addresses and literary works, he is regarded as a brilliant orator and literary stylist of the French language.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/58807","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jacques-B%C3%A9nigne%20Bossuet%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jacques-B%C3%A9nigne_Bossuet","kind":"about"}],"isidoreFolder":"Bossuet, Jacques-Benigne","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Jacques-B%C3%A9nigne_Bossuet_1.PNG","license":"Public domain","artist":"Hyacinthe Rigaud","pd":1}},"francois-fenelon":{"extract":"François de Salignac de la Mothe-Fénelon, P.S.S., more commonly known as François Fénelon, was a French Catholic archbishop, theologian, poet and writer. Today, he is remembered mostly as the author of The Adventures of Telemachus, first published in 1699. He was a member of the Sulpician Fathers.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/fenelon","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/3810","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Fran%C3%A7ois%20F%C3%A9nelon%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Fran%C3%A7ois_F%C3%A9nelon","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Fran%C3%A7ois_de_Salignac_de_la_Mothe-F%C3%A9nelon.PNG","license":"Public domain","artist":"Joseph Vivien","pd":1}},"brother-lawrence":{"extract":"Brother Lawrence of the Resurrection, OCD was a French Catholic religious brother who served at a Discalced Carmelite monastery, what is now Saint-Joseph-des-Carmes in Paris. He is best remembered for a posthumous book of his writing, the classic Christian text The Practice of the Presence of God.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/lawrence","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/1832","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Brother%20Lawrence%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Brother_Lawrence","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Brother_Lawrence_in_the_kitchen.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"margaret-mary-alacoque":{"extract":"Margaret Mary Alacoque was a French Visitation nun and mystic who promoted devotion to the Sacred Heart of Jesus in its modern form.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Margaret%20Mary%20Alacoque%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Margaret_Mary_Alacoque","kind":"about"}],"isidoreFolder":"Alacoque, Marguerite-Marie, Saint, 1647-1690","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Marguerite-Marie_Alacoque.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"jean-pierre-de-caussade":{"extract":"Jean Pierre de Caussade was a French Jesuit priest and writer. He is especially known for the work ascribed to him known as Abandonment to Divine Providence, and also his work with the Nuns of the Visitation in Nancy, France.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/46647","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jean-Pierre%20de%20Caussade%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jean_Pierre_de_Caussade","kind":"about"}],"isidoreFolder":"de Caussade, Jean-Pierre, S.J_"},"louis-de-montfort":{"extract":"Louis-Marie Grignion de Montfort, SMM was a French Catholic priest known for his influence on Catholic Mariology. He wrote a number of books that went on to become classic Catholic titles, including Secret of the Rosary and True Devotion to Mary, and influenced several popes. He also founded several religious communities, including the Company of Mary.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Louis%20de%20Montfort%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Louis_de_Montfort","kind":"about"}],"isidoreFolder":"Grignion de Montfort, St. Louis-Marie, T.O.P., 1673-1716","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:%D0%9B%D1%8E%D0%B4%D0%BE%D0%B2%D0%B8%D0%BA_%D0%9C%D0%B0%D1%80%D0%B8%D1%8F_%D0%93%D1%80%D0%B8%D0%BD%D1%8C%D0%BE%D0%BD_%D0%B4%D0%B5_%D0%9C%D0%BE%D0%BD%D1%84%D0%BE%D1%80.jpg","license":"Public domain","artist":"Неизвестный автор","pd":1}},"john-of-saint-thomas":{"extract":"John of St. Thomas, born João Poinsot, was a Portuguese Dominican friar, Thomist theologian, and professor of philosophy. He is known for being an early theorist in the field of semiotics.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22John%20of%20Saint%20Thomas%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_of_St._Thomas","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:John_of_St._Thomas.webp","license":"Public domain","artist":"Author unknown","pd":1}},"juan-de-los-angeles":{"extract":"Juan de los Ángeles, was a Spanish priest and writer. He belonged to the Franciscan Order and was reported to have had a vast knowledge of the classics of antiquity.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Juan%20de%20los%20%C3%81ngeles%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Juan_de_los_%C3%81ngeles","kind":"about"}]},"mary-of-agreda":{"extract":"Mary of Jesus of Ágreda, OIC,, was an abbess and spiritual writer. She is best known for her extensive correspondence with King Philip IV of Spain and her reports of bilocation between Spain and New Spain. She was a noted mystic whose popularity has endured.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Mary%20of%20Agreda%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mary_of_Jesus_of_%C3%81greda","kind":"about"}],"isidoreFolder":"Mary of Agreda, Ven_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Mar%C3%ADa_de_Jes%C3%BAs_de_%C3%81greda_%28cropped%29.png","license":"Public domain","artist":"Unidentified painter","pd":1}},"alphonsus-liguori":{"extract":"Alphonsus Maria de Liguori was an Italian Catholic bishop and saint, as well as a spiritual writer, composer, musician, artist, poet, lawyer, scholastic philosopher, and theologian. He founded the Congregation of the Most Holy Redeemer, known as the Redemptorists, in November 1732.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Alphonsus%20Liguori%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alphonsus_Liguori","kind":"about"}],"isidoreFolder":"Liguori, St. Alfonso Maria de', 1696-1787","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Liguori.jpg","license":"CC BY-SA 3.0","artist":"Author unknown","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f6/Liguori.jpg/330px-Liguori.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"leonard-of-port-maurice":{"extract":"Leonard of Port Maurice, O.F.M., was an Italian Franciscan preacher and ascetic writer.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Leonard%20of%20Port%20Maurice%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Leonard_of_Port_Maurice","kind":"about"}],"isidoreFolder":"Leonard of Port Maurice, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:S_Leonardo.JPG","license":"Public domain","artist":"Author unknown","pd":1}},"paul-of-the-cross":{"extract":"Paul of the Cross was an Italian Catholic mystic, and founder of the Passionists.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Paul%20of%20the%20Cross%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Paul_of_the_Cross","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Paul_de_la_croix.jpg","license":"Public domain","artist":"Plet philippe","pd":1}},"prospero-lambertini":{"extract":"Pope Benedict XIV, born Prospero Lorenzo Lambertini, was head of the Catholic Church and leader of the Papal States from 17 August 1740 to his death on 3 May 1758. His intellectualism and advocacy of science education earned him the nickname \"the Enlightenment Pope\".","qidWork":null,"links":[{"label":"Documents on vatican.va","url":"https://www.vatican.va/content/benedictus-xiv/en.html","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Prospero%20Lambertini%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pope_Benedict_XIV","kind":"about"}],"isidoreFolder":"Benedict XIV, Pope","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Pierre_Subleyras_Portrait_of_Benedict_XIV_1746._Metropolitan_Museum_of_Art.jpg","license":"Public domain","artist":"Pierre Subleyras","pd":1}},"alban-butler":{"extract":"Alban Butler was an English Roman Catholic priest and hagiographer. Born in Northamptonshire, he studied at the English College in Douay, France, where he later taught philosophy and theology. He served as a guide on the Grand Tour to the nephews of the Earl of Shrewsbury. Upon his return in 1749, Butler was made chaplain to the Duke of Norfolk. He was appointed president of the English seminary at Saint Omer in France. Butler is mainly known for his Lives of the Saints, the result of thirty years of work.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/9306","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Alban%20Butler%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alban_Butler","kind":"about"}],"isidoreFolder":"Butler, Alban"},"richard-challoner":{"extract":"Richard Challoner was an English Catholic prelate who served as Vicar Apostolic of the London District during the greater part of the 18th century, and as Titular Bishop of Doberus. In 1738, he published a revision of the Douay–Rheims Bible.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/challoner","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/50938","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Richard%20Challoner%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Richard_Challoner","kind":"about"}],"isidoreFolder":"Challoner, Richard","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Richard_Challoner_painting.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"gregory-martin":{"extract":"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Gregory%20Martin%22","kind":"search"}],"isidoreFolder":"Martin, Gregory"},"jean-mabillon":{"extract":"Dom Jean Mabillon, was a French Benedictine monk and scholar of the Congregation of Saint Maur. He is considered the founder of the disciplines of palaeography and diplomatics.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jean%20Mabillon%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jean_Mabillon","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Portrait_of_Mabillon_%284671638%29.jpg","license":"Public domain","artist":"John Pass","pd":1}},"charles-billuart":{"extract":"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Charles%20Billuart%22","kind":"search"}]},"joseph-de-maistre":{"extract":"Joseph Marie, comte de Maistre, was a Savoyard lawyer, diplomat, and political philosopher. He is chiefly remembered as one of the intellectual forefathers of modern conservatism.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Joseph%20de%20Maistre%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Joseph_de_Maistre","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Jmaistre.jpg","license":"Public domain","artist":"Carl Christian Vogel von Vogelstein","pd":1}},"francois-rene-de-chateaubriand":{"extract":"François-René, vicomte de Chateaubriand was a French writer, politician, diplomat and historian who influenced French literature of the 19th century. Descended from an old aristocratic family from Brittany, Chateaubriand was a royalist. He served as Minister of Foreign Affairs from 1822 to 1824 and as the French ambassador to Sweden, Prussia, the United Kingdom, and the Papal States.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/7255","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Fran%C3%A7ois-Ren%C3%A9%20de%20Chateaubriand%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Fran%C3%A7ois-Ren%C3%A9_de_Chateaubriand","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Anne-Louis_Girodet-Trioson_006.jpg","license":"Public domain","artist":"Anne-Louis Girodet","pd":1}},"johann-adam-mohler":{"extract":"Johann Adam Möhler was a German Roman Catholic theologian and priest associated with the Catholic Tübingen school. His main area of theology was in the comparison of Catholicism and Protestantism.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Johann%20Adam%20M%C3%B6hler%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Johann_Adam_M%C3%B6hler","kind":"about"}],"isidoreFolder":"Mohler, Johann Adam, 1796-1838","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:M%C3%B6hler_Istas.jpg","license":"Public domain","artist":"Eduard Istas","pd":1}},"juan-donoso-cortes":{"extract":"Juan Francisco María de la Salud Donoso Cortés y Fernández Canedo, marqués de Valdegamas was a Spanish writer, diplomat, politician, and Catholic political theologian.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Juan%20Donoso%20Cort%C3%A9s%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Juan_Donoso_Cort%C3%A9s","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Juan_Donoso_Cort%C3%A9s%2C_por_Federico_Madrazo.jpg","license":"Public domain","artist":"Federico de Madrazo y Kuntz","pd":1}},"jaime-balmes":{"extract":"Jaime Luciano Balmes y Urpiá was a Spanish philosopher, theologian, Catholic apologist, sociologist and political writer. Familiar with the doctrine of Saint Thomas Aquinas, Balmes was an original philosopher, who did not belong to any particular school or stream, and was called by Pope Pius XII the Prince of Modern Apologetics.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/5162","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jaime%20Balmes%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jaime_Balmes","kind":"about"}],"isidoreFolder":"Balmes, Rev. J_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Jaime_Balmes_%28Real_Academia_de_la_Historia%29%2C_cropped.jpg","license":"Public domain","artist":"Luis Brochetón y Muguruza","pd":1}},"antonio-rosmini":{"extract":"Antonio Francesco Davide Ambrogio Rosmini-Serbati, IC was an Italian Catholic priest and philosopher. He founded the Rosminians, officially the Institute of Charity, and pioneered the concept of social justice and Italian Liberal Catholicism.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Antonio%20Rosmini%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Antonio_Rosmini","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Hayez%2C_Ritratto_di_Antonio_Rosmini%2C_1853_%28cropped%29.jpg","license":"Public domain","artist":"Francesco Hayez","pd":1}},"alessandro-manzoni":{"extract":"Alessandro Francesco Tommaso Antonio Manzoni was an Italian philosopher, poet, playwright, and novelist. He is best known for the novel The Betrothed, generally ranked among the masterpieces of world literature. The novel, published in 1827, is a symbol of the Italian Risorgimento for its patriotic message, and also because it was a fundamental milestone in the development of the modern and unified Italian language.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/37500","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Alessandro%20Manzoni%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alessandro_Manzoni","kind":"about"}],"isidoreFolder":"Manzoni, Alessandro","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Francesco_Hayez_-_Ritratto_di_Alessandro_Manzoni.jpg","license":"Public domain","artist":"Francesco Hayez","pd":1}},"john-henry-newman":{"extract":"John Henry Newman was an English Catholic theologian, academic, philosopher, historian, writer, and poet. He was an important figure in the religious history of England in the 19th century.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/newman","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/8264","kind":"read"},{"label":"Newman Reader — complete works","url":"https://www.newmanreader.org/","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22John%20Henry%20Newman%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Henry_Newman","kind":"about"}],"isidoreFolder":"Newman, John Henry, Cdl., 1801-1890","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:John_Henry_Newman_1887_Portrait_Photograph_%283x4_cropped%29.jpg","license":"Public domain","artist":"Herbert Rose Barraud","pd":1}},"henry-edward-manning":{"extract":"Henry Edward Manning was an English prelate of the Catholic Church, and the second Archbishop of Westminster from 1865 until his death in 1892. He was ordained in the Church of England as a young man, but converted to Catholicism in the aftermath of the Gorham judgement.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Henry%20Edward%20Manning%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Henry_Edward_Manning","kind":"about"}],"isidoreFolder":"Manning, Card. Henry Edward, 1808-1892","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Henry_Edward_Manning%2C_negative%2C_1883_%28by_Alexander_Bassano%3B_NPG_x96182%29_%283x4_cropped%29.png","license":"Public domain","artist":"Alexander Bassano","pd":1}},"frederick-william-faber":{"extract":"Frederick William Faber was a noted English hymnwriter and theologian, who converted from Anglicanism to Catholicism in 1845. He was ordained to the Catholic priesthood in 1847. His best-known work is the hymn \"Faith of Our Fathers\". He was a member of the Oratory of Saint Philip Neri.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Frederick%20William%20Faber%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Frederick_William_Faber","kind":"about"}],"isidoreFolder":"Faber, Frederick William, 1814-1863","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Frederick_William_Faber.jpg","license":"Public domain","artist":"Joseph Brown, engraver","pd":1}},"nicholas-wiseman":{"extract":"Nicholas Patrick Stephen Wiseman was an English Catholic prelate who served as the first Archbishop of Westminster upon the re-establishment of the Catholic hierarchy in England and Wales in 1850. He was made a cardinal in 1850.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/49787","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Nicholas%20Wiseman%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Nicholas_Wiseman","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Nicholas_Wiseman_NPG.jpg","license":"Public domain","artist":"Herbert Watkins (died 1916)","pd":1}},"orestes-brownson":{"extract":"Orestes Augustus Brownson was an American intellectual, activist, preacher, labor organizer, and writer. Brownson was also a noted Catholic convert. Brownson was a publicist, a career which spanned his affiliation with the New England Transcendentalists through his subsequent conversion to Roman Catholicism.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/802","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Orestes%20Brownson%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Orestes_Brownson","kind":"about"}],"isidoreFolder":"Brownson, Orestes","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Orestes_Brownson_by_GPA_Healy%2C_1863.jpg","license":"Public domain","artist":"George Peter Alexander Healy","pd":1}},"isaac-hecker":{"extract":"Isaac Thomas Hecker, CSP, was an American Catholic priest who founded the Paulist Fathers, a religious congregation for men.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/50874","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Isaac%20Hecker%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Isaac_Hecker","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Father_Isaac_Hecker.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"james-gibbons":{"extract":"James Gibbons was an American Catholic prelate who served as Archbishop of Baltimore for more than forty years, from 1877 until his death in 1921. Created a cardinal in 1886, he was the second American cardinal, after John McCloskey.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/32691","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22James%20Gibbons%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/James_Gibbons","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:GibbonsPhotoStanding.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"matthias-joseph-scheeben":{"extract":"Matthias Joseph Scheeben was a German Catholic priest and theologian. He is regarded as \"one of the greatest minds of modern Catholic theology.\"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Matthias%20Joseph%20Scheeben%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Matthias_Joseph_Scheeben","kind":"about"}],"isidoreFolder":"Scheeben, Matthias Joseph","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Matthias_Joseph_Scheeben.jpg","license":"CC BY-SA 4.0","artist":"Tohma ( talk ) photo","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/Matthias_Joseph_Scheeben.jpg/330px-Matthias_Joseph_Scheeben.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"joseph-kleutgen":{"extract":"Joseph Wilhelm Karl Kleutgen was a German Jesuit theologian and philosopher. He was a member of the Society of Jesus, and contributed significantly to the establishment of Neo-scholasticism.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Joseph%20Kleutgen%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Joseph_Kleutgen","kind":"about"}],"isidoreFolder":"Kleutgen, Josef, S.J_"},"prosper-gueranger":{"extract":"Prosper Louis Pascal Guéranger was a French priest and Benedictine monk, who served for nearly 40 years as the abbot of the monastery of Solesmes. Through the new Abbey of Solesmes, he became the founder of the French Benedictine Congregation, which re-established Benedictine monastic life in France after it had been wiped out by the French Revolution. Guéranger was the author of The Liturgical Year, a popular commentary which covers every day of the Catholic Church's liturgical cycles in 15 volumes. He was well regarded by Pope Pius IX, and was a proponent of the dogmas of the Immaculate Conc","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Prosper%20Gu%C3%A9ranger%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Prosper_Gu%C3%A9ranger","kind":"about"}],"isidoreFolder":"Gueranger, Prosper, O.S.B_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Prosper.jpg","license":"Public domain","artist":"Claude Ferdinand Gaillard","pd":1}},"jean-marie-vianney":{"extract":"John Vianney was a French Catholic priest and member of the Third Order of Mary who is often referred to as the Curé d'Ars. Canonized a saint in 1925, he is known for his priestly and pastoral work in his parish in Ars, France, resulting in the radical spiritual transformation of the community and its surroundings. Catholics note his saintly life, mortification, persevering ministry in the sacrament of confession, and ardent devotion to the Blessed Virgin Mary. His feast day is 4 August. He is the patron saint of parish priests.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jean-Marie%20Vianney%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Vianney","kind":"about"}],"isidoreFolder":"Vianney, St. Jean-Marie Baptiste, Cure of Ars, 1786-1859","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:S%C3%A3o_Jo%C3%A3o_Maria_Vianney.png","license":"CC BY-SA 4.0","artist":"BarãoPandora","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e5/S%C3%A3o_Jo%C3%A3o_Maria_Vianney.png/330px-S%C3%A3o_Jo%C3%A3o_Maria_Vianney.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"anne-catherine-emmerich":{"extract":"Anne Catherine Emmerich, CRV was a Catholic\nAugustinian canoness of the Congregation of Windesheim. During her lifetime, she was a mystic, Marian visionary and stigmatist.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/emmerich","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Anne%20Catherine%20Emmerich%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Anne_Catherine_Emmerich","kind":"about"}],"isidoreFolder":"Emmerich, Bl. Anne Catherine","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Anna_Katharina_Emmerick_-_Gabriel_von_Max_1885.jpg","license":"Public domain","artist":"Gabriel von Max","pd":1}},"frederic-ozanam":{"extract":"Antoine-Frédéric Ozanam was a French Catholic literary scholar, lawyer, journalist and equal rights advocate. He founded with fellow students the Conference of Charity, later known as the Society of Saint Vincent de Paul. He was beatified by Pope John Paul II in the Cathedral of Notre-Dame de Paris in 1997. His feast day is 9 September.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Fr%C3%A9d%C3%A9ric%20Ozanam%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Fr%C3%A9d%C3%A9ric_Ozanam","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Fr%C3%A9d%C3%A9ric_Ozanam_2.jpg","license":"Public domain","artist":"Engraving by Antoine Maurin known as \"Maurin the Elder\" (1793-1860) from a drawing by Louis Janmot (1814-1892)","pd":1}},"henri-dominique-lacordaire":{"extract":"Jean-Baptiste Henri-Dominique Lacordaire, OP, often styled Henri-Dominique Lacordaire, was a French Catholic priest, journalist, theologian and political activist. He re-established the Dominican Order in post-Revolutionary France. Lacordaire was reputed to be the greatest pulpit orator of the nineteenth century.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Henri-Dominique%20Lacordaire%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jean-Baptiste_Henri_Lacordaire","kind":"about"}],"isidoreFolder":"Lacordaire, Henri-Dominique, O.P., 1802-1861","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Portrait_of_Dominique_Lacordaire.jpg","license":"Public domain","artist":"Théodore Chassériau","pd":1}},"louis-veuillot":{"extract":"Louis Veuillot was a French journalist and writer who helped to popularize ultramontanism.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/56831","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Louis%20Veuillot%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Louis_Veuillot","kind":"about"}],"isidoreFolder":"Veuillot, Louis","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Veuillot%2C_by_Nadar.jpg","license":"Public domain","artist":"Nadar (Life time: (1820 – 1910))","pd":1}},"therese-of-lisieux":{"extract":"Thérèse of Lisieux, religious name Therese of the Child Jesus and the Holy Face was a French Discalced Carmelite. She is popularly known in English as the \"Little Flower of Jesus\", or simply the \"Little Flower\", and in French and German as the \"little Therese\", in contrast to Teresa of Avila, who is called the \"great Therese\").","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/therese","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/6923","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Th%C3%A9r%C3%A8se%20of%20Lisieux%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Th%C3%A9r%C3%A8se_of_Lisieux","kind":"about"}],"isidoreFolder":"Lisieux, Therese de, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Teresa-de-Lisieux.jpg","license":"Public domain","artist":"Céline Martin","pd":1}},"john-bosco":{"extract":"John Melchior Bosco, SDB, popularly known as Don Bosco, was an Italian Catholic priest, educator, and writer. While working in Turin, where the population suffered many of the ill effects of industrialization and urbanization, he dedicated his life to the betterment and education of street children, juvenile delinquents, and other disadvantaged youth. He developed teaching methods based on love rather than punishment, a method that became known as the Salesian Preventive System.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22John%20Bosco%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Bosco","kind":"about"}],"isidoreFolder":"Bosco, St. John","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Don_Bosco_%40_Torino%2C_1880_%28original%29.jpg","license":"Public domain","artist":"Attributed to Carlo Felice Deasti","pd":1}},"gerard-manley-hopkins":{"extract":"Gerard Manley Hopkins was an English poet and Jesuit priest.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/25314","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Gerard%20Manley%20Hopkins%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gerard_Manley_Hopkins","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:GerardManleyHopkins.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"francis-thompson":{"extract":"Francis Joseph Thompson was an English poet and Catholic mystic. At the behest of his father, a doctor, he entered medical school at the age of 18, but at 26 left home to pursue his talent as a writer and poet. He spent three years on the streets of London, supporting himself with menial labour, becoming addicted to opium which he took to relieve a nervous problem.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/608","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Francis%20Thompson%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Francis_Thompson","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Francis_Thompson_at_19.jpg","license":"Public domain","artist":"Published by Herder, MO, USA","pd":1}},"coventry-patmore":{"extract":"Coventry Kersey Dighton Patmore was an English poet and literary critic. He is best known for his book of poetry The Angel in the House (1854), a narrative poem about the Victorian ideal of a happy marriage.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/1354","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Coventry%20Patmore%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Coventry_Patmore","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Portrait_of_Coventry_Patmore.jpg","license":"Public domain","artist":"John Singer Sargent","pd":1}},"alice-meynell":{"extract":"Alice Christiana Gertrude Meynell was a British writer, editor, critic, and suffragist, now remembered mainly as a poet. She was considered for the position of Poet Laureate of the United Kingdom twice, first in 1892 on the death of Alfred, Lord Tennyson, and later in 1913 on the death of Alfred Austin, but was never appointed to the position.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/546","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Alice%20Meynell%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alice_Meynell","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Alice_Meynell_7.jpg","license":"Public domain","artist":"Published by Herder, MO, USA","pd":1}},"leon-bloy":{"extract":"Léon Bloy was a French Catholic novelist, essayist, pamphleteer, and satirist, known additionally for his eventual and passionate defense of Catholicism and for his influence within French Catholic circles.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/37756","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22L%C3%A9on%20Bloy%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/L%C3%A9on_Bloy","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:L%C3%A9on_Bloy_Portrait_1887.jpg","license":"Public domain","pd":1}},"joris-karl-huysmans":{"extract":"Charles-Marie-Georges Huysmans was a French novelist and art critic who published his works as Joris-Karl Huysmans. He is most famous for the novel À rebours. He supported himself by way of a 30-year career in the French civil service.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/4324","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Joris-Karl%20Huysmans%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Joris-Karl_Huysmans","kind":"about"}],"isidoreFolder":"Huysmans, J.-K_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Huysmans_-_photo_Taponier.jpg","license":"Public domain","artist":"Frédéric Boissonnas / André Taponier","pd":1}},"ludwig-von-pastor":{"extract":"Ludwig Pastor, ennobled as Ludwig von Pastor, Freiherr von Campersfelden, was a German historian and diplomat for Austria. He became one of the most important Catholic historians of his time and is most notable for his History of the Popes. He was raised to the nobility by the Emperor Franz Joseph I in 1908 and was nominated for the Nobel Prize in Literature six times.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Ludwig%20von%20Pastor%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ludwig_von_Pastor","kind":"about"}],"isidoreFolder":"Pastor, Ludwig","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Ludwig_von_Pastor.JPG","license":"Public domain","artist":"Author unknown","pd":1}},"joseph-deharbe":{"extract":"Joseph Deharbe was a French Jesuit theologian and catechist.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Joseph%20Deharbe%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Joseph_Deharbe","kind":"about"}]},"adolphe-tanquerey":{"extract":"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Adolphe%20Tanquerey%22","kind":"search"}],"isidoreFolder":"Tanquerey, Adolphe, 1854-1932"},"columba-marmion":{"extract":"Columba Marmion, O.S.B was an Irish Benedictine monk and the third abbot of Maredsous Abbey in Belgium. Beatified by Pope John Paul II on September 3, 2000, Columba was one of the most popular and influential Catholic authors of the 20th century. His books are considered spiritual classics.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Columba%20Marmion%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Columba_Marmion","kind":"about"}],"isidoreFolder":"Marmion, Abbot Columba, O.S.B., 1858-1923","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Columba_Marmion_%281858-1923%29.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"jean-baptiste-chautard":{"extract":"Jean-Baptiste Chautard OCSO was a French Trappist abbot and religious writer.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jean-Baptiste%20Chautard%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jean-Baptiste_Chautard","kind":"about"}],"isidoreFolder":"Chautard, Dom Jean-Baptiste, O.C.S.O_"},"elizabeth-of-the-trinity":{"extract":"Elizabeth of the Trinity, OCD, born Élisabeth Catez, was a French Discalced Carmelite, a mystic, and a spiritual writer. She was known for the depth of her spiritual growth as a Carmelite as well as bleak periods in which her religious calling was perceived to be unsure according to those around her; she however was acknowledged for her persistence in pursuing the will of God and in devoting herself to the charism of the Carmelites.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/elizabeth","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Elizabeth%20of%20the%20Trinity%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Elizabeth_of_the_Trinity","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Visage_d%27Elisabeth_de_la_Trinit%C3%A9.jpg","license":"CC BY-SA 3.0","artist":"Willuconquer","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Visage_d%27Elisabeth_de_la_Trinit%C3%A9.jpg/330px-Visage_d%27Elisabeth_de_la_Trinit%C3%A9.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"faustina-kowalska":{"extract":"Maria Faustyna Kowalska of the Blessed Sacrament, OLM was a Polish Catholic religious sister and mystic. Faustyna, popularly spelled Faustina in English, had apparitions of Jesus Christ which inspired the Catholic devotion to the Divine Mercy, therefore she is sometimes called the \"secretary\" of Divine Mercy.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Faustina%20Kowalska%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Faustina_Kowalska","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Maria_Faustyna_Kowalska.jpg","license":"Public domain","artist":"Stanisław Sztama","pd":1}},"maximilian-kolbe":{"extract":"Maximilian Maria Kolbe, OFM Conv was a Polish Conventual Franciscan friar, priest, missionary, and martyr. He volunteered to die in place of a man named Franciszek Gajowniczek in the German death camp of Auschwitz, located in German-occupied Poland during World War II. He had been active in promoting the veneration of the Immaculate Virgin Mary, founding and supervising the monastery of Niepokalanów near Warsaw, operating an amateur-radio station (SP3RN), and founding or running several other organizations and publications.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Maximilian%20Kolbe%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Maximilian_Kolbe","kind":"about"}],"isidoreFolder":"Kolbe, Maximilian Maria, O.F.M_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Fr.Maximilian_Kolbe_in_1936.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"edith-stein":{"extract":"\n\nEdith Stein was a German philosopher who converted to Catholicism and became a Discalced Carmelite. She was murdered in the gas chamber at the Auschwitz II-Birkenau concentration camp on 9 August 1942, and is canonized as a martyr of the Catholic Church; she is also one of six patron saints of Europe.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Edith%20Stein%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Edith_Stein","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Edith_Stein_%28ca._1938-1939%29.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"pio-of-pietrelcina":{"extract":"Pio of Pietrelcina, widely known as Padre Pio, Latin: Pater Pius) was an Italian friar of the Order of Friars Minor Capuchin, priest, stigmatist and mystic. He is venerated as a saint in the Catholic Church, and the Palmarian Church; his feast day is celebrated on 23 September.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Pio%20of%20Pietrelcina%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Padre_Pio","kind":"about"}],"isidoreFolder":"Padre Pio of Pietrelcina, O.F.M. Cap_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Padre_Pio_portraitFXD.jpg","license":"Public domain","artist":"File:Padre Pio portrait.jpg : The original uploader was Manfredonia at Italian Wikipedia . derivative work: MisterNox","pd":1}},"josemaria-escriva":{"extract":"Josemaría Escrivá de Balaguer y Albás was a Spanish Catholic priest who founded Opus Dei, an organization of laypeople and priests dedicated to the principle of everyday holiness. He was canonized by Pope John Paul II in 2002.","qidWork":null,"links":[{"label":"Escrivá Works","url":"https://escriva.org/en/","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Josemar%C3%ADa%20Escriv%C3%A1%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Josemar%C3%ADa_Escriv%C3%A1","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Josemaria_Escriva.jpg","license":"CC BY-SA 2.0","artist":"Oficina de Información de la Prelatura del Opus Dei en España","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Josemaria_Escriva.jpg/330px-Josemaria_Escriva.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"g-k-chesterton":{"extract":"Gilbert Keith Chesterton was an English Christian apologist writer. Chesterton's wit, paradoxical style, and defence of tradition made him a dominant figure in early 20th-century literature.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/chesterton","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/80","kind":"read"},{"label":"Society of G. K. Chesterton","url":"https://www.chesterton.org/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22G.%20K.%20Chesterton%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/G._K._Chesterton","kind":"about"}],"isidoreFolder":"Chesterton, Gilbert Keith","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Gilbert_Chesterton.jpg","license":"Public domain","artist":"Ernest Herbert Mills","pd":1}},"hilaire-belloc":{"extract":"Joseph Hilaire Pierre René Belloc was a French-English writer and political activist. Belloc was considered one of the most versatile authors of the 20th century, producing essays on history, politics and economics as well as poetry, travelogues and satire. His Catholicism had a strong effect on his works.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/2437","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Hilaire%20Belloc%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hilaire_Belloc","kind":"about"}],"isidoreFolder":"Belloc, Hilaire","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Hilaire_Belloc_Portrait_circa_1917.jpg","license":"Public domain","artist":"Keystone/Hulton Archive","pd":1}},"robert-hugh-benson":{"extract":"Robert Hugh Benson AFSC KC*SG KGCHS was an English Catholic priest and writer. First an Anglican priest, he was received into the Catholic Church in 1903 and ordained therein the next year. He was also a prolific writer of fiction, writing the notable dystopian novel Lord of the World, as well as Come Rack! Come Rope!.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/4052","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Robert%20Hugh%20Benson%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Robert_Hugh_Benson","kind":"about"}],"isidoreFolder":"Benson, Robert Hugh","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Monsignor_R._H._Benson_in_Oct._1912%2C_Aged_40.jpg","license":"Public domain","artist":"Photograph by G. Jerrard","pd":1}},"maurice-baring":{"extract":"Maurice Baring was an English man of letters, known as a dramatist, poet, novelist, translator and essayist, and also as a travel writer and war correspondent, with particular knowledge of Russia. During World War I, Baring served in the Intelligence Corps and Royal Air Force.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/937","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Maurice%20Baring%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Maurice_Baring","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Maurice_Baring_Notable_Londoners_1922.jpg","license":"Public domain","artist":"photographer: Bertram Park","pd":1}},"ronald-knox":{"extract":"Ronald Arbuthnott Knox was an English Catholic priest, theologian, author, and radio broadcaster. Educated at Eton and Balliol College, Oxford, where he earned a high reputation as a classicist, Knox was ordained as a priest of the Church of England in 1912. He was a fellow and chaplain of Trinity College, Oxford until he resigned from those positions following his conversion to Catholicism in 1917. Knox became a Catholic priest in 1918, continuing in that capacity his scholarly and literary work.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/50428","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Ronald%20Knox%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ronald_Knox","kind":"about"}],"isidoreFolder":"Knox, Ronald Arbuthnott, 1888-1957"},"christopher-dawson":{"extract":"Christopher Henry Dawson was a British Catholic historian and independent scholar, who wrote many books on cultural history and argued for the necessity for Western culture to be in continuity with Christianity not to stagnate and deteriorate. Dawson has been called \"the greatest English-speaking Catholic historian of the twentieth century\" and was recognized as being able to expound his thought to \"Catholic and Protestant, Christian and non-Christian\".","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Christopher%20Dawson%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Christopher_Dawson","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Christopher_Dawson_Portrait.jpg","license":"CC0","artist":"Levan Ramishvili","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","pd":1}},"j-r-r-tolkien":{"extract":"John Ronald Reuel Tolkien was an English writer and academic philologist. He was the author of the high fantasy works The Hobbit (1937) and The Lord of the Rings (1954–1955).","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/42379","kind":"read"},{"label":"The Tolkien Society","url":"https://www.tolkiensociety.org/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22J.%20R.%20R.%20Tolkien%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/J._R._R._Tolkien","kind":"about"}],"isidoreFolder":"Tolkien, J. R. R_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:J._R._R._Tolkien%2C_ca._1925.jpg","license":"Public domain","artist":"Unknown photo studio commissioned by Tolkien's students 1925/6 (private communication from Catherine McIlwaine, Tolkien Archivist, Bodleian Library)","pd":1}},"evelyn-waugh":{"extract":"Arthur Evelyn St. John Waugh was an English writer of novels, biographies, and travel books; he was also a prolific journalist and book reviewer. His most famous works include the early satires Decline and Fall (1928) and A Handful of Dust (1934), the novel Brideshead Revisited (1945), and the Second World War trilogy Sword of Honour (1952–1961). He is recognised as one of the great prose stylists of the English language in the 20th century.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/59113","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Evelyn%20Waugh%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Evelyn_Waugh","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Evelynwaugh.jpeg","license":"Public domain","artist":"Carl Van Vechten (1880–1964)","pd":1}},"graham-greene":{"extract":"Henry Graham Greene was an English writer and journalist regarded by many as one of the leading novelists of the 20th century.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Graham%20Greene%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Graham_Greene","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Graham_Greene_angol_%C3%ADr%C3%B3%2C_1975_Fortepan_84697.jpg","license":"CC BY-SA 3.0","artist":"FOTO:Fortepan — ID 84697 : Adományozó/Donor: Magyar Hírek folyóirat. archive copy at the Wayback Machine","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3e/Graham_Greene_angol_%C3%ADr%C3%B3%2C_1975_Fortepan_84697.jpg/330px-Graham_Greene_angol_%C3%ADr%C3%B3%2C_1975_Fortepan_84697.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"muriel-spark":{"extract":"Dame Muriel Sarah Spark was a Scottish novelist, short story writer, poet and essayist.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Muriel%20Spark%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Muriel_Spark","kind":"about"}]},"flannery-o-connor":{"extract":"Mary Flannery O'Connor was an American novelist, short story writer, and essayist. She wrote two novels and 31 short stories, as well as a number of reviews and commentaries.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Flannery%20O%27Connor%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Flannery_O'Connor","kind":"about"}],"isidoreFolder":"O'Connor, Flannery","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Flannery-O%27Connor_1947.jpg","license":"CC BY-SA 3.0","artist":"Cmacauley","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},"img":"https://upload.wikimedia.org/wikipedia/commons/7/7e/Flannery-O%27Connor_1947.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled"},"walker-percy":{"extract":"Walker Percy, OblSB was an American writer whose works explored alienation, existentialism, faith, and the limits of science in modern life. A prominent Southern and Catholic literary figure, Percy is especially noted for his novels set in New Orleans. His first, The Moviegoer (1961), won the National Book Award for Fiction.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Walker%20Percy%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Walker_Percy","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Walker_Percy.jpg","license":"CC0","artist":"Aspen Institute Pictures","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","pd":1}},"j-f-powers":{"extract":"James Farl Powers was an American novelist and short story writer who often drew his inspiration from developments in the Catholic Church, and was known for his studies of Catholic priests in the Midwest. Although not a priest himself, he is known for having captured a \"clerical idiom\" in postwar North America. His first novel, Morte d'Urban, won the 1963 National Book Award for Fiction.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22J.%20F.%20Powers%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/J._F._Powers","kind":"about"}]},"sigrid-undset":{"extract":"Sigrid Undset was a Danish-born Norwegian novelist. She was awarded the 1928 Nobel Prize in Literature.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/35742","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Sigrid%20Undset%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Sigrid_Undset","kind":"about"}],"isidoreFolder":"Undset, Sigrid, T.O.P_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Sigrid_Undset_1928.jpg","license":"Public domain","artist":"Aage Remfeldt / Aage Rasmussen (1889-1983)","pd":1}},"francois-mauriac":{"extract":"François Charles Mauriac was a French novelist, dramatist, critic, poet, and journalist, a member of the Académie française, and laureate of the Nobel Prize in Literature (1952). He was awarded the Grand Cross of the Légion d'honneur in 1958.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/45991","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Fran%C3%A7ois%20Mauriac%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Fran%C3%A7ois_Mauriac","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Fran%C3%A7ois_Mauriac_redux.jpg","license":"Public domain","artist":"Agence de presse Meurisse","pd":1}},"georges-bernanos":{"extract":"Louis Émile Clément Georges Bernanos was a French author, and a soldier in World War I. A Catholic with monarchist leanings, he was critical of elitist thought and was opposed to what he identified as defeatism. He believed this had led to France's defeat and eventual occupation by Germany in 1940 during World War II. His two best-known novels Sous le soleil de Satan (1926) and the Journal d'un curé de campagne (1936) both revolve around a parish priest who combats evil and despair in the world. Most of his novels have been translated into English and frequently published in both Great Britain","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/56147","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Georges%20Bernanos%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Georges_Bernanos","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Georges-Bernanos.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"paul-claudel":{"extract":"Paul Claudel was a French poet, dramatist and diplomat, and the younger brother of the sculptor Camille Claudel. He is most famous for his verse dramas, which often convey his devout Catholicism, and for institutionalizing his sister.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/43686","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Paul%20Claudel%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Paul_Claudel","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Paul_Claudel_cph.3b31258.jpg","license":"Public domain","artist":"Underwood & Underwood","pd":1}},"charles-peguy":{"extract":"Charles Pierre Péguy was a French poet, essayist, and editor. His two main philosophies were socialism and nationalism; by 1908 at the latest, after years of uneasy agnosticism, he had become a believing Catholic. From that time, Catholicism strongly influenced his works. Péguy was killed in World War I at age 41 by German invading forces near Villeroy, Seine-et-Marne.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/49150","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Charles%20P%C3%A9guy%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Charles_P%C3%A9guy","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Charles_P%C3%A9guy_by_Eug%C3%A8ne_Pirou%2C_cropped.png","license":"Public domain","artist":"Eugène Pirou","pd":1}},"gertrud-von-le-fort":{"extract":"Baroness Gertrud von Le Fort was a German writer.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Gertrud%20von%20le%20Fort%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gertrud_von_Le_Fort","kind":"about"}],"isidoreFolder":"von le Fort, Gertrud","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Gertrud_v_Le_Fort_c1935.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"shusaku-endo":{"extract":"Shūsaku Endō  was a Japanese writer who wrote from the perspective of a Japanese Catholic. Internationally, he is known for his 1966 historical fiction novel Silence, adapted into a 2016 film by Martin Scorsese. He was the laureate of several prestigious literary accolades, including the Akutagawa Prize and the Order of Culture, and was inducted into the Roman Catholic Order of St. Sylvester by Pope Paul VI.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Sh%C5%ABsaku%20End%C5%8D%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Sh%C5%ABsaku_End%C5%8D","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Shusaku-Endo-1.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"henryk-sienkiewicz":{"extract":"Henryk Adam Aleksander Pius Sienkiewicz, also known by the pseudonym Litwos, was a Polish epic writer. He is remembered for his historical novels, such as the Trilogy series and especially for his internationally known best-seller Quo Vadis (1895–1896).","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/sienkiewicz","kind":"read"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/1052","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Henryk%20Sienkiewicz%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Henryk_Sienkiewicz","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Henryk_Sienkiewicz_ca_1885_%2845871548%29_%28cropped%29.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"lew-wallace":{"extract":"Lewis Wallace was an American lawyer, Union general in the American Civil War, governor of New Mexico Territory, politician, diplomat, artist, inventor, and author from Indiana. Among his novels and biographies, Wallace is best known for his historical adventure story, Ben-Hur: A Tale of the Christ (1880), a bestselling novel that has been called \"the most influential Christian book of the nineteenth century.\"","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/836","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Lew%20Wallace%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Lew_Wallace","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Lewis_Wallace.jpg","license":"Public domain","artist":"Materialscientist","pd":1}},"willa-cather":{"extract":"Willa Sibert Cather was an American writer known for her novels of life on the Great Plains, including O Pioneers!, The Song of the Lark, and My Ántonia. In 1923, she was awarded the Pulitzer Prize for One of Ours, a novel set during World War I.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/22","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Willa%20Cather%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Willa_Cather","kind":"about"}],"isidoreFolder":"Cather, Willa","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Cather_Van_Vechten.jpg","license":"Public domain","artist":"Carl Van Vechten","pd":1}},"caryll-houselander":{"extract":"Caryll Houselander was an English lay Roman Catholic ecclesiastical artist, mystic, popular religious writer and poet.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Caryll%20Houselander%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Caryll_Houselander","kind":"about"}],"isidoreFolder":"Houselander, Caryll"},"dorothy-day":{"extract":"Dorothy May Day was an American journalist, social activist and anarchist who, after a bohemian youth, became a Catholic. She was perhaps the best-known political radical among American Catholics.","qidWork":null,"links":[{"label":"Catholic Worker — Dorothy Day collection","url":"https://www.catholicworker.org/dorothyday/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Dorothy%20Day%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Dorothy_Day","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Dorothy_Day_Vivian_Cherry_Portrait_Edit.jpg","license":"Public domain","artist":"Vivian Cherry","pd":1}},"peter-maurin":{"extract":"Peter Maurin was a French Catholic social activist, theologian, and De La Salle Brother who founded the Catholic Worker Movement in 1933 with Dorothy Day.","qidWork":null,"links":[{"label":"Catholic Worker Movement","url":"https://www.catholicworker.org/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Peter%20Maurin%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Peter_Maurin","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Peter_Maurin.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"thomas-merton":{"extract":"Thomas Merton, religious name M. Louis, was an American Trappist monk, Catholic priest, theologian, mystic, poet, and writer. He was a professed member of the Abbey of Our Lady of Gethsemani, near Bardstown, Kentucky, living there from 1941 to his death.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/merton","kind":"read"},{"label":"Thomas Merton Center","url":"https://merton.org/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Thomas%20Merton%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Thomas_Merton","kind":"about"}]},"fulton-j-sheen":{"extract":"Fulton John Sheen was an American Catholic prelate who served as the Bishop of Rochester from 1966 to 1969. He was known for his preaching, especially on television and radio.","qidWork":null,"links":[{"label":"Fulton Sheen archive (Archbishop Fulton John Sheen Foundation)","url":"https://www.celebratesheen.com/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Fulton%20J.%20Sheen%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Fulton_J._Sheen","kind":"about"}],"isidoreFolder":"Sheen, Abp. Fulton J_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Fulton_J._Sheen_NYWTS_%284x5_cropped%29.jpg","license":"Public domain","artist":"Fred Palumbo , World Telegram staff photographer","pd":1}},"frank-sheed":{"extract":"Francis Joseph Sheed was an Australian-born lawyer, Catholic writer, publisher, speaker, and lay theologian. He and his wife Maisie Ward were the names behind the imprint Sheed & Ward and as forceful public lecturers in the Catholic Evidence Guild.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Frank%20Sheed%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Frank_Sheed","kind":"about"}],"isidoreFolder":"Sheed, Frank"},"maisie-ward":{"extract":"Mary Josephine \"Maisie\" Ward Sheed was a British writer, speaker, and publisher, well known for her biography of G. K. Chesterton.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Maisie%20Ward%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Maisie_Ward","kind":"about"}]},"jacques-maritain":{"extract":"Jacques Maritain was a French Catholic philosopher and theologian. An author of more than 60 books, he helped to revive Thomas Aquinas for modern times, and was influential in the development and drafting of the Universal Declaration of Human Rights. Pope Paul VI presented his \"Message to Men of Thought and of Science\" at the close of Vatican II to Maritain, his long-time friend and mentor. The same pope had seriously considered making him a lay cardinal, but Maritain rejected it.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jacques%20Maritain%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jacques_Maritain","kind":"about"},{"label":"Jacques Maritain Center (Notre Dame)","url":"https://maritain.nd.edu/","kind":"site"}],"isidoreFolder":"Maritain, Jacques","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Maritain_Jacques.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"raissa-maritain":{"extract":"Raïssa Maritain was a Russian-born French Catholic philosopher and poet. She was the wife of Jacques Maritain, with whom she worked and whose companion she was for more than half a century, at the center of a circle of French Catholic intellectuals. Her memoir, Les Grandes Amitiés, which won the prix du Renouveau français, chronicles this. Jacques Maritain, Raïssa and her sister Vera (1886-1959) formed what would be called \"the three Maritains\".","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Ra%C3%AFssa%20Maritain%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ra%C3%AFssa_Maritain","kind":"about"}],"isidoreFolder":"Maritain, Raissa","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Raissa_Maritain_1905_portrait_%283x4_cropped%29.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"etienne-gilson":{"extract":"Étienne Henri Gilson was a French Catholic philosopher and historian of philosophy. A scholar of medieval philosophy, he originally specialised in the thought of Descartes; he also philosophized in the \"existential\" tradition of Thomas Aquinas, although he did not consider himself a neo-Thomist philosopher. In 1946, he attained the distinction of being elected an \"Immortal\" (member) of the Académie française. He was nominated for the Nobel Prize in Literature.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22%C3%89tienne%20Gilson%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/%C3%89tienne_Gilson","kind":"about"}],"isidoreFolder":"Gilson, Etienne","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Etienne_Gilson_%C3%A2g%C3%A9.jpg","license":"CC BY-SA 4.0","artist":"IsidoreHendrix","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/Etienne_Gilson_%C3%A2g%C3%A9.jpg/330px-Etienne_Gilson_%C3%A2g%C3%A9.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"reginald-garrigou-lagrange":{"extract":"Réginald Marie Garrigou-Lagrange was a French Dominican friar, philosopher and theologian. As a neo-Thomist, he is recognized along with Édouard Hugon and Martin Grabmann as a distinguished theologian of the 20th century. As professor at the Pontifical University of Saint Thomas Aquinas, he taught dogmatic and spiritual theology in Rome from 1909 to 1959. There he wrote The Three Ages of the Interior Life in 1938.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22R%C3%A9ginald%20Garrigou-Lagrange%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/R%C3%A9ginald_Garrigou-Lagrange","kind":"about"}],"isidoreFolder":"Garrigou-Lagrange, Reginald, O.P_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Garrigou1.jpeg","license":"Public domain","artist":"Lex.mercurio","pd":1}},"antonin-dalmace-sertillanges":{"extract":"Antonin-Gilbert Sertillanges, OP, known in religion as Antonin-Dalmace Sertillanges, was a French Catholic philosopher and spiritual writer. He was a member of the Dominican Order.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Antonin-Dalmace%20Sertillanges%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Antonin_Sertillanges","kind":"about"}],"isidoreFolder":"Sertillanges, A. D., O.P_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Antonin-Dalmace_Sertillanges.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"josef-pieper":{"extract":"Josef Pieper was a German Catholic philosopher and an important figure in the resurgence of interest in the thought of Thomas Aquinas in early-to-mid 20th-century philosophy. Among his most notable works are The Four Cardinal Virtues: Prudence, Justice, Fortitude, Temperance; Leisure, the Basis of Culture; and Guide to Thomas Aquinas.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Josef%20Pieper%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Josef_Pieper","kind":"about"}],"isidoreFolder":"Pieper, Josef","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Pieper.png","license":"CC BY 4.0","artist":"Muesse","licenseUrl":"https://creativecommons.org/licenses/by/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/Pieper.png/330px-Pieper.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"dietrich-von-hildebrand":{"extract":"Dietrich Richard Alfred von Hildebrand was a German Catholic philosopher and religious writer.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Dietrich%20von%20Hildebrand%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Dietrich_von_Hildebrand","kind":"about"}],"isidoreFolder":"von Hildebrand, Dietrich, 1889-1977","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Dietrich_von_Hildebrand_%281889%E2%80%931977%29_%C2%A9_Max_Fenichel_%281885%E2%80%931942%29_OeNB_9802368.png","license":"Public domain","artist":"Max Fenichel","pd":1}},"romano-guardini":{"extract":"Romano Guardini was an Italian, naturalized German Catholic priest, philosopher and theologian.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/26362","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Romano%20Guardini%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Romano_Guardini","kind":"about"}],"isidoreFolder":"Guardini, Romano","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Romano_Guardini_um_1920.JPG","license":"Public domain","artist":"Author unknown","pd":1}},"karl-adam":{"extract":"Karl Adam was a German Catholic theologian, known for his work in the fields of ecclesiology and Christology. He spent most of his academic career at the University of Tübingen, where he published work influenced by Lebensphilosophie and German Romanticism including The Spirit of Catholicism (1924), which argued for an understanding of the church as a community and for a revitalisation of Christian faith. Following Adolf Hitler's rise to power in 1933, Adam sought a rapprochement between the Nazi regime and the German Catholic Church. In pursuit of this aim, he published work during the Nazi e","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Karl%20Adam%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Karl_Adam_(theologian)","kind":"about"}],"isidoreFolder":"Adam, Karl"},"henri-de-lubac":{"extract":"Henri-Marie Joseph Sonier de Lubac, better known as Henri de Lubac, was a French Jesuit priest and cardinal who is considered one of the most influential theologians of the 20th century. His writings and doctrinal research played a key role in shaping the Second Vatican Council.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Henri%20de%20Lubac%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Henri_de_Lubac","kind":"about"}],"isidoreFolder":"De Lubac, Henri"},"yves-congar":{"extract":"Yves Marie-Joseph Congar was a French Catholic cardinal and theologian. He is perhaps best known for his influence at the Second Vatican Council and for reviving theological interest in the Holy Spirit for the life of individuals and of the Church. He was created a cardinal in 1994.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Yves%20Congar%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Yves_Congar","kind":"about"}],"isidoreFolder":"Congar, Yves, 1904-1995","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Coat_of_arms_of_Yves_Congar.svg","license":"CC BY-SA 3.0","artist":"Collona , elements by SajoR","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fe/Coat_of_arms_of_Yves_Congar.svg/330px-Coat_of_arms_of_Yves_Congar.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"jean-danielou":{"extract":"Jean-Guenolé-Marie Daniélou was a French Jesuit and cardinal, an internationally well known patrologist, theologian and historian and a member of the Académie française.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jean%20Dani%C3%A9lou%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jean_Dani%C3%A9lou","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Giorgio_La_Pira_and_Jean_Dani%C3%A9lou.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"hans-urs-von-balthasar":{"extract":"Hans Urs von Balthasar was a Swiss theologian and Catholic priest who is considered one of the most important Catholic theologians of the 20th century. With Joseph Ratzinger and Henri de Lubac, he founded the theological journal Communio. Over the course of his life, he authored 85 books, over 500 articles and essays, and almost 100 translations. He is known for his 15-volume trilogy on beauty, goodness (Theo-Drama), and truth (Theo-Logic).","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Hans%20Urs%20von%20Balthasar%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hans_Urs_von_Balthasar","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:HUvB-microphone.jpg","license":"CC BY-SA 4.0","artist":"Author unknown","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/87/HUvB-microphone.jpg/330px-HUvB-microphone.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"adrienne-von-speyr":{"extract":"Adrienne von Speyr was a Swiss Catholic convert, physician, mystic, and author of some sixty books of spirituality and theology.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Adrienne%20von%20Speyr%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Adrienne_von_Speyr","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Adrienne_von_Speyr_older.jpg","license":"CC BY-SA 4.0","artist":"Author unknown","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cb/Adrienne_von_Speyr_older.jpg/330px-Adrienne_von_Speyr_older.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"karl-rahner":{"extract":"Karl Rahner was a German Jesuit priest and theologian who, alongside Henri de Lubac, Hans Urs von Balthasar, and Yves Congar, is considered to be one of the most influential Catholic theologians of the 20th-century. He was the brother of Hugo Rahner, also a Jesuit scholar.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Karl%20Rahner%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Karl_Rahner","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Karl_Rahner_by_Letizia_Mancino_Cremer.jpg","license":"CC BY-SA 4.0","artist":"Letizia Mancino Cremer (foto / upload Andy Nestl )","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/Karl_Rahner_by_Letizia_Mancino_Cremer.jpg/330px-Karl_Rahner_by_Letizia_Mancino_Cremer.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"bernard-lonergan":{"extract":"Bernard Joseph Francis Lonergan was a Canadian Jesuit priest, philosopher, and theologian regarded by many as one of the most important thinkers of the 20th century.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Bernard%20Lonergan%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Bernard_Lonergan","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Bernard_Lonergan_SJ.jpg","license":"CC BY-SA 4.0","artist":"BCLonergan","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://upload.wikimedia.org/wikipedia/commons/5/5e/Bernard_Lonergan_SJ.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled"},"louis-bouyer":{"extract":"Louis Bouyer was a French Catholic priest and former Lutheran minister who was received into the Catholic Church in 1939. During his religious career he was an influential theological thinker, especially in the fields of history, liturgy and spirituality, and as peritus helped shape the vision of the Second Vatican Council. He was a member of the Oratory of Jesus.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Louis%20Bouyer%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Louis_Bouyer","kind":"about"}],"isidoreFolder":"Bouyer, Louis"},"charles-journet":{"extract":"Charles Journet was a Swiss Roman Catholic cardinal and theologian.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Charles%20Journet%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Charles_Journet","kind":"about"}],"isidoreFolder":"Journet, Charles","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Armand_Niquille_%28Inv._302%29.jpg","license":"CC BY-SA 4.0","artist":"Fondation Armand Niquille","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/db/Armand_Niquille_%28Inv._302%29.jpg/330px-Armand_Niquille_%28Inv._302%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"ludwig-ott":{"extract":"Ludwig Ott was a Roman Catholic theologian and medievalist from Bavaria, Germany.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Ludwig%20Ott%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ludwig_Ott","kind":"about"}],"isidoreFolder":"Ott, Ludwig"},"joseph-pohle":{"extract":"","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/33972","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Joseph%20Pohle%22","kind":"search"}],"isidoreFolder":"Pohle, Joseph, 1852-1922"},"heinrich-denzinger":{"extract":"Heinrich Joseph Dominicus Denzinger was a leading German Catholic theologian and author of the Enchiridion symbolorum et definitionum, a work commonly referred to simply as Denzinger after him.","qidWork":null,"links":[{"label":"Denzinger at Internet Archive","url":"https://archive.org/search?query=denzinger+enchiridion","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Heinrich%20Denzinger%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Heinrich_Joseph_Dominicus_Denzinger","kind":"about"}],"isidoreFolder":"Denzinger, Heinrich"},"ronald-rolheiser":{"extract":"Ronald Rolheiser is a Canadian Catholic priest and theologian. He is a member of the Missionary Oblates of Mary Immaculate and teaches at the Oblate School of Theology in San Antonio, Texas.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Ronald%20Rolheiser%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ronald_Rolheiser","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Ronald_Rolheiser_speaks_at_Oblate_School_of_Theology.jpg","license":"CC BY-SA 4.0","artist":"GreenIsBest10","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7f/Ronald_Rolheiser_speaks_at_Oblate_School_of_Theology.jpg/330px-Ronald_Rolheiser_speaks_at_Oblate_School_of_Theology.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"henri-nouwen":{"extract":"Henri Jozef Machiel Nouwen was a Dutch Catholic priest, professor, writer and theologian. His interests were rooted primarily in psychology, pastoral ministry, spirituality, social justice and community. Over the course of his life, Nouwen was heavily influenced by the work of Anton Boisen, Thomas Merton, Rembrandt, Vincent van Gogh, and Jean Vanier.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/nouwen","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Henri%20Nouwen%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Henri_Nouwen","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:HenriNouwen.JPG","license":"CC BY-SA 3.0","artist":"Frank Hamilton","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/HenriNouwen.JPG/330px-HenriNouwen.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"jacques-philippe":{"extract":"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jacques%20Philippe%22","kind":"search"}],"isidoreFolder":"Philippe, Jacques"},"frank-duff":{"extract":"Francis Michael Duff, was an Irish lay Catholic and author known for bringing attention to the role of the Catholic laity during the Second Vatican Council of the Catholic Church. Duff had previously founded the Legion of Mary in his native city of Dublin, Ireland.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Frank%20Duff%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Frank_Duff","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Frank_Duff%2C_1934_%28cropped%29.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"eugene-boylan":{"extract":"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Eugene%20Boylan%22","kind":"search"}],"isidoreFolder":"Boylan, M. Eugene"},"dom-hubert-van-zeller":{"extract":"Hubert van Zeller was a Benedictine writer, sculptor, and theologian, noted for writing about human suffering from a Catholic perspective. Under the pseudonym Brother Choleric, he was also active as a cartoonist, making satirical drawings and comics about life in monasteries.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Dom%20Hubert%20van%20Zeller%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hubert_van_Zeller","kind":"about"}]},"walter-ciszek":{"extract":"Walter Joseph Ciszek, S.J. was a Polish-American Jesuit priest of the Russian Greek Catholic Church who clandestinely conducted missionary work in the Soviet Union between 1939 and 1963.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Walter%20Ciszek%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Walter_Ciszek","kind":"about"}]},"alfred-delp":{"extract":"Alfred Friedrich Delp was a German Jesuit religious priest and philosopher of the German Resistance. A member of the inner Kreisau Circle resistance group, he is considered a significant figure in Catholic resistance to Nazism. Falsely implicated in the failed 1944 July Plot to overthrow Adolf Hitler, Delp was arrested and sentenced to death. He was executed in 1945.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Alfred%20Delp%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alfred_Delp","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Alfred_Delp_Mannheim.jpg","license":"CC BY-SA 3.0","artist":"Graf Foto","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},"img":"https://upload.wikimedia.org/wikipedia/commons/3/38/Alfred_Delp_Mannheim.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled"},"titus-brandsma":{"extract":"Titus Brandsma was a Dutch Carmelite priest and a professor of philosophy. Brandsma was vehemently opposed to Nazi ideology and spoke out against it many times before World War II. He was imprisoned at the Dachau concentration camp, where he was murdered in 1942.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Titus%20Brandsma%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Titus_Brandsma","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:TitusBrandsma.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"jerome-lejeune":{"extract":"Jérôme Jean Louis Marie Lejeune was a French pediatrician and geneticist. He is best known for his work on the links between chromosome abnormalities like Down syndrome (trisomy-21) and cri du chat syndrome. He is also known for his subsequent strong opposition to the use of amniocentesis prenatal testing for eugenic purposes through selective and elective abortion. He was declared Venerable by Pope Francis on 21 January 2021.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22J%C3%A9r%C3%B4me%20Lejeune%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/J%C3%A9r%C3%B4me_Lejeune","kind":"about"}]},"russell-kirk":{"extract":"Russell Amos Kirk was an American political philosopher, moralist, historian, social critic, literary critic, lecturer, author, and novelist who influenced 20th-century American conservatism. In 1953, he authored The Conservative Mind, which outlined and traced the development of socio-conservative thought in the works of Anglo-American tradition, such as those of Edmund Burke. The book helped establish the intellectual framework for a religious and humanistic understanding of conservatism in the postwar era. Kirk was the chief proponent of traditionalist conservatism.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Russell%20Kirk%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Russell_Kirk","kind":"about"}],"isidoreFolder":"Kirk, Russell","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Kirk_1962.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"marshall-mcluhan":{"extract":"Herbert Marshall McLuhan was a Canadian philosopher whose work is among the cornerstones of the study of media theory. Raised in Winnipeg, McLuhan studied at the University of Manitoba and the University of Cambridge. He began his teaching career as a professor of English at several universities in the United States and Canada before moving to the University of Toronto in 1946, where he remained for the rest of his life. He is known as \"the father of media studies\".","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Marshall%20McLuhan%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Marshall_McLuhan","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Marshall_McLuhan.jpg","license":"Public domain","artist":"Josephine Smith","pd":1}},"alasdair-macintyre":{"extract":"Alasdair Chalmers MacIntyre was a Scottish-American philosopher who contributed to moral and political philosophy as well as history of philosophy and theology. MacIntyre's After Virtue (1981) is one of the most important works of Anglophone moral and political philosophy in the 20th century. He was a senior research fellow at the Centre for Contemporary Aristotelian Studies in Ethics and Politics (CASEP) at London Metropolitan University, emeritus Professor of Philosophy at the University of Notre Dame, and permanent senior distinguished research fellow at the Notre Dame de Nicola Center for ","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Alasdair%20MacIntyre%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alasdair_MacIntyre","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Alasdair_MacIntyre.jpg","license":"CC BY 2.0","artist":"Sean O'Connor","licenseUrl":"https://creativecommons.org/licenses/by/2.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4c/Alasdair_MacIntyre.jpg/330px-Alasdair_MacIntyre.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"charles-taylor":{"extract":"Charles Margrave Taylor is a Canadian philosopher and professor emeritus at McGill University best known for his contributions to political philosophy, the philosophy of social science, the history of philosophy, and intellectual history. A devout Catholic philosopher, his work has earned him the Kyoto Prize, the Templeton Prize, the Berggruen Prize for Philosophy, and the John W. Kluge Prize.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Charles%20Taylor%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Charles_Taylor_(philosopher)","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Charles_Taylor_in_2019_%284x5_cropped%29.jpg","license":"CC BY-SA 4.0","artist":"Lëa-Kim Châteauneuf","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3c/Charles_Taylor_in_2019_%284x5_cropped%29.jpg/330px-Charles_Taylor_in_2019_%284x5_cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"rene-girard":{"extract":"René Noël Théophile Girard was a French academic best known for developing mimetic theory, which posits that human desire is fundamentally imitative, leading to rivalry, violence and the scapegoat mechanism as foundations of religion and culture. Holding academic appointments primarily in literature departments in the United States, his interdisciplinary work influenced fields ranging from theology to economics to psychology and cultural studies.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Ren%C3%A9%20Girard%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ren%C3%A9_Girard","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Ren%C3%A9_Girard.jpg","license":"Public domain","artist":"Vicq","pd":1}},"gabriel-marcel":{"extract":"Gabriel Honoré Marcel was a French philosopher, playwright, music critic and leading Christian existentialist. The author of over a dozen books and at least thirty plays, Marcel's work focused on the modern individual's struggle in a technologically dehumanizing society. Though often regarded as the first French existentialist, he dissociated himself from figures such as Jean-Paul Sartre, preferring the term philosophy of existence or neo-Socrateanism to define his own thought. The Mystery of Being is a well-known two-volume work authored by Marcel.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Gabriel%20Marcel%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gabriel_Marcel","kind":"about"}]},"elizabeth-anscombe":{"extract":"Gertrude Elizabeth Margaret Anscombe, usually cited as G. E. M. Anscombe or Elizabeth Anscombe, was a British analytic philosopher. She wrote on the philosophy of mind, philosophy of action, philosophical logic, philosophy of language, and ethics. She was a prominent figure of analytical Thomism, a fellow of Somerville College, Oxford, and a professor of philosophy at the University of Cambridge.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Elizabeth%20Anscombe%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/G._E._M._Anscombe","kind":"about"}]},"peter-geach":{"extract":"Peter Thomas Geach was a British philosopher who was Professor of Logic at the University of Leeds. His areas of interest were philosophical logic, ethics, history of philosophy, philosophy of religion and the theory of identity.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Peter%20Geach%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Peter_Geach","kind":"about"}]},"germain-grisez":{"extract":"Germain Gabriel Grisez was a French-American philosopher. Grisez's development of ideas from Thomas Aquinas has redirected Catholic thought and changed the way it has engaged with secular moral philosophy. In 'The First Principle of Practical Reason: A Commentary on the Summa Theologiae, I-II, Q. 94, A. 2' (1965), Grisez attacked the neo-scholastic interpretation of Aquinas as holding that moral norms are derived from methodologically antecedent knowledge of human nature. Grisez defended the idea of metaphysical free choice and proposed a natural law theory of practical reasoning and moral jud","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Germain%20Grisez%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Germain_Grisez","kind":"about"}],"isidoreFolder":"Grisez, Germain Gabriel"},"john-finnis":{"extract":"John Mitchell Finnis is an Australian legal philosopher and jurist specializing in jurisprudence and the philosophy of law. He is an original interpreter of Aristotle and Aquinas, and counts Germain Grisez as a major influence and collaborator. He has made contributions to epistemology, metaphysics, and moral philosophy.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22John%20Finnis%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Finnis","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:John_Finnis_on_After_Dark_26th_June_1987_%283x4_cropped%29.jpg","license":"GFDL","artist":"(c)1987 Open Media Ltd. Uploaded to Wikipedia by AnOpenMedium","licenseUrl":"http://www.gnu.org/copyleft/fdl.html"},"img":"https://upload.wikimedia.org/wikipedia/commons/9/99/John_Finnis_on_After_Dark_26th_June_1987_%283x4_cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled"},"robert-p-george":{"extract":"Robert Peter George is an American legal scholar, political philosopher, and public intellectual who is the sixth McCormick Professor of Jurisprudence and director of the James Madison Program in American Ideals and Institutions at Princeton University. He lectures on constitutional interpretation, civil liberties, philosophy of law, and political philosophy.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Robert%20P.%20George%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Robert_P._George","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Robert_P._George_by_Gage_Skidmore.jpg","license":"CC BY-SA 3.0","artist":"Gage Skidmore","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1d/Robert_P._George_by_Gage_Skidmore.jpg/330px-Robert_P._George_by_Gage_Skidmore.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"edward-feser":{"extract":"Edward Charles Feser is an American Catholic philosopher. He is a professor of Philosophy at Pasadena City College in Pasadena, California.","qidWork":null,"links":[{"label":"Edward Feser blog","url":"https://edwardfeser.blogspot.com/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Edward%20Feser%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Edward_Feser","kind":"about"}],"isidoreFolder":"Feser, Edward","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Ed_Feser_Portrait_%284x5_cropped%29.jpg","license":"CC0","artist":"Edward Feser","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","pd":1}},"peter-kreeft":{"extract":"Peter John Kreeft is an American professor of philosophy at Boston College and The King's College. A convert to Catholicism, he is the author of over eighty books on Christian philosophy, theology and apologetics. He also formulated, together with Ronald K. Tacelli, Twenty Arguments for the Existence of God in their Handbook of Christian Apologetics.","qidWork":null,"links":[{"label":"PeterKreeft.com","url":"https://www.peterkreeft.com/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Peter%20Kreeft%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Peter_Kreeft","kind":"about"}],"isidoreFolder":"Kreeft, Peter","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Peter_Kreeft_Portrait_ca_2006_%284x5_cropped%29.jpg","license":"CC BY-SA 3.0","artist":"uploaded by Marax","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/"},"img":"https://upload.wikimedia.org/wikipedia/commons/2/2b/Peter_Kreeft_Portrait_ca_2006_%284x5_cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled"},"ralph-mcinerny":{"extract":"Ralph Matthew McInerny was an American author and philosophy professor at the University of Notre Dame. McInerny's most popular mystery novels featured Father Dowling, and was later adapted into the Father Dowling Mysteries television show, which ran from 1987 to 1991.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Ralph%20McInerny%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ralph_McInerny","kind":"about"}],"isidoreFolder":"McInerny, Ralph M_"},"servais-pinckaers":{"extract":"Servais-Théodore Pinckaers OP was a Belgian Dominican priest and noted moral theologian. He has been especially influential in the renewal of a theological and Christological approach to Christian virtue ethics.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Servais%20Pinckaers%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Servais-Th%C3%A9odore_Pinckaers","kind":"about"}],"isidoreFolder":"Pinckaers, Servais, O.P_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Pinckaers_Servais_copie.jpg","license":"Public domain","artist":"University of Fribourg","pd":1}},"jean-pierre-torrell":{"extract":"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jean-Pierre%20Torrell%22","kind":"search"}],"isidoreFolder":"Torrell, Jean-Pierre, O.P_"},"thomas-joseph-white":{"extract":"Thomas Joseph White is an American Catholic priest and theologian who has served as rector of the Pontifical University of Saint Thomas Aquinas in Rome since 2021. He is also a founding member of the bluegrass band The Hillbilly Thomists and is a member of the Dominican Order.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Thomas%20Joseph%20White%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Thomas_Joseph_White","kind":"about"}],"isidoreFolder":"White, Thomas Joseph, O.P_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Fr._Thomas_Joseph_White%2C_O.P._%284x5_cropped%29.jpg","license":"CC BY-SA 4.0","artist":"Segrettore","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/52/Fr._Thomas_Joseph_White%2C_O.P._%284x5_cropped%29.jpg/330px-Fr._Thomas_Joseph_White%2C_O.P._%284x5_cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"matthew-levering":{"extract":"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Matthew%20Levering%22","kind":"search"}],"isidoreFolder":"Levering, Matthew"},"scott-hahn":{"extract":"Scott Walker Hahn is an American Catholic author, theologian and apologist.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Scott%20Hahn%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Scott_Hahn","kind":"about"}],"isidoreFolder":"Hahn, Scott","intro":"Scott Hahn, born in 1957, is a biblical theologian who has taught at Franciscan University of Steubenville since 1990 and founded the St. Paul Center for Biblical Theology. Ordained a Presbyterian minister in 1982, he entered the Catholic Church at the Easter Vigil of 1986, a journey he and his wife Kimberly tell in Rome Sweet Home. His popular books, including The Lamb's Supper and Hail, Holy Queen, explain the Mass and Mary through Scripture. All are in copyright, so we link to them.","books":[{"t":"Rome Sweet Home: Our Journey to Catholicism","pub":"Ignatius Press","isbn":"9780898704785","y":1993,"url":"https://ignatius.com/rome-sweet-home-rshp/","note":"with Kimberly Hahn"},{"t":"A Father Who Keeps His Promises: God's Covenant Love in Scripture","pub":"Charis (Servant Publications)","isbn":"9780892838295","y":1998,"url":"https://openlibrary.org/books/OL698412M"},{"t":"The Lamb's Supper: The Mass as Heaven on Earth","pub":"Doubleday","isbn":"9780385496599","y":1999,"url":"https://openlibrary.org/books/OL37087M"},{"t":"Hail, Holy Queen: The Mother of God in the Word of God","pub":"Doubleday","isbn":"9780385501682","y":2001,"url":"https://openlibrary.org/books/OL6788677M"},{"t":"Reasons to Believe: How to Understand, Explain, and Defend the Catholic Faith","pub":"Doubleday","isbn":"9780385509350","y":2007,"url":"https://openlibrary.org/books/OL7440923M"},{"t":"Kinship by Covenant: A Canonical Approach to the Fulfillment of God's Saving Promises","pub":"Yale University Press","isbn":"9780300140972","y":2009,"url":"https://openlibrary.org/books/OL24073218M"},{"t":"Ignatius Catholic Study Bible: New Testament (RSV-2CE)","pub":"Ignatius Press","isbn":"9781586174859","y":2010,"url":"https://openlibrary.org/books/OL26010787M","note":"with Curtis Mitch"},{"t":"The Fourth Cup: Unveiling the Mystery of the Last Supper and the Cross","pub":"Image","isbn":"9781524758790","y":2018,"url":"https://openlibrary.org/books/OL27360486M"}],"media":[{"label":"Scott Hahn (official site)","url":"https://www.scotthahn.com/","kind":"official"},{"label":"Free Online Resources (scotthahn.com)","url":"https://www.scotthahn.com/listen-online","kind":"audio/video"},{"label":"Sunday Bible Reflections","url":"https://www.scotthahn.com/audio-video/2016/1/20/sunday-bible-reflections","kind":"audio"},{"label":"St. Paul Center on YouTube","url":"https://www.youtube.com/@StPaulCenter","kind":"youtube"},{"label":"Scott Hahn on Instagram","url":"https://www.instagram.com/scottwhahn","kind":"social"},{"label":"St. Paul Center for Biblical Theology","url":"https://stpaulcenter.com/","kind":"organization"},{"label":"Franciscan University of Steubenville","url":"https://www.franciscan.edu/","kind":"organization"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Scott_Hahn.jpg","license":"CC BY-SA 4.0","artist":"Patrick Sweeney","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Scott_Hahn.jpg/330px-Scott_Hahn.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"brant-pitre":{"extract":"Brant James Pitre is an American New Testament scholar and Distinguished Research Professor of Scripture at the Augustine Institute. He has written on the historical Jesus, the Virgin Mary, Paul the Apostle, the origin of the Eucharist, and the canonical Gospels.","qidWork":null,"links":[{"label":"Catholic Productions","url":"https://catholicproductions.com/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Brant%20Pitre%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Brant_Pitre","kind":"about"}],"isidoreFolder":"Pitre, Brant"},"jimmy-akin":{"extract":"Jimmy Akin is an American Catholic apologist. He has been working for Catholic Answers since 1993 and is their longest-serving staff member.","qidWork":null,"links":[{"label":"JimmyAkin.com","url":"https://jimmyakin.com/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jimmy%20Akin%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jimmy_Akin","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Jimmyakinvsbartehrmandebate2022.jpg","license":"CC BY-SA 4.0","artist":"AndrewReder","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Jimmyakinvsbartehrmandebate2022.jpg/330px-Jimmyakinvsbartehrmandebate2022.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"karl-keating":{"extract":"Karl Keating is an American Catholic apologist and author who founded and presided over Catholic Answers, a lay apostolate of Catholic apologetics and evangelization.","qidWork":null,"links":[{"label":"Catholic Answers","url":"https://www.catholic.com/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Karl%20Keating%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Karl_Keating","kind":"about"}]},"trent-horn":{"extract":"Trent Horn is an American Catholic apologist, writer, and academic. He is best known for his work in apologetics and his role as a speaker and educator on various aspects of Catholic teaching, in addition to his engagement in numerous debates regarding religious, philosophical, and political matters.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Trent%20Horn%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Trent_Horn","kind":"about"}],"isidoreFolder":"Horn, Trent","intro":"Trent Horn is a staff apologist at Catholic Answers, which he joined in 2012, and the host of the weekly podcast The Counsel of Trent. He entered the Catholic Church at seventeen and went on to earn three master's degrees, in theology, philosophy, and bioethics. His books answer the objections of atheists and Protestants, work through difficult passages of Scripture, and make the pro-life case, with steady attention to charitable and persuasive conversation. All are in copyright, so we link to them.","books":[{"t":"Answering Atheism: How to Make the Case for God with Logic and Charity","pub":"Catholic Answers Press","isbn":"9781938983436","y":2013,"url":"https://shop.catholic.com/answering-atheism-how-to-make-the-case-for-god-with-logic-and-charity/"},{"t":"Persuasive Pro-Life: How to Talk About Our Culture's Toughest Issue","pub":"Catholic Answers Press","isbn":"9781941663042","y":2014,"url":"https://openlibrary.org/books/OL37069606M"},{"t":"Hard Sayings: A Catholic Approach to Answering Bible Difficulties","pub":"Catholic Answers Press","isbn":"9781941663745","y":2016,"url":"https://openlibrary.org/books/OL37739292M"},{"t":"Why We're Catholic: Our Reasons for Faith, Hope, and Love","pub":"Catholic Answers Press","isbn":"9781683570240","y":2017,"url":"https://shop.catholic.com/why-were-catholic-our-reasons-for-faith-hope-and-love/"},{"t":"The Case for Catholicism: Answers to Classic and Contemporary Protestant Objections","pub":"Ignatius Press","isbn":"9781621641445","y":2017,"url":"https://ignatius.com/the-case-for-catholicism-ccatp/"},{"t":"Made This Way: How to Prepare Kids to Face Today's Tough Moral Issues","pub":"Catholic Answers Press","isbn":"9781683570974","y":2018,"url":"https://shop.catholic.com/made-this-way-how-to-prepare-kids-to-face-todays-tough-moral-issues/","note":"with Leila Miller"},{"t":"Counterfeit Christs: Finding the Real Jesus Among the Impostors","pub":"Catholic Answers Press","isbn":"9781683571162","y":2019,"url":"https://shop.catholic.com/counterfeit-christs-finding-the-real-jesus-among-the-impostors/"},{"t":"What the Saints Never Said: Pious Misquotes and the Subtle Heresies They Teach","pub":"Catholic Answers Press","isbn":"9781683570691","url":"https://shop.catholic.com/what-the-saints-never-said-pious-misquotes-and-the-subtle-heresies-they-teach-you/"}],"media":[{"label":"Trent Horn (official site)","url":"https://www.trenthorn.com/","kind":"official"},{"label":"The Counsel of Trent (Catholic Answers)","url":"https://www.catholic.com/audio/cot","kind":"podcast"},{"label":"The Counsel of Trent on YouTube","url":"https://www.youtube.com/@TheCounselofTrent","kind":"youtube"},{"label":"The Counsel of Trent on Apple Podcasts","url":"https://podcasts.apple.com/us/podcast/the-counsel-of-trent/id1354647807","kind":"podcast"},{"label":"The Counsel of Trent on Spotify","url":"https://open.spotify.com/show/5PGmCKE1KzIHMN9kvKOpC8","kind":"podcast"},{"label":"Trent Horn on X","url":"https://x.com/Trent_Horn","kind":"social"},{"label":"Catholic Answers: Trent Horn profile","url":"https://www.catholic.com/profile/trent-horn","kind":"organization"},{"label":"Trent Horn: Books (official)","url":"https://www.trenthorn.com/books/","kind":"organization"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Trent_Horn_in_2024.png","license":"CC BY 3.0","artist":"ReasonTV","licenseUrl":"https://creativecommons.org/licenses/by/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/be/Trent_Horn_in_2024.png/330px-Trent_Horn_in_2024.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"robert-barron":{"extract":"Robert Emmet Patrick Barron is an American Catholic theologian who has served as bishop of the Diocese of Winona–Rochester since 2022. He served as rector at Mundelein Seminary from 2012 to 2015 and as auxiliary bishop for the Archdiocese of Los Angeles from 2015 to 2022. He has published on theology and spirituality, and is the founder of Word on Fire.","qidWork":null,"links":[{"label":"Word on Fire","url":"https://www.wordonfire.org/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Robert%20Barron%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Robert_Barron","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Bishop_Robert_Barron.jpg","license":"CC0","artist":"ARC Forum","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","pd":1}},"peter-kwasniewski":{"extract":"Peter Andrew Kwasniewski is an American traditionalist Catholic theologian and composer.","qidWork":null,"links":[{"label":"PeterKwasniewski.com","url":"https://www.peterkwasniewski.com/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Peter%20Kwasniewski%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Peter_Kwasniewski","kind":"about"}],"isidoreFolder":"Kwasniewski, Peter A_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Dr._Kwasniewski.jpg","license":"CC BY-SA 4.0","artist":"Julian Kwasniewski","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/81/Dr._Kwasniewski.jpg/330px-Dr._Kwasniewski.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"george-weigel":{"extract":"George Weigel is an American Catholic author, political analyst, and social activist. He currently serves as a distinguished senior fellow of the Ethics and Public Policy Center. Weigel was the founding president of the James Madison Foundation. He is the author of a best-selling biography of Pope John Paul II, Witness to Hope, and Tranquillitas Ordinis: The Present Failure and Future Promise of American Catholic Thought on War and Peace.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22George%20Weigel%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/George_Weigel","kind":"about"}],"isidoreFolder":"Weigel, George","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:George_weigel_8948.JPG","license":"GFDL 1.2","artist":"slowking","licenseUrl":"http://www.gnu.org/licenses/old-licenses/fdl-1.2.html"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/28/George_weigel_8948.JPG/330px-George_weigel_8948.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"michael-d-o-brien":{"extract":"Michael David O'Brien is a Canadian author, artist, and essayist and lecturer on faith and culture.","qidWork":null,"links":[{"label":"StudioBrien","url":"https://www.studiobrien.com/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Michael%20D.%20O%27Brien%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Michael_O'Brien_(Canadian_author)","kind":"about"}]},"joseph-pearce":{"extract":"Joseph Pearce is a British-born American writer who serves as director of the Center for Faith and Culture at Aquinas College in Nashville, Tennessee. He previously held positions at Ave Maria College in Ypsilanti, Michigan, and Ave Maria University in Ave Maria, Florida. He is a co-editor of the St. Austin Review.","qidWork":null,"links":[{"label":"JosephPearce.com","url":"https://www.jpearce.co/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Joseph%20Pearce%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Joseph_Pearce","kind":"about"}],"isidoreFolder":"Pearce, Joseph","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Joseph_Pearce_speaking_into_a_microphone.jpg","license":"Public domain","artist":"PeterMottola","pd":1}},"dana-gioia":{"extract":"Michael Dana Gioia is an American poet, literary critic, literary translator, and essayist.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Dana%20Gioia%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Dana_Gioia","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Dana_Gioia.jpg","license":"Public domain","artist":"Dana Gioia by Star Black","pd":1}},"marilynne-robinson":{"extract":"Marilynne Summers Robinson is an American novelist and essayist. Across her writing career, Robinson has received numerous awards, including the Pulitzer Prize for Fiction in 2005, National Humanities Medal in 2012, and the 2016 Library of Congress Prize for American Fiction. In 2016, Robinson was named in Time magazine's list of 100 most influential people. Robinson began teaching at the Iowa Writers' Workshop in 1991 and retired in the spring of 2016.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Marilynne%20Robinson%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Marilynne_Robinson","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Marilynne_Robinson_%28cropped2%29.jpg","license":"CC0","artist":"Christian Scott Heinen Bell","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","pd":1}},"alice-von-hildebrand":{"extract":"Alice Marie von Hildebrand, was a Belgian-born American Catholic philosopher, theologian, author, and professor. She taught philosophy at Hunter College for 37 years. She was also the second wife of Dietrich von Hildebrand.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Alice%20von%20Hildebrand%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alice_von_Hildebrand","kind":"about"}],"isidoreFolder":"von Hildebrand, Alice"},"benedict-groeschel":{"extract":"Benedict Joseph Groeschel, C.F.R. was an American Franciscan friar, Catholic priest, retreat master, author, psychologist, activist, and television host. He hosted the television talk program Sunday Night Prime on the Eternal Word Television Network, as well as several serial religious specials.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Benedict%20Groeschel%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Benedict_Groeschel","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Benedict_Groeschel_2009.jpg","license":"CC BY 2.0","artist":"Ambrose Little","licenseUrl":"https://creativecommons.org/licenses/by/2.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2f/Benedict_Groeschel_2009.jpg/330px-Benedict_Groeschel_2009.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"john-hardon":{"extract":"John Anthony Hardon was an American Jesuit priest, writer, teacher and theologian. As a beatification process was opened for him in 2005, he is recognized by the Catholic Church as a Servant of God.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22John%20Hardon%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Hardon","kind":"about"}],"isidoreFolder":"Hardon, John A., S.J_"},"jacques-barzun":{"extract":"Jacques Martin Barzun was a French-born American historian known for his studies of the history of ideas and cultural history. He wrote about a wide range of subjects, including baseball, mystery novels, and classical music, and was also known as a philosopher of education. In the book Teacher in America (1945), Barzun influenced the training of schoolteachers in the United States.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jacques%20Barzun%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jacques_Barzun","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Jacques_barzun.jpg","license":"Public domain","artist":"Eric Robert Morse","pd":1}},"warren-h-carroll":{"extract":"Warren Hasty Carroll was an American historian who was the founder and first president of Christendom College in Front Royal, Virginia. He authored multiple works of Roman Catholic church history.","qidWork":null,"links":[{"label":"Christendom College Press (publisher of A History of Christendom)","url":"https://press.christendom.edu/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Warren%20H.%20Carroll%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Warren_H._Carroll","kind":"about"}],"isidoreFolder":"Carroll, Warren Hasty","intro":"Warren H. Carroll (1932–2011) was an American historian who earned his doctorate at Columbia and was received into the Catholic Church in 1968. In 1977 he founded Christendom College in Virginia, serving as its first president and later chairing its history department until 2002. His multi-volume History of Christendom tells the story of the West from an openly Catholic perspective, and he also wrote on Isabel of Spain and Our Lady of Guadalupe. His books are in copyright, so we link to them.","books":[{"t":"1917: Red Banners, White Mantle","pub":"Christendom Publications","isbn":"9780931888052","y":1981,"url":"https://press.christendom.edu/product/1917/"},{"t":"Our Lady of Guadalupe and the Conquest of Darkness","pub":"Christendom Publications","isbn":"9780931888120","y":1983,"url":"https://press.christendom.edu/product/our-lady-of-guadalupe-2/","note":"ISBN is the 2004 Christendom Press reprint"},{"t":"The Founding of Christendom (A History of Christendom, vol. 1)","pub":"Christendom Press","isbn":"9780931888212","y":1985,"url":"https://press.christendom.edu/product/the-founding-of-christendom/","note":"ISBN is the 2004 Christendom Press reprint"},{"t":"The Building of Christendom (vol. 2)","pub":"Christendom Press","isbn":"9780931888243","y":1987,"url":"https://press.christendom.edu/product/the-building-of-christendom-324-1100/","note":"ISBN is the 2004 Christendom Press reprint"},{"t":"Isabel of Spain: The Catholic Queen","pub":"Christendom Press","isbn":"9780931888434","y":1991,"url":"https://press.christendom.edu/product/isabel-of-spain/","note":"ISBN is the 2004 Christendom Press reprint"},{"t":"The Glory of Christendom (vol. 3)","pub":"Christendom Press","isbn":"9780931888557","y":1993,"url":"https://press.christendom.edu/product/the-glory-of-christendom-1100-1517/"},{"t":"The Last Crusade","pub":"Christendom Press","isbn":"9780931888670","y":1996,"url":"https://press.christendom.edu/product/the-last-crusade-2/"},{"t":"The Cleaving of Christendom (vol. 4)","pub":"Christendom Press","isbn":"9780931888755","y":2000,"url":"https://press.christendom.edu/product/the-cleaving-of-christendom-1517-1661/","note":"ISBN is the 2004 Christendom Press reprint"},{"t":"The Revolution Against Christendom (vol. 5)","pub":"Christendom Press","isbn":"9780931888809","y":2005,"url":"https://press.christendom.edu/product/the-revolution-against-christendom-1661-1815/"},{"t":"The Crisis of Christendom (vol. 6)","pub":"Christendom Press","isbn":"9780931888847","y":2013,"url":"https://press.christendom.edu/product/the-crisis-of-christendom-1815-2005/"}],"media":[{"label":"Christendom College: Our Founder","url":"https://www.christendom.edu/about/warren-h-carroll/","kind":"organization"},{"label":"Christendom College Press: The History of Christendom","url":"https://press.christendom.edu/product/history-of-christendom-collection/","kind":"organization"},{"label":"National Catholic Register obituary (2011)","url":"https://www.ncregister.com/news/warren-carroll-1932-2011-83xz3xbw","kind":"organization"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Warren_H._Carroll_-_Black_and_white_photo_portrait.jpg","license":"Public domain","artist":"Christendom College","pd":1}},"eamon-duffy":{"extract":"Eamon Duffy is an Irish historian. He is the emeritus professor of the History of Christianity at the University of Cambridge, and a fellow and former president of Magdalene College.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Eamon%20Duffy%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Eamon_Duffy","kind":"about"}],"isidoreFolder":"Duffy, Eamon","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Eamon_Duffy_%284548480973%29_%28cropped%29.jpg","license":"CC BY 2.0","artist":"Fr James Bradley from Southampton, UK","licenseUrl":"https://creativecommons.org/licenses/by/2.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Eamon_Duffy_%284548480973%29_%28cropped%29.jpg/330px-Eamon_Duffy_%284548480973%29_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"rodney-stark":{"extract":"Rodney William Stark was an American sociologist of religion who was a longtime professor of sociology and of comparative religion at the University of Washington. At the time of his death he was the Distinguished Professor of the Social Sciences at Baylor University, co-director of the university's Institute for Studies of Religion, and founding editor of the Interdisciplinary Journal of Research on Religion.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Rodney%20Stark%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Rodney_Stark","kind":"about"}]},"thomas-e-woods":{"extract":"Thomas Ernest Woods Jr. is an American author, podcast host, and libertarian commentator who is currently a senior fellow at the Mises Institute. A proponent of the Austrian School of economics, Woods hosts a podcast, The Tom Woods Show, and formerly co-hosted the weekly podcast Contra Krugman.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Thomas%20E.%20Woods%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Tom_Woods","kind":"about"}],"isidoreFolder":"Woods, Thomas E., Jr_","intro":"Thomas E. Woods Jr. is an American historian who studied at Harvard and earned his doctorate at Columbia. He appears here for his books on Catholic history: How the Catholic Church Built Western Civilization, The Church Confronts Modernity, a study of Catholic intellectuals in the Progressive Era, and Sacred Then and Sacred Now, on the traditional Latin Mass. He also writes on economics and politics; in The Church and the Market he argues for a free economy. Those views are his own, not Church teaching.","books":[{"t":"The Church Confronts Modernity: Catholic Intellectuals and the Progressive Era","pub":"Columbia University Press","isbn":"9780231131865","y":2004,"url":"https://openlibrary.org/books/OL3691914M"},{"t":"How the Catholic Church Built Western Civilization","pub":"Regnery Publishing","isbn":"9780895260383","y":2005,"url":"https://openlibrary.org/books/OL8250523M"},{"t":"The Church and the Market: A Catholic Defense of the Free Economy","pub":"Lexington Books","isbn":"9780739110362","y":2005},{"t":"Sacred Then and Sacred Now: The Return of the Old Latin Mass","pub":"Roman Catholic Books","isbn":"9780979354021","url":"https://openlibrary.org/books/OL11840237M"}],"media":[{"label":"Thomas E. Woods Jr. (official site)","url":"https://tomwoods.com/","kind":"official"},{"label":"The Tom Woods Show","url":"https://tomwoods.com/podcasts/","kind":"podcast"},{"label":"The Tom Woods Show on Apple Podcasts","url":"https://podcasts.apple.com/us/podcast/the-tom-woods-show/id716825890","kind":"podcast"},{"label":"The Tom Woods Show on Spotify","url":"https://open.spotify.com/show/4RziZyRebkVYcRuGJlkJHN","kind":"podcast"},{"label":"Thomas E. Woods Jr. on X","url":"https://x.com/thomasewoods","kind":"social"},{"label":"Thomas E. Woods Jr. on YouTube","url":"https://www.youtube.com/@TomWoodsTV","kind":"social"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Thomas_Woods_%283x4_cropped%29.jpg","license":"CC BY-SA 2.0","artist":"Gage Skidmore from Surprise, AZ, United States of America","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8b/Thomas_Woods_%283x4_cropped%29.jpg/330px-Thomas_Woods_%283x4_cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"mother-teresa-of-calcutta":{"extract":"Anjezë Gonxhe Bojaxhiu, better known as Mother Teresa or Saint Mother Teresa of Calcutta, was an Albanian-Indian Catholic nun, founder of the Missionaries of Charity and a Catholic saint.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Mother%20Teresa%20of%20Calcutta%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mother_Teresa","kind":"about"}],"isidoreFolder":"Mother Teresa","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Mother_Teresa_1.jpg","license":"CC BY-SA 2.0","artist":"Kingkongphoto & www.celebrity-photos.com from Laurel Maryland, USA","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d6/Mother_Teresa_1.jpg/330px-Mother_Teresa_1.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"john-paul-ii":{"extract":"Pope John Paul II was the head of the Catholic Church and sovereign of Vatican City from 16 October 1978 until his death in 2005. He was the first non-Italian pope since Adrian VI in the 16th century, as well as the third longest-serving pope in history, after St. Peter and Pius IX. In addition to this, he was an important philosopher and theologian of the 20th century.","qidWork":null,"links":[{"label":"Documents on vatican.va","url":"https://www.vatican.va/content/john-paul-ii/en.html","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22John%20Paul%20II%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pope_John_Paul_II","kind":"about"}],"isidoreFolder":"Wojtyla, Karol","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:ADAMELLO_-_PAPA_-_Giovanni_Paolo_II_-_panoramio_%28cropped%29.jpg","license":"CC BY-SA 3.0","artist":"Gregorini Demetrio","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9c/ADAMELLO_-_PAPA_-_Giovanni_Paolo_II_-_panoramio_%28cropped%29.jpg/330px-ADAMELLO_-_PAPA_-_Giovanni_Paolo_II_-_panoramio_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"joseph-ratzinger":{"extract":"Pope Benedict XVI was the head of the Catholic Church and sovereign of the Vatican City from 2005 until his resignation in 2013. Following his resignation, he chose to be known as \"pope emeritus\", a title he held until his death on 31 December 2022. In addition to this, he was an important philosopher and theologian of the 20th and early 21st centuries.","qidWork":null,"links":[{"label":"Documents on vatican.va","url":"https://www.vatican.va/content/benedict-xvi/en.html","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Joseph%20Ratzinger%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pope_Benedict_XVI","kind":"about"}],"isidoreFolder":"Ratzinger, Joseph","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Benedykt_XVI_%282010-10-17%29_2.jpg","license":"GFDL 1.2","artist":"Kancelaria Prezydenta RP","licenseUrl":"https://gnu.org/licenses/old-licenses/fdl-1.2.html"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/98/Benedykt_XVI_%282010-10-17%29_2.jpg/330px-Benedykt_XVI_%282010-10-17%29_2.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"pope-francis":{"extract":"Pope Francis was the head of the Catholic Church and sovereign of Vatican City from 13 March 2013 until his death in 2025. He was the first Jesuit pope, the first Latin American, and the first pope born or raised outside Europe since the 8th-century Syrian pope Gregory III.","qidWork":null,"links":[{"label":"Documents on vatican.va","url":"https://www.vatican.va/content/francesco/en.html","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Pope%20Francis%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pope_Francis","kind":"about"}]},"pope-leo-xiv":{"extract":"Pope Leo XIV is the head of the Catholic Church and sovereign of Vatican City.","qidWork":null,"links":[{"label":"Documents on vatican.va","url":"https://www.vatican.va/content/leo-xiv/en.html","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Pope%20Leo%20XIV%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pope_Leo_XIV","kind":"about"}],"isidoreFolder":"Prevost, Robert F., O.S.A_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Pope_Leo_XIV_3_%283x4_cropped%29.png","license":"CC BY-SA 4.0","artist":"Edgar Beltrán , The Pillar","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/Pope_Leo_XIV_3_%283x4_cropped%29.png/330px-Pope_Leo_XIV_3_%283x4_cropped%29.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"pope-leo-xiii":{"extract":"Pope Leo XIII was head of the Catholic Church from 1878 until his death in 1903. He had the fourth-longest reign and third-longest verified reign of any pope, behind those of St. Peter, Pius IX, and John Paul II.","qidWork":null,"links":[{"label":"Documents on vatican.va","url":"https://www.vatican.va/content/leo-xiii/en.html","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Pope%20Leo%20XIII%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pope_Leo_XIII","kind":"about"}],"isidoreFolder":"Leo XIII, Pope","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Papa_Leone_XIII_%283x4_cropped%29.jpeg","license":"Public domain","artist":"Braun et Compagnie","pd":1}},"pope-pius-ix":{"extract":"Pope Pius IX was head of the Catholic Church from 16 June 1846 until his death in February 1878.","qidWork":null,"links":[{"label":"Documents on vatican.va","url":"https://www.vatican.va/content/pius-ix/en.html","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Pope%20Pius%20IX%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pope_Pius_IX","kind":"about"}],"isidoreFolder":"Pius IX, Pope","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Pius_IX%2C_by_Adolphe_Braun%2C_1875.jpg","license":"Public domain","pd":1}},"pope-pius-x":{"extract":"Pope Pius X was head of the Catholic Church from 4 August 1903 until his death in August 1914. He opposed modernist interpretations of Catholic doctrine, and promoted liturgical reforms and Thomist scholastic theology. He initiated the preparation of the 1917 Code of Canon Law, the first comprehensive and systemic work of its kind, which was ultimately promulgated by his successor. He is venerated as a saint in the Catholic Church.","qidWork":null,"links":[{"label":"Documents on vatican.va","url":"https://www.vatican.va/content/pius-x/en.html","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Pope%20Pius%20X%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pope_Pius_X","kind":"about"}],"isidoreFolder":"Pius X, Pope St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Pius_X%2C_by_Ernest_Walter_Histed_%28retouched%29.jpg","license":"Public domain","pd":1}},"pope-pius-xi":{"extract":"Pope Pius XI was head of the Catholic Church from 6 February 1922 until his death in February 1939. He was also the first sovereign of Vatican City upon its creation on 11 February 1929.","qidWork":null,"links":[{"label":"Documents on vatican.va","url":"https://www.vatican.va/content/pius-xi/en.html","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Pope%20Pius%20XI%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pope_Pius_XI","kind":"about"}],"isidoreFolder":"Pius XI, Pope","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Pius_XI%2C_by_Nicola_Perscheid%2C_circa_1922_%28retouched%29.jpg","license":"Public domain","artist":"Nicola Perscheid","pd":1}},"pope-pius-xii":{"extract":"Pope Pius XII was head of the Catholic Church and sovereign of the Vatican City from 2 March 1939 until his death in 1958. His pontificate spanned a highly consequential 19 years that included the Second World War, the Holocaust, and the first years of the Cold War.","qidWork":null,"links":[{"label":"Documents on vatican.va","url":"https://www.vatican.va/content/pius-xii/en.html","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Pope%20Pius%20XII%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pope_Pius_XII","kind":"about"}],"isidoreFolder":"Pius XII, Pope","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Pius_XII_with_tabard%2C_by_Michael_Pitcairn%2C_1951_%28retouched%29.jpg","license":"Public domain","artist":"Michael Pitcairn","pd":1}},"pope-john-xxiii":{"extract":"Pope John XXIII was head of the Catholic Church and sovereign of Vatican City from 28 October 1958 until his death on 3 June 1963.","qidWork":null,"links":[{"label":"Documents on vatican.va","url":"https://www.vatican.va/content/john-xxiii/en.html","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Pope%20John%20XXIII%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pope_John_XXIII","kind":"about"}],"isidoreFolder":"John XXIII","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Ioannes_XXIII%2C_by_De_Agostini%2C_1958%E2%80%931963.jpg","license":"Public domain","artist":"De Agostini Editore","pd":1}},"pope-paul-vi":{"extract":"Pope Paul VI was head of the Catholic Church and sovereign of Vatican City from 21 June 1963 until his death on 6 August 1978. Succeeding John XXIII, he continued the Second Vatican Council, which he closed in 1965, implementing its numerous reforms. He fostered improved ecumenical relations with Eastern Orthodox and Protestant churches, which resulted in many historic meetings and agreements.","qidWork":null,"links":[{"label":"Documents on vatican.va","url":"https://www.vatican.va/content/paul-vi/en.html","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Pope%20Paul%20VI%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pope_Paul_VI","kind":"about"}],"isidoreFolder":"Paul VI","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Pope_Paul_VI_1969_Portrait_%284x5_cropped%29.jpg","license":"Public domain","artist":"Fotografia Felici","pd":1}},"gregory-xvi":{"extract":"Pope Gregory XVI was head of the Catholic Church and leader of the Papal States from 2 February 1831 to his death in June 1846. He had adopted the name Mauro upon entering the religious order of the Camaldolese. He is the most recent pope to take the pontifical name \"Gregory\", the last to govern the Papal States for the whole duration of his pontificate, and the most recent not to have been a bishop when elected.","qidWork":null,"links":[{"label":"Documents on vatican.va","url":"https://www.vatican.va/content/gregorius-xvi/en.html","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Gregory%20XVI%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pope_Gregory_XVI","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Gregory_XVI.jpg","license":"Public domain","artist":"Paul Delaroche","pd":1}},"francis-arinze":{"extract":"Francis Arinze is a Nigerian prelate of the Catholic Church, who served as the Prefect of the Secretariat for Non-Christians from 1984 to 2002 and Prefect of the Congregation for Divine Worship and the Discipline of the Sacraments from 2002 to 2008. He previously served as the Archbishop of Onitsha from 1967 to 1985 and as the president of the Catholic Bishops' Conference of Nigeria from 1979 to 1984. Arinze is the current Cardinal Bishop of Velletri–Segni since 2005 and was one of the principal advisors to Pope John Paul II and was considered papabile at the 2005 Papal conclave. According to ","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Francis%20Arinze%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Francis_Arinze","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Card._Francis_Arinze.jpg","license":"CC BY-SA 3.0","artist":"At commons.cathopedia.org, User Name: Padre Mimmo Spatuzzi","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/50/Card._Francis_Arinze.jpg/330px-Card._Francis_Arinze.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"robert-sarah":{"extract":"Robert Sarah is a Guinean Catholic prelate who served as prefect of the Congregation for Divine Worship and the Discipline of the Sacraments from 23 November 2014 to 20 February 2021. He previously served as secretary of the Congregation for the Evangelization of Peoples under Pope John Paul II and president of the Pontifical Council Cor Unum under Pope Benedict XVI. He was made a cardinal in 2010.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Robert%20Sarah%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Robert_Sarah","kind":"about"}],"isidoreFolder":"Sarah, Robert Cardinal","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Cardinal_Robert_Sarah_%28cropped%29.JPG","license":"CC BY-SA 4.0","artist":"François-Régis Salefran","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/27/Cardinal_Robert_Sarah_%28cropped%29.JPG/330px-Cardinal_Robert_Sarah_%28cropped%29.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"christoph-schonborn":{"extract":"Christoph Maria Michael Hugo Damian Peter Adalbert Schönborn, OP is a Bohemian-born Austrian Catholic prelate who served as Archbishop of Vienna from 1995 until 2025. He was chairman of the Austrian Bishops' Conference from 1998 to 2020 and was made a cardinal in 1998. He is a member of the Dominican Order.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Christoph%20Sch%C3%B6nborn%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Christoph_Sch%C3%B6nborn","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Sch%C3%B6nborn_%C3%96sterreichische_Bischofskonferenz_20200616.jpg","license":"CC BY-SA 4.0","artist":"Mureccles","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/da/Sch%C3%B6nborn_%C3%96sterreichische_Bischofskonferenz_20200616.jpg/330px-Sch%C3%B6nborn_%C3%96sterreichische_Bischofskonferenz_20200616.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"avery-dulles":{"extract":"Avery Robert Dulles was an American Jesuit priest, theologian, and cardinal of the Catholic Church. Dulles served on the faculty of Woodstock College from 1960 to 1974, of the Catholic University of America from 1974 to 1988, and as the Laurence J. McGinley Professor of Religion and Society at Fordham University from 1988 to 2008. He was also an author and lecturer.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Avery%20Dulles%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Avery_Dulles","kind":"about"}],"isidoreFolder":"Dulles, Cardinal Avery"},"john-o-connor":{"extract":"John Joseph O'Connor was an American Catholic prelate who served as Archbishop of New York from 1984 until his death in 2000, and was made a cardinal in 1985.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22John%20O%27Connor%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_O'Connor_(cardinal)","kind":"about"}]},"francis-xavier-nguyen-van-thuan":{"extract":"Francis-Xavier Nguyễn Văn Thuận was a Vietnamese Catholic prelate who served as President of the Pontifical Council for Justice and Peace from 1998 to 2002. Prior to that, he served as Coadjutor Archbishop of the Archdiocese of Sài Gòn from 1975 to 1994 and as Bishop of Nha Trang from 1967 to 1975.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Francis%20Xavier%20Nguy%E1%BB%85n%20V%C4%83n%20Thu%E1%BA%ADn%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Nguy%E1%BB%85n_V%C4%83n_Thu%E1%BA%ADn","kind":"about"}]},"jozsef-mindszenty":{"extract":"József Mindszenty was a Hungarian cardinal of the Catholic Church who served as Archbishop of Esztergom and leader of the Catholic Church in Hungary from 1945 to 1973. According to the Encyclopedia Britannica, for five decades \"he personified uncompromising opposition to fascism and communism in Hungary\".","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22J%C3%B3zsef%20Mindszenty%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/J%C3%B3zsef_Mindszenty","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:J%C3%B3zsef_Mindszenty.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"john-a-o-brien":{"extract":"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22John%20A.%20O%27Brien%22","kind":"search"}]},"leo-j-trese":{"extract":"Leo John Trese was an American Catholic priest, and author of spiritual books.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Leo%20J.%20Trese%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Leo_J._Trese","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Leo-J-Trese-ca-1955.jpg","license":"CC BY-SA 4.0","artist":"Clementeste","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Leo-J-Trese-ca-1955.jpg/330px-Leo-J-Trese-ca-1955.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"francis-fernandez-carvajal":{"extract":"\nFrancisco Fernández Carvajal or Francis Fernandez was a Spanish Catholic priest in the Opus Dei Prelature and the author of several books.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Francis%20Fernandez-Carvajal%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Francisco_Fern%C3%A1ndez_Carvajal","kind":"about"}]},"gabriel-of-st-mary-magdalen":{"extract":"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Gabriel%20of%20St.%20Mary%20Magdalen%22","kind":"search"}]},"mary-ann-glendon":{"extract":"Mary Ann Glendon is the Learned Hand Professor of Law Emerita at Harvard Law School and a former United States Ambassador to the Holy See. She teaches and writes on bioethics, comparative constitutional law, property, and human rights in international law.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Mary%20Ann%20Glendon%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mary_Ann_Glendon","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Mary_Ann_Glendon_ambassador.jpg","license":"Public domain","artist":"United States Department of State","pd":1}},"robert-spaemann":{"extract":"Robert Spaemann was a German Catholic philosopher. He is considered a member of the Ritter School.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Robert%20Spaemann%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Robert_Spaemann","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Robert_Spaemann_2015_%283x4_cropped%29.jpg","license":"CC BY-SA 4.0","artist":"Demo für Alle","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/94/Robert_Spaemann_2015_%283x4_cropped%29.jpg/330px-Robert_Spaemann_2015_%283x4_cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"remi-brague":{"extract":"Rémi Brague is a French historian of philosophy specializing in Islamic, Jewish, and Christian thought of the Middle Ages. He is professor emeritus of Arabic and religious philosophy at the Sorbonne and Romano Guardini chair of philosophy (emeritus) at LMU Munich.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22R%C3%A9mi%20Brague%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/R%C3%A9mi_Brague","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Paris_-_R%C3%A9mi_Brague_-_1.jpg","license":"CC BY-SA 4.0","artist":"This illustration was made by Peter Potrowl . Please credit this with : © Peter Potrowl in the immediate vicinity of the image. A link to my website sitemai.eu would be much appreciated but isn't…","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/Paris_-_R%C3%A9mi_Brague_-_1.jpg/330px-Paris_-_R%C3%A9mi_Brague_-_1.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"pierre-teilhard-de-chardin":{"extract":"Pierre Teilhard de Chardin, S.J. was a French Jesuit priest, scientist, paleontologist, philosopher, mystic and teacher. He investigated the theory of evolution from a perspective influenced by Henri Bergson and Christian mysticism, writing scientific and religious works on the subject. His mainstream scientific achievements include his paleontological research in China, taking part in the discovery of the significant Peking Man fossils from the Zhoukoudian cave complex, near Beijing.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/chardin","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Pierre%20Teilhard%20de%20Chardin%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pierre_Teilhard_de_Chardin","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:TeilhardP_1955a.jpg","license":"CC BY-SA 3.0","artist":"Phillippe Halsman","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e3/TeilhardP_1955a.jpg/330px-TeilhardP_1955a.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"georges-lemaitre":{"extract":"Georges Henri Joseph Édouard Lemaître was a Belgian Catholic priest, theoretical physicist, and mathematician who made major contributions to cosmology and astrophysics. He was the first to argue that the recession of galaxies is evidence of an expanding universe and to connect the observational Hubble–Lemaître law with the solution to the Einstein field equations in the general theory of relativity for a homogenous and isotropic universe. That work led Lemaître to propose what he called the \"hypothesis of the primeval atom\", now regarded as the first formulation of the Big Bang theory of the ","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Georges%20Lema%C3%AEtre%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Georges_Lema%C3%AEtre","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:GLemaitre30.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"stanley-jaki":{"extract":"Stanley L. Jaki was a Hungarian-born priest of the Benedictine order. From 1975 to his death, he was Distinguished University Professor at Seton Hall University, in South Orange, New Jersey.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Stanley%20Jaki%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Stanley_Jaki","kind":"about"}],"isidoreFolder":"Jaki, Stanley L., O.S.B_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Father_Jaki_June_2007.jpg","license":"CC BY-SA 3.0","artist":"Antonio G Colombo","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6e/Father_Jaki_June_2007.jpg/330px-Father_Jaki_June_2007.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"gregor-mendel":{"extract":"Gregor Johann Mendel was an Austrian biologist, meteorologist, mathematician, Augustinian friar and abbot of St. Thomas' Abbey in Brno (Brünn), Margraviate of Moravia. Mendel was born in a German-speaking family in the Silesian part of the Austrian Empire and gained posthumous recognition as the founder of the modern science of genetics. Though farmers had known for millennia that crossbreeding of animals and plants could favor certain desirable traits, Mendel's pea plant experiments conducted between 1856 and 1863 established many of the rules of heredity, now referred to as the laws of Mende","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/40855","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Gregor%20Mendel%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gregor_Mendel","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Gregor_Mendel_2.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"hugh-ross-williamson":{"extract":"Hugh Ross Williamson (1901–1978) was a prolific British popular historian, and a dramatist. Starting from a career in the literary world, and having a Nonconformist background, he became an Anglican priest in 1943.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Hugh%20Ross%20Williamson%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hugh_Ross_Williamson","kind":"about"}]},"alfred-noyes":{"extract":"Alfred Noyes CBE was an English poet, short-story writer and playwright.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/2093","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Alfred%20Noyes%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alfred_Noyes","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Portrait_of_Alfred_Noyes.jpg","license":"Public domain","artist":"Alexander Bassano","pd":1}},"siegfried-sassoon":{"extract":"Siegfried Loraine Sassoon was an English war poet, writer, and soldier. Decorated for bravery on the Western Front, he became one of the leading poets of the First World War. His poetry both described the horrors of the trenches and satirized the patriotic pretensions of those who, in Sassoon's view, were responsible for a jingoism-fuelled war. Sassoon became a focal point for dissent within the armed forces when he made a lone protest against the continuation of the war with his \"Soldier's Declaration\" of July 1917, which resulted in his being sent to the Craiglockhart War Hospital. During th","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/2934","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Siegfried%20Sassoon%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Siegfried_Sassoon","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Siegfried_Sassoon_by_George_Charles_Beresford_%281915%29.jpg","license":"Public domain","artist":"George Charles Beresford","pd":1}},"david-jones":{"extract":"David Michael Jones CH was a British painter and modernist poet. As a painter he worked mainly in watercolour on portraits and animal, landscape, legendary and religious subjects. He was also a wood-engraver and inscription painter. In 1965, Kenneth Clark took him to be the best living British painter, while both T. S. Eliot and W. H. Auden put his poetry among the best written in their century. Jones's work gains form from his Christian faith and Welsh heritage.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22David%20Jones%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/David_Jones_(painter)","kind":"about"}]},"edith-sitwell":{"extract":"Dame Edith Louisa Sitwell was a British poet and critic and the eldest of the three literary Sitwells. She reacted badly to her eccentric, unloving parents and lived much of her life with her governess. She never married but became passionately attached to Russian painter Pavel Tchelitchew, and her home was always open to London's poetic circle, to whom she was generous and helpful.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/52004","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Edith%20Sitwell%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Edith_Sitwell","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Edith_Sitwell_by_Elliott_%26_Fry_%281929%29.png","license":"Public domain","artist":"Elliott & Fry","pd":1}},"oscar-wilde":{"extract":"Oscar Fingal O'Fflahertie Wills Wilde was an Irish author, poet and playwright. After writing in different literary styles throughout the 1880s, he became one of the most popular and influential dramatists in London in the early 1890s. He was a key figure in the emerging Aestheticism movement of the late 19th century and is widely regarded as the greatest playwright of the Victorian era. Wilde is best known for his Gothic novel The Picture of Dorian Gray (1890), his epigrams, plays and bedtime stories for children, as well as his criminal conviction in 1895 for gross indecency and for practici","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/111","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Oscar%20Wilde%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Oscar_Wilde","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Oscar_Wilde_by_Napoleon_Sarony._Three-quarter-length_photograph%2C_seated_%28cropped%29.jpg","license":"Public domain","artist":"Napoleon Sarony / Adam Cuerden","pd":1}},"ernest-dowson":{"extract":"Ernest Christopher Dowson was an English poet, novelist, and short-story writer. Despite his short lifespan, he made a lasting impression on the literature of the English fin-de-siècle through his Decadent poetry.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/2775","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Ernest%20Dowson%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ernest_Dowson","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Ernest_Dowson.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"joyce-kilmer":{"extract":"Alfred Joyce Kilmer was an American writer and poet mainly remembered for a short poem titled \"Trees\" (1913), which was published in the collection Trees and Other Poems in 1914. Though a prolific poet whose works celebrated the common beauty of the natural world as well as his Catholic faith, Kilmer was also a journalist, literary critic, lecturer, and editor. At the time of his deployment to Europe during World War I, Kilmer was considered the leading American Catholic poet and lecturer of his generation, whom critics often compared to British contemporaries G. K. Chesterton (1874–1936) and ","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/149","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Joyce%20Kilmer%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Joyce_Kilmer","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Kilmer_1908_columbia_yearbook_picture.png","license":"Public domain","artist":"Columbia University (1908)","pd":1}},"joseph-fessio":{"extract":"Joseph Fessio is an American Jesuit priest, as well as the founder and editor of Ignatius Press. After studying with Joseph Ratzinger, he founded the St. Ignatius Institute at the University of San Francisco, one of the first Catholic Great Books programs in the United States, then served as the founding provost of Ave Maria University. He hosts the weekly podcast Father Fessio in Five.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Joseph%20Fessio%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Joseph_Fessio","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Fessio2015.jpeg","license":"CC BY-SA 4.0","artist":"TraLeSollecitudini","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c1/Fessio2015.jpeg/330px-Fessio2015.jpeg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"mike-aquilina":{"extract":"Mike Aquilina is an American Catholic author and journalist working in the area of Church history, especially patristics. He is co-founder of the St. Paul Center for Biblical Theology, a Catholic research center based in Steubenville, Ohio.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Mike%20Aquilina%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mike_Aquilina","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Mike_Aquilina%2C_author.tif","license":"CC BY-SA 4.0","artist":"James Merrick","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/da/Mike_Aquilina%2C_author.tif/lossless-page1-330px-Mike_Aquilina%2C_author.tif.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"fr-mike-schmitz":{"extract":"Michael Thomas Schmitz is an American Catholic priest, speaker, author, and podcaster. He serves as director of youth and young adult ministry in the Diocese of Duluth and Newman Center chaplain at the University of Minnesota Duluth. Schmitz is most notable for his social media presence, including YouTube videos and The Bible in a Year podcast produced by Ascension Press.","qidWork":null,"links":[{"label":"The Bible in a Year","url":"https://bibleinayear.fireside.fm/","kind":"site"},{"label":"The Catechism in a Year","url":"https://catechisminayear.fireside.fm/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Mike%20Schmitz%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mike_Schmitz","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Mike_Schmitz.png","license":"CC BY 3.0","artist":"Steubenville Conferences","licenseUrl":"https://creativecommons.org/licenses/by/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Mike_Schmitz.png/330px-Mike_Schmitz.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"jason-evert":{"extract":"Jason Evert is a Catholic author and chastity speaker. He founded Totus Tuus Press and Chastity Project, an organization that promotes chastity primarily to high school and college students.","qidWork":null,"links":[{"label":"Chastity Project","url":"https://chastity.com/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jason%20Evert%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jason_Evert","kind":"about"}]},"christopher-west":{"extract":"Christopher West is a Catholic author and speaker on gender and sexuality, best known for his work on Pope John Paul II’s series of audience addresses entitled Theology of the Body.","qidWork":null,"links":[{"label":"Theology of the Body Institute","url":"https://tobinstitute.org/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Christopher%20West%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Christopher_West","kind":"about"}]},"taylor-marshall":{"extract":"Taylor Reed Marshall is an American traditionalist Catholic writer, podcaster, and YouTube commentator.","qidWork":null,"links":[{"label":"YouTube — Dr. Taylor Marshall","url":"https://www.youtube.com/@DrTaylorMarshall","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Taylor%20Marshall%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Taylor_Marshall","kind":"about"}],"isidoreFolder":"Marshall, Taylor R_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Taylor_Marshall.png","license":"CC BY 3.0","artist":"Elliott Hulse | WISDOM","licenseUrl":"https://creativecommons.org/licenses/by/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1f/Taylor_Marshall.png/330px-Taylor_Marshall.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"matt-fradd":{"extract":"Matthew Fradd is an Australian-American author, podcaster, and Catholic motivational speaker. He hosts his podcast, Pints with Aquinas, founded in March 2016, which became part of The Daily Wire in January 2026.","qidWork":null,"links":[{"label":"Pints with Aquinas","url":"https://www.dailywire.com/show/pints-with-aquinas","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Matt%20Fradd%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Matt_Fradd","kind":"about"}],"isidoreFolder":"Fradd, Matt","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Matt_Fradd.png","license":"CC BY 3.0","artist":"Steubenville Conferences","licenseUrl":"https://creativecommons.org/licenses/by/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e0/Matt_Fradd.png/330px-Matt_Fradd.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"patrick-madrid":{"extract":"Patrick Madrid is an American Catholic, author, and radio host. His many books include Why Be Catholic?, Life Lessons: 50 Things I Learned in My First 50 Years, and How to Do Apologetics. His books have sold over one million copies, including foreign-language editions.","qidWork":null,"links":[{"label":"PatrickMadrid.com","url":"https://patrickmadrid.com/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Patrick%20Madrid%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Patrick_Madrid","kind":"about"}],"isidoreFolder":"Madrid, Patrick","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Patrick_Madrid_Taco_Tuesday.jpg","license":"CC BY-SA 4.0","artist":"BryRadio1","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Patrick_Madrid_Taco_Tuesday.jpg/330px-Patrick_Madrid_Taco_Tuesday.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"tim-staples":{"extract":"Tim Staples is a Catholic author, apologist, and lecturer. Until July 2026, he was the Director of Apologetics and Evangelization at Catholic Answers.","qidWork":null,"links":[{"label":"Catholic Answers","url":"https://www.catholic.com/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Tim%20Staples%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Tim_Staples","kind":"about"}]},"jennifer-fulwiler":{"extract":"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jennifer%20Fulwiler%22","kind":"search"}]},"ross-douthat":{"extract":"Ross Gregory Douthat is an American columnist and author who is a correspondent for the CBS News program 60 Minutes.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Ross%20Douthat%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ross_Douthat","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Ross_Douthat_on_Conversations_with_Tyler.png","license":"CC BY 3.0","artist":"Mercatus Center","licenseUrl":"https://creativecommons.org/licenses/by/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/Ross_Douthat_on_Conversations_with_Tyler.png/330px-Ross_Douthat_on_Conversations_with_Tyler.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"sohrab-ahmari":{"extract":"Sohrab Ahmari is an Iranian-born American columnist, editor, and author of nonfiction books. He is a founding editor of the online magazine Compact. He is a contributing editor of The Catholic Herald, and a columnist for First Things. Previously, he served as the op-ed editor of the New York Post, an editor with The Wall Street Journal opinion pages in New York and London, and as a senior writer at Commentary. Ahmari advocates an isolationist foreign policy and was an advisor to the United States Vice President JD Vance during President Trump's second term. In June 2026, Ahmari flew with JD Va","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Sohrab%20Ahmari%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Sohrab_Ahmari","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Sohrab_Ahmari_in_2026.jpg","license":"CC BY 4.0","artist":"Elekes Andor","licenseUrl":"https://creativecommons.org/licenses/by/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ed/Sohrab_Ahmari_in_2026.jpg/330px-Sohrab_Ahmari_in_2026.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"erik-varden":{"extract":"Erik Varden is a Norwegian Catholic prelate, writer, and Trappist monk who has served as Bishop of Trondheim since 2020.","qidWork":null,"links":[{"label":"Coram Fratribus (blog)","url":"https://coramfratribus.com/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Erik%20Varden%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Erik_Varden","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:ErikVarden24.jpg","license":"CC BY-SA 4.0","artist":"Archivo Fotográfico Universidad de Navarra","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/ErikVarden24.jpg/330px-ErikVarden24.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"aristides-of-athens":{"extract":"Aristides the Athenian was a Greek Christian author who is primarily known for authoring the Apology of Aristides in the 2nd century Revered as a saint, his feast day is August 31 in the Catholic Church and September 13 in the Eastern Orthodox Church.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/01712d.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/aristides","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Aristides%20of%20Athens%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Aristides_of_Athens","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Saint-Aristides-mural-painting-in-a-Greek-Orthodox-church.png","license":"CC BY-SA 4.0","artist":"Peloponnisios","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/Saint-Aristides-mural-painting-in-a-Greek-Orthodox-church.png/330px-Saint-Aristides-mural-painting-in-a-Greek-Orthodox-church.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"epistle-of-barnabas":{"extract":"The Epistle of Barnabas is an early Christian Greek epistle written between 70 and 135 AD. The complete text is preserved in the 4th-century Codex Sinaiticus, where it is positioned at the end of the New Testament, following the Book of Revelation and preceding the Shepherd of Hermas.","qidWork":"Q262557","links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/02300a.htm","kind":"about"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Epistle%20of%20Barnabas%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Epistle_of_Barnabas","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Codex_Tchacos_p33.jpg","license":"Public domain","artist":"WolfgangRieger","pd":1}},"didache":{"extract":"The Didache, also known as The Lord's Teaching Through the Twelve Apostles to the Nations, is a brief, anonymous early Christian treatise written in Koine Greek, dated by modern scholars to the first or second century AD.","qidWork":"Q210752","links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Didache%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Didache","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Didache.png","license":"Public domain","artist":"didachist","pd":1}},"bardaisan":{"extract":"Bardaisan, known in Arabic as ibn Dayṣān and in Latin as Bardesanes, was a Syriac-speaking Christian writer and teacher with a Gnostic background, and founder of the Bardaisanites.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/02293a.htm","kind":"about"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Bardaisan%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Bardaisan","kind":"about"}]},"gaius-of-rome":{"extract":"\nCaius, Presbyter of Rome was a Christian author who lived and wrote towards the beginning of the 3rd century. Only fragments of his works are known, which are given in the collection entitled The Ante-Nicene Fathers. However, the Muratorian fragment, an early attempt to establish the canon of the New Testament, is often attributed to Caius and is included in that collection.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/03144a.htm","kind":"about"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Gaius%20of%20Rome%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Caius_(presbyter)","kind":"about"}]},"commodian":{"extract":"Commodian (Commodianus) was a Christian Latin poet, who flourished about AD 250.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/04165a.htm","kind":"about"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Commodian%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Commodian","kind":"about"}]},"pope-dionysius":{"extract":"Pope Dionysius was the Bishop of Rome from 22 July 259 to 26 December 268. His pontificate oversaw the transition from Valerian's persecutions to the toleration issued by Gallienus in 260. During this period, he reorganized the Roman church, assigning presbyters to individual parishes.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/05009b.htm","kind":"about"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Pope%20Dionysius%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pope_Dionysius","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Pope_Dionysius.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"gennadius-of-massilia":{"extract":"Gennadius of Massilia, also known as Gennadius Scholasticus or Gennadius Massiliensis, was a 5th-century Christian priest, monk, and historian.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/06417a.htm","kind":"about"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Gennadius%20of%20Massilia%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gennadius_of_Massilia","kind":"about"}]},"sextus-julius-africanus":{"extract":"Sextus Julius Africanus was a Christian traveler and historian of the late 2nd and early 3rd centuries. He influenced fellow historian Eusebius, later writers of Church history among the Church Fathers, and the Greek school of chroniclers.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/08565a.htm","kind":"about"},{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/55795","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Sextus%20Julius%20Africanus%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Sextus_Julius_Africanus","kind":"about"}]},"movses-khorenatsi":{"extract":"Movses Khorenatsi was a prominent Armenian historian from late antiquity and the author of the History of the Armenians.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/10598a.htm","kind":"about"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Movses%20Khorenatsi%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Movses_Khorenatsi","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:St.Movses_Khorenatsi.jpg","license":"CC BY-SA 2.0","artist":"Ashnag","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8e/St.Movses_Khorenatsi.jpg/330px-St.Movses_Khorenatsi.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"pamphilus-of-caesarea":{"extract":"Pamphilus, was a priest of Caesarea and chief among the biblical scholars of his generation. He was the friend and teacher of Eusebius of Caesarea, who recorded details of his career in a three-book Vita that has been lost.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/11436b.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/pamphilus","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Pamphilus%20of%20Caesarea%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pamphilus_of_Caesarea","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Pamphilus_of_Caesarea.jpg","license":"Public domain","artist":"Authors of Menologion of Basil II (circa 985 AC, Constantinople), Byzantine manuscript illuminators : Pantoleon with Georgios, Michael the Younger, Michael of Blachernae, Symeon, Symeon of…","pd":1}},"peter-of-alexandria":{"extract":"Pope Peter I of Alexandria was the 17th Pope and Patriarch of Alexandria from 300 to 311. He is revered as a saint by the Coptic Orthodox Church, the Eastern Orthodox Church, and the Catholic Church.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/11771a.htm","kind":"about"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Peter%20of%20Alexandria%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Peter_I_of_Alexandria","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Peter_of_Alexandria.jpg","license":"Public domain","artist":"Georgios Foukas","pd":1}},"victorinus-of-pettau":{"extract":"Saint Victorinus of Pettau was an Early Christian ecclesiastical writer who flourished about 270, and who was martyred during the persecutions of Emperor Diocletian. A Bishop of Poetovio in Pannonia, Victorinus is also known as Victorinus Petavionensis or Poetovionensis. Victorinus composed commentaries on various texts within the Christians' Holy Scriptures.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/15414a.htm","kind":"about"},{"label":"Works at CCEL","url":"https://ccel.org/ccel/victorinus","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Victorinus%20of%20Pettau%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Victorinus_of_Pettau","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Victorinus_%28cropped%29.jpg","license":"CC BY-SA 3.0","artist":"Jakob Brollo","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/Victorinus_%28cropped%29.jpg/330px-Victorinus_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"alexander-of-alexandria":{"extract":"Alexander I of Alexandria was the 19th Patriarch of Alexandria.","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/01296a.htm","kind":"about"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Alexander%20of%20Alexandria%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pope_Alexander_I_of_Alexandria","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Veljusa_Monastery_St._Alexander_of_Alexandria.jpg","license":"FAL","artist":"Author unknown","licenseUrl":"http://artlibre.org/licence/lal/en"},"img":"https://upload.wikimedia.org/wikipedia/commons/e/ec/Veljusa_Monastery_St._Alexander_of_Alexandria.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled"},"alexander-of-lycopolis":{"extract":"Alexander of Lycopolis was an ancient Greek philosopher, who lived in Egypt during the late 3rd century CE, belonged to the Neoplatonic school and is remembered as a determined opponent of Manichaeism. This then still very young religion had been founded in the Persian Sasanian Empire by Mani, a contemporary of Alexander, had spread westward into the Roman Empire, and had been brought to Egypt by missionaries. Alexander’s polemic against Manichaeism provides valuable information about its early history and shows that he was well informed about the doctrine he opposed. His aim was to defend the","qidWork":null,"links":[{"label":"Works at New Advent (Fathers)","url":"https://www.newadvent.org/fathers/","kind":"read"},{"label":"Catholic Encyclopedia article","url":"https://www.newadvent.org/cathen/01299a.htm","kind":"about"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Alexander%20of%20Lycopolis%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alexander_of_Lycopolis","kind":"about"}]},"sophronius-of-jerusalem":{"extract":"Sophronius, called Sophronius the Sophist, was the Greek Patriarch of the city known as Aelia Capitolina and then Jerusalem from 634 until his death. He is venerated as a saint in the Eastern Orthodox and Catholic Churches. Before rising to the primacy of the See, he was a monk and theologian who was the chief protagonist for orthodox teaching in the doctrinal controversy on the essential nature of Jesus and his volitional acts. He is also renowned for the negotiation of the surrender of Aelia Capitolina to the Rashid caliph Umar in 637/8.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Sophronius%20of%20Jerusalem%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Sophronius_of_Jerusalem","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Athonite_Fresco_Icon_of_Saint_Sophronios_of_Jerusalem.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"andrew-of-crete":{"extract":"Andrew of Crete, also known as Andrew of Jerusalem, was an 8th-century bishop, theologian, homilist, and hymnographer. He is venerated as a saint in both the Eastern Orthodox Church and the Catholic Church.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Andrew%20of%20Crete%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Andrew_of_Crete","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Agios_Andreas_Kretes_Dionysiou.jpg","license":"Public domain","artist":"Tzortzis Phouka","pd":1}},"germanus-i-of-constantinople":{"extract":"Germanus I of Constantinople was the Ecumenical Patriarch of Constantinople from 715 to 730. He is regarded as a saint by both the Orthodox and Catholic Churches, with a feast day of 12 May. He had been ecumenically preceded by Patriarch John VI of Constantinople, and was succeeded in Orthodox Rite by Patriarch Anastasius of Constantinople.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Germanus%20I%20of%20Constantinople%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Germanus_I_of_Constantinople","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Agios_Germanos_Konstantinoupoleos_Vissarionos.jpg","license":"Public domain","artist":"Tzortzis Phouka","pd":1}},"theodore-the-studite":{"extract":"Theodore the Studite, also known as Theodorus Studita and Saint Theodore of Stoudios/Studium, was a Byzantine Greek monk and abbot of the Stoudios Monastery in Constantinople. He played a major role in the revivals both of Byzantine monasticism and of classical literary genres in Byzantium. He is known as a zealous opponent of iconoclasm, one of several conflicts that set him at odds with both emperor and patriarch. Throughout his life he maintained letter correspondences with many important political and cultural figures of the Byzantine empire; this included many women, such as the composer ","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Theodore%20the%20Studite%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Theodore_the_Studite","kind":"about"}],"isidoreFolder":"Theodore the Studite","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Studite.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"romanos-the-melodist":{"extract":"Romanos the Melodist was a Byzantine hymnographer and composer, who is a central early figure in the history of Byzantine music. Called \"the Pindar of rhythmic poetry\", he flourished during the sixth century, though the earliest manuscripts of his works are dated centuries after this. He was the foremost Kontakion composer of his time.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Romanos%20the%20Melodist%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Romanos_the_Melodist","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:1649._%D0%9F%D0%B0%D0%BA%D1%80%D0%BE%D1%9E.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"venantius-fortunatus":{"extract":"Venantius Honorius Clementianus Fortunatus, known as Saint Venantius Fortunatus, was a Latin poet and hymnographer in the Merovingian Court, and a Christian bishop who has been venerated since the Middle Ages.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Venantius%20Fortunatus%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Venantius_Fortunatus","kind":"about"}],"imgCredit":{"page":"https://en.wikipedia.org/wiki/File:Poitiers%2C_M%C3%A9diath%C3%A8que_Fran%C3%A7ois_Mitterrand%2C_MS_250_%28136%29%2C_fol._21v.jpg","license":"PD","pd":1}},"fulgentius-of-ruspe":{"extract":"Fabius Claudius Gordianus Fulgentius, also known as Fulgentius of Ruspe, was a African Christian prelate who served as Bishop of Ruspe in what is now Tunisia, during the 5th and 6th century. He is venerated as a saint.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Fulgentius%20of%20Ruspe%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Fulgentius_of_Ruspe","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Fulgentius_von_Ruspe_17Jh.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"caesarius-of-arles":{"extract":"Caesarius of Arles, sometimes called \"of Chalon\" from his birthplace Chalon-sur-Saône, was the foremost ecclesiastic of his generation in Merovingian Gaul. Caesarius is considered to be of the last generation of church leaders of Gaul who worked to integrate large-scale ascetic elements into the Western Christian tradition. William E. Klingshirn's study of Caesarius depicts Caesarius as having the reputation of a \"popular preacher of great fervour and enduring influence\". Among those who exercised the greatest influence on Caesarius were Augustine of Hippo, Julianus Pomerius, and John Cassian.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Caesarius%20of%20Arles%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Caesarius_of_Arles","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Arles%2CSt_C%C3%A9saire27%2Cchoeur7%2CSt_C%C3%A9saire_%28cropped%29.jpg","license":"CC BY-SA 4.0","artist":"Neoclassicism Enthusiast","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Arles%2CSt_C%C3%A9saire27%2Cchoeur7%2CSt_C%C3%A9saire_%28cropped%29.jpg/330px-Arles%2CSt_C%C3%A9saire27%2Cchoeur7%2CSt_C%C3%A9saire_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"leander-of-seville":{"extract":"Leander of Seville was a Hispano-Roman Catholic prelate who served as Bishop of Seville. He was instrumental in effecting the conversion of the Visigothic kings Hermenegild and Reccared to Catholicism. His brother was the encyclopedist Isidore of Seville.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Leander%20of%20Seville%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Leander_of_Seville","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:San_Leandro.jpg","license":"Public domain","artist":"Bartolomé Esteban Murillo","pd":1}},"ildephonsus-of-toledo":{"extract":"Ildefonsus or Ildephonsus was a scholar and theologian who served as the Metropolitan Archbishop of Toledo for the last decade of his life. His Gothic name was Hildefuns. In the Ethiopian Orthodox Tewahedo Church he is known as Dexius based on the Ge'ez translation of legends about his life.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Ildephonsus%20of%20Toledo%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ildefonsus","kind":"about"}],"isidoreFolder":"Ildephonsus of Toledo, St_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Ildefonso_de_Toledo_%28cropped%29.jpg","license":"Public domain","artist":"El Greco","pd":1}},"adomnan":{"extract":"Adomnán or Adamnán of Iona, also known as Eunan, was an abbot of Iona Abbey (r. 679–704), hagiographer, statesman, canon jurist, and saint. He was the author of the Life of Columba, probably written between 697 and 700. This biography is by far the most important surviving work written in early-medieval Scotland, and is a vital source for our knowledge of the Picts, and an insight into the life of Iona and the early-medieval Gaelic monk.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Adomn%C3%A1n%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Adomn%C3%A1n","kind":"about"}]},"boniface":{"extract":"Boniface was an English Benedictine monk and leading figure in the Anglo-Saxon mission to the Germanic parts of Francia during the eighth century. He organised significant foundations of the church in Germany and was made Archbishop of Mainz by Pope Gregory III. He was martyred in Frisia in 754, along with 52 others, and his remains were returned to Fulda, where they rest in a sarcophagus which remains a site of Christian pilgrimage.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Boniface%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Saint_Boniface","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Saint_Boniface_by_Cornelis_Bloemaert.jpg","license":"Public domain","artist":"Cornelis Bloemaert","pd":1}},"paul-the-deacon":{"extract":"Paul the Deacon, also known as Paulus Diaconus, Warnefridus, Barnefridus, or Winfridus, and sometimes suffixed Cassinensis, was a Benedictine monk, scribe, and historian of the Lombards of Latin language.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Paul%20the%20Deacon%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Paul_the_Deacon","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:PaulusDiaconus_Plut.65.35.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"hincmar-of-reims":{"extract":"Hincmar, archbishop of Reims, was a Frankish jurist and theologian, as well as the friend, advisor and propagandist of Charles the Bald. He belonged to a noble family of northern Francia.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Hincmar%20of%20Reims%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hincmar","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Reims_%2851%29_Saint-R%C3%A9mi_Baie_208-2.jpg","license":"CC0","artist":"GO69","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","pd":1}},"odo-of-cluny":{"extract":"Odo of Cluny was the second abbot of Cluny.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Odo%20of%20Cluny%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Odo_of_Cluny","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Odo_Cluny-11.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"fulbert-of-chartres":{"extract":"Fulbert of Chartres was the Bishop of Chartres from 1006 to 1028 and a teacher at the Cathedral school there. Fulbert may have been a pupil of Gerbert of Aurillac, who would later become Pope Sylvester II. He was responsible for the advancement of the Nativity of the Virgin's feast day on September 8 and for one of the many reconstructions of the Chartres Cathedral. Most of the information available about him comes from letters he wrote to secular and religious figures between 1004 and 1028.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Fulbert%20of%20Chartres%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Fulbert_of_Chartres","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Chartres_%2828%29_Cath%C3%A9drale_Notre-Dame_-_Tour_du_ch%C5%93ur_-_%C3%89v%C3%AAque_de_Chartres_07.jpg","license":"CC BY-SA 4.0","artist":"GO69","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a6/Chartres_%2828%29_Cath%C3%A9drale_Notre-Dame_-_Tour_du_ch%C5%93ur_-_%C3%89v%C3%AAque_de_Chartres_07.jpg/330px-Chartres_%2828%29_Cath%C3%A9drale_Notre-Dame_-_Tour_du_ch%C5%93ur_-_%C3%89v%C3%AAque_de_Chartres_07.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"lanfranc":{"extract":"Lanfranc was an Italian-born English churchman, monk and scholar. Born in Italy, he moved to Normandy to become a Benedictine monk at Bec. He served successively as prior of Bec Abbey and abbot of St Stephen's Abbey in Caen, Normandy and then as Archbishop of Canterbury in England, following its conquest by William the Conqueror. He is also variously known as Lanfranc of Pavia, Lanfranc of Bec, and Lanfranc of Canterbury. In his lifetime, he was regarded as the greatest theologian of his generation.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Lanfranc%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Lanfranc","kind":"about"}],"isidoreFolder":"Canterbury, Lanfranc of","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Lanfrancstatuecanterburycathedraloutside.jpg","license":"CC BY-SA 3.0","artist":"Ealdgyth","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c8/Lanfrancstatuecanterburycathedraloutside.jpg/330px-Lanfrancstatuecanterburycathedraloutside.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"guigo-ii-the-carthusian":{"extract":"Guigo II, sometimes referred to as Guy, or by the moniker \"the Angelic\", was a Carthusian monk and the 9th prior of Grande Chartreuse monastery, from 1174 to 1180.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Guigo%20II%20the%20Carthusian%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Guigo_II","kind":"about"}]},"rupert-of-deutz":{"extract":"Rupert of Deutz was an influential Benedictine theologian, exegete and writer on liturgical and musical topics.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Rupert%20of%20Deutz%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Rupert_of_Deutz","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Rupert_von_Deutz_-_Federzeichnung_Codec_lat._11355.png","license":"Public domain","artist":"Stephanus","pd":1}},"alan-of-lille":{"extract":"Alain de Lille was a French theologian and poet. He was born in Lille some time before 1128. His exact date of death remains unclear as well, with most research pointing toward it being between 14 April 1202 and 5 April 1203. He is known for writing a number of works based upon the teachings of the liberal arts, with one of his most renowned poems, De planctu Naturae, focusing on sexual conduct among humans. Although Alain was widely known during his lifetime, little is known about his personal life.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Alan%20of%20Lille%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alain_de_Lille","kind":"about"}]},"joachim-of-fiore":{"extract":"Joachim of Fiore, also known as Joachim of Flora, was an Italian Christian theologian, Catholic abbot, and the founder of the monastic order of San Giovanni in Fiore. According to theologian Bernard McGinn, \"Joachim of Fiore is the most important apocalyptic thinker of the whole medieval period.\" The Divine Comedy of Dante Alighieri is one of the most famous works possibly inspired by his ideas. Later followers, inspired by his works in Christian eschatology and historicist theories, are called Joachimites.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/joachim","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Joachim%20of%20Fiore%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Joachim_of_Fiore","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Gregorio_Vasquez_de_Arce_y_Ceballos_-_Joachim_of_Fiore_shows_the_portraits_of_Saint_Dominic_de_Guzm%C3%A1n_and_Saint_Francis_of_Assisi_-_1680_%28detail%29.jpg","license":"Public domain","artist":"Gregorio Vasquez de Arce y Ceballos","pd":1}},"alexander-of-hales":{"extract":"Alexander of Hales —known also as Doctor Irrefragibilis, or \"Irrefutable Teacher\", and as Theologorum Monarcha —was a Franciscan friar, theologian, and philosopher instrumental to the development of scholasticism.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Alexander%20of%20Hales%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alexander_of_Hales","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Alexanderofhales.png","license":"CC BY-SA 4.0","artist":"George Glover","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Alexanderofhales.png/330px-Alexanderofhales.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"raymond-of-penyafort":{"extract":"Raymond of Peñafort was a Dominican friar who was a canon lawyer. He compiled the Decretals of Gregory IX, a collection of canonical laws that remained a major part of Church law until the 1917 Code of Canon Law abrogated it. He was canonized by Pope Clement VIII in 1601 and is the patron saint of canon lawyers.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Raymond%20of%20Penyafort%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Raymond_of_Pe%C3%B1afort","kind":"about"}],"isidoreFolder":"Penafort, St. Raymond, O.P_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:St._Raymond_of_Penyafort_%28cropped%29.jpg","license":"Public domain","artist":"Tommaso Dolabella","pd":1}},"giles-of-rome":{"extract":"Giles of Rome was an Italian medieval philosopher and Scholastic theologian and a friar of the Order of St Augustine, who was also appointed to the positions of prior general of his order and as Archbishop of Bourges. He is famed as being a logician, who produced a commentary on the Organon by Aristotle, and as the author of two important works: De ecclesiastica potestate, a major text of early-14th-century papalism, and De regimine principum, a guide book for Christian temporal leadership. Giles was styled Doctor Fundatissimus by Pope Benedict XIV.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Giles%20of%20Rome%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Giles_of_Rome","kind":"about"}],"isidoreFolder":"Giles of Rome, O.S.A_","imgCredit":{"page":"https://en.wikipedia.org/wiki/File:Giles_of_Rome.png","license":"PD","pd":1}},"henry-of-ghent":{"extract":"Henry of Ghent, also known as Henricus de Gandavo and Henricus Gandavensis, was a scholastic philosopher who acquired the nickname of Doctor Solemnis.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Henry%20of%20Ghent%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Henry_of_Ghent","kind":"about"}]},"godfrey-of-fontaines":{"extract":"Godfrey of Fontaines, was a scholastic philosopher and theologian who was designated by the title Doctor Venerandus. He made contributions to a diverse range of subjects ranging from moral philosophy to epistemology. However, he is best known today for his work on metaphysics.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Godfrey%20of%20Fontaines%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Godfrey_of_Fontaines","kind":"about"}]},"thomas-of-celano":{"extract":"Thomas of Celano was an Italian friar of the Franciscans as well as a poet and the author of three hagiographies about Francis of Assisi.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Thomas%20of%20Celano%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Thomas_of_Celano","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Tommaso_da_Celano_OFM.jpeg","license":"Public domain","artist":"Author unknown","pd":1}},"jacopone-da-todi":{"extract":"Jacopone da Todi was an Italian Franciscan friar from Umbria. He wrote several laude in the local vernacular. He was an early pioneer in Italian theatre, being one of the earliest scholars who dramatised Gospel subjects.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/34285","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jacopone%20da%20Todi%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jacopone_da_Todi","kind":"about"}]},"margery-kempe":{"extract":"Margery Kempe was an English Catholic mystic, known for writing through dictation The Book of Margery Kempe, a work considered by some to be the first autobiography in the English language. Her book chronicles her domestic tribulations, her adoption of celibacy, her extensive pilgrimages to holy sites in Europe and the Holy Land, her worship performances, as well as her mystical conversations with God and Christ. She is honoured in the Anglican Communion, but has not been canonised as a Catholic saint.","qidWork":null,"links":[{"label":"Works at CCEL","url":"https://ccel.org/ccel/kempe","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Margery%20Kempe%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Margery_Kempe","kind":"about"}]},"john-capistrano":{"extract":"John of Capistrano, OFM was an Italian Franciscan friar and Catholic priest from the town of Capestrano, Abruzzo. Famous as a preacher, theologian, and inquisitor, he earned himself the nickname \"the Soldier Saint\" when in 1456 at age 70 he led a Crusade against the invading Ottoman Empire at the siege of Belgrade with the Hungarian military commander John Hunyadi.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22John%20Capistrano%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_of_Capistrano","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:82Johannes_von_Capestrano.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"gabriel-biel":{"extract":"Gabriel Biel was a German scholastic philosopher and member of the Canons Regular of the Congregation of Windesheim, who were the clerical counterpart to the Brethren of the Common Life. Because of his reliance on the scholastic tradition, as well as nominalist views, he is credited an \"articulate spokesman of the via moderna and … a discerning user of the thought of via antiqua\". He has been called ultimus scholasticorum, the last of the schoolmen.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Gabriel%20Biel%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gabriel_Biel","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Gabriel_Biel.jpg","license":"CC0","artist":"Kagbub123","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","pd":1}},"johannes-capreolus":{"extract":"John Capreolus, in French Jean Capréolus and in Latin Johannes Capreolus, was a French Dominican theologian and Thomist.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Johannes%20Capreolus%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Capreolus","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Caprioli_-_In_libros_sententiarum_amplissimae_quaestiones%2C_1589_-_4446120.tif","license":"Public domain","artist":"Jean Caprioli","pd":1}},"francis-of-paola":{"extract":"Francis of Paola, O.M., was a Catholic friar from the town of Paola in Calabria who founded the Order of Minims. He was named after Francis of Assisi and like him—but unlike most founders of men's religious orders—Francis of Paola was never ordained a priest.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Francis%20of%20Paola%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Francis_of_Paola","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Francis_of_Paola_by_Giovanni_Domenico_Tiepolo.jpg","license":"CC BY-SA 3.0","artist":"Giovanni Domenico Tiepolo","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/Francis_of_Paola_by_Giovanni_Domenico_Tiepolo.jpg/330px-Francis_of_Paola_by_Giovanni_Domenico_Tiepolo.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"robert-persons":{"extract":"Robert Persons, later known as Robert Parsons, was an English Jesuit priest. He was a major figure in establishing the 16th-century \"English Mission\" of the Society of Jesus.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Robert%20Persons%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Robert_Persons","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Portrait_of_P._Robertus_Personius_%284671756%29.jpg","license":"Public domain","artist":"Jacob Neefs","pd":1}},"thomas-stapleton":{"extract":"Thomas Stapleton was an English Catholic priest and controversialist.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Thomas%20Stapleton%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Thomas_Stapleton_(theologian)","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Thomas_Stapleton.jpg","license":"Public domain","artist":"Léonard Gaultier","pd":1}},"william-allen":{"extract":"William Allen, also known as Guilielmus Alanus or Gulielmus Alanus, was an English Cardinal of the Roman Catholic Church. He was an ordained priest, but was never a bishop. His main role was setting up colleges to train English missionary priests with the mission of returning secretly to England to keep Roman Catholicism alive there. Allen assisted in the planning of the Spanish Armada's attempted invasion of England in 1588. It failed badly, but if it had succeeded he would probably have been made Archbishop of Canterbury and Lord Chancellor. The Douai-Rheims Bible, a complete translation int","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22William%20Allen%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/William_Allen_(cardinal)","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Cardinal_William_Allen.png","license":"Public domain","artist":"Author unknown","pd":1}},"johann-eck":{"extract":"Johann Eck, also known as Johann Maier von Eck and often anglicized as John Eck, was a German Roman Catholic theologian, scholastic, prelate, and opponent of Martin Luther.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Johann%20Eck%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Johann_Eck","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Johannes-Eck.jpg","license":"Public domain","pd":1}},"juan-de-maldonado":{"extract":"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Juan%20de%20Maldonado%22","kind":"search"}]},"cornelius-a-lapide":{"extract":"Cornelius Cornelii a Lapide, SJ was a Flemish Jesuit priest and noted exegete of Sacred Scripture.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Cornelius%20a%20Lapide%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Cornelius_a_Lapide","kind":"about"}],"isidoreFolder":"Lapide, Cornelius a, S.J., 1567-1637","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Cornelius_a_Lapide%2C_8B6292100_%28cropped%29.jpg","license":"Public domain","artist":"a Lapide, Cornelius Cornelii, S.J. (1567-1637) (depicted)","pd":1}},"leonard-lessius":{"extract":"Lenaert Leys, better known as Leonardus Lessius was a Brabant jurist, theologian, economist from the Jesuit order.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Leonard%20Lessius%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Leonardus_Lessius","kind":"about"}],"isidoreFolder":"Lessius, Leonardus, S.J., 1554-1623","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Portret_van_jezu%C3%AFet_Leonardus_Lessius_Leonardvs_Lessivs_Societatis_Iesv_Theologvs_%28titel_op_object%29%2C_RP-P-1939-318.jpg","license":"CC0","artist":"Rijksmuseum","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","pd":1}},"gabriel-vasquez":{"extract":"Gabriel Vásquez, known as Bellomontanus, was a Spanish theologian, Jesuit priest, and scholastic philosopher. Vásquez was the foremost academic rival of his fellow Jesuit Francisco Suárez, whose philosophical views he often and openly criticized. Suárez's treatment of the jus gentium, like his treatment of natural law, was partly directed at combatting the arguments of Vásquez.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Gabriel%20V%C3%A1squez%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gabriel_V%C3%A1squez","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Gabrie_Vazquez%2C_8B6293079_%28cropped%29.jpg","license":"Public domain","artist":"Vasquez, Gabriel, S.J. (1551-1604) (depicted)","pd":1}},"juan-de-lugo":{"extract":"John de Lugo, a Spanish Jesuit and Cardinal, was an eminent scholastic theologian of the Baroque period.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Juan%20de%20Lugo%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_de_Lugo","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Juan_de_Lugo.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"louis-lallemant":{"extract":"Louis Lallemant was a French Jesuit.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Louis%20Lallemant%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Louis_Lallemant","kind":"about"}],"isidoreFolder":"Lallemant, Louis, S.J., 1588-1635"},"jean-joseph-surin":{"extract":"Jean-Joseph Surin was a French Jesuit priest, mystic, devotional writer and exorcist. He is remembered for his participation in the exorcisms of Loudun in 1634–37.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jean-Joseph%20Surin%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jean-Joseph_Surin","kind":"about"}],"isidoreFolder":"Surin, Jean-Joseph, S.J., 1600-65"},"angelus-silesius":{"extract":"Angelus Silesius, OFM, born Johann Scheffler, was a German Catholic priest, physician, mystic and religious poet. Born and raised a Lutheran, he began to read the works of medieval mystics while studying in the Netherlands and became acquainted with the works of the German mystic Jacob Böhme through Böhme's friend Abraham von Franckenberg. Silesius's display of his mystic beliefs caused tension with Lutheran authorities and led to his eventual conversion to Catholicism in 1653, wherein he adopted the name Angelus and the epithet Silesius (\"Silesian\"). He entered the Franciscans and was ordaine","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/44674","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Angelus%20Silesius%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Angelus_Silesius","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Johannes_Scheffler.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"friedrich-spee":{"extract":"Friedrich Spee was a German Jesuit priest, professor, and poet, most well known as a forceful opponent of witch trials and one who was an insider writing from the epicenter of the European witch-phobia. Spee argued strongly against the use of torture, and as an eyewitness he gathered a book full of details regarding its cruelty and unreliability. He wrote, \"Torture has the power to create witches where none exist.\"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Friedrich%20Spee%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Friedrich_Spee","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Fridericus_Spee_SJ.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"claude-la-colombiere":{"extract":"Claude La Colombière, sometimes referred to as Claude de la Colombière, was a French Jesuit priest best known as the confessor of Margaret Mary Alacoque. He is venerated as a saint in the Catholic Church.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Claude%20La%20Colombi%C3%A8re%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Claude_La_Colombi%C3%A8re","kind":"about"}],"isidoreFolder":"de la Colombiere, Claude, S.J_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:ClaudedelaColombiere.jpg","license":"Public domain","pd":1}},"jean-baptiste-de-la-salle":{"extract":"Jean-Baptiste de La Salle was a French priest, educational reformer, and founder of the Institute of the Brothers of the Christian Schools. He is a saint of the Catholic Church and the patron saint for teachers of youth.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jean-Baptiste%20de%20La%20Salle%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jean-Baptiste_de_La_Salle","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Jean_baptiste_de_la_Salle.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"augustin-calmet":{"extract":"Antoine Augustin Calmet was a French Benedictine abbot.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/33896","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Augustin%20Calmet%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Antoine_Augustin_Calmet","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Portret_van_de_theoloog_Augustin_Calmet%2C_RP-P-1883-A-7537.jpg","license":"CC0","artist":"Rijksmuseum","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","pd":1}},"giovanni-battista-scaramelli":{"extract":"Giovanni Battista Scaramelli was an Italian Jesuit, ethicist, and ascetical writer.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Giovanni%20Battista%20Scaramelli%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Giovanni_Battista_Scaramelli","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Joannes_Baptista_Scaramelli%2C_8B6293034_%28cropped%29.jpg","license":"Public domain","artist":"Scaramelli, Joannes Baptista, S.J. (1687-1752) (depicted)","pd":1}},"john-gother":{"extract":"\n\nJohn Gother, also known as John Goter, was an English convert to Catholicism, priest, controvertist and eirenicist.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22John%20Gother%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Gother","kind":"about"}]},"clemens-brentano":{"extract":"Clemens Wenzeslaus Brentano was a German poet and novelist, and a major figure of German Romanticism. He was the uncle, via his brother Christian, of Franz and Lujo Brentano.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/882","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Clemens%20Brentano%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Clemens_Brentano","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Clemens_Brentano2.jpg","license":"Public domain","artist":"Emilie Linder","pd":1}},"friedrich-schlegel":{"extract":"Karl Wilhelm Friedrich von Schlegel was a German literary critic, philosopher, and Indologist. With his older brother, August Wilhelm Schlegel, he was one of the main figures of Jena Romanticism.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/35760","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Friedrich%20Schlegel%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Friedrich_Schlegel","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Franz_Gareis_Portrait_Friedrich_Schlegel.jpg","license":"Public domain","artist":"Franz Gareis","pd":1}},"joseph-gorres":{"extract":"Johann Joseph Görres, since 1839 von Görres, was a German writer, philosopher, theologian, historian and journalist.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Joseph%20G%C3%B6rres%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Joseph_G%C3%B6rres","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Painting_of_Joseph_G%C3%B6rres.jpg","license":"Public domain","artist":"Joseph Anton Nikolaus Settegast","pd":1}},"felicite-de-lamennais":{"extract":"Félicité Robert de La Mennais was a French Catholic priest, philosopher and political theorist. He was one of the most influential intellectuals of Restoration France. Lamennais is also considered the forerunner of both liberal Catholicism and Modernism.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/49622","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22F%C3%A9licit%C3%A9%20de%20Lamennais%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/F%C3%A9licit%C3%A9_de_La_Mennais","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Lanc%C3%B4me_-_Portrait_de_F%C3%A9licit%C3%A9_Robert_de_Lamennais_%281782-1854%29%2C_%C3%A9crivain_et_philosophe_-_P848_-_Mus%C3%A9e_Carnavalet_%28cropped%29.jpg","license":"CC0","artist":"L. D. Lancôme","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","pd":1}},"augustus-pugin":{"extract":"Augustus Welby Northmore Pugin was an English architect, designer, artist and critic with French and Swiss origins. He is principally remembered for his pioneering role in the Gothic Revival style of architecture. Among his best-known work is the interior and clock tower of the Palace of Westminster, the meeting place of the Parliament of the United Kingdom. Pugin designed many churches in England, and some in Ireland and Australia. He was the son of Auguste Pugin, and the father of Edward Welby Pugin, Cuthbert Welby Pugin, and Peter Paul Pugin, who continued his architectural and interior des","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/46585","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Augustus%20Pugin%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Augustus_Pugin","kind":"about"}],"isidoreFolder":"Pugin, A. Welby","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Augustus_Welby_Northmore_Pugin_from_NPG.jpg","license":"Public domain","artist":"Unidentified painter","pd":1}},"william-george-ward":{"extract":"William George Ward was an English theologian and mathematician. A Roman Catholic convert, his career illustrates the development of religious opinion at a time of crisis in the history of English religious thought.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22William%20George%20Ward%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/William_George_Ward","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Portrait_of_William_George_Ward.jpg","license":"Public domain","artist":"Not stated","pd":1}},"wilfrid-ward":{"extract":"Wilfrid Philip Ward was an English essayist and biographer. Ward and his friend Baron Friedrich von Hügel have been described as \"the two leading lay English Catholic thinkers of their generation\".","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Wilfrid%20Ward%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Wilfrid_Ward","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Wilfrid_Philip_Ward.jpg","license":"Public domain","artist":"George Grantham Bain Collection (Library of Congress)","pd":1}},"lord-acton":{"extract":"John Emerich Edward Dalberg-Acton, 1st Baron Acton, 13th Marquess of Groppoli,, better known as Lord Acton, was an English Catholic historian, Liberal politician, and writer. A strong advocate for individual liberty, Acton is best known for his observation on the dangers of concentrated authority. In an 1887 letter to an Anglican bishop, he famously wrote, 'Power tends to corrupt, and absolute power corrupts absolutely', underscoring his belief that unchecked power poses the greatest threat to human freedom. His works consistently emphasised the importance of limiting governmental and institut","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Lord%20Acton%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Dalberg-Acton%2C_1st_Baron_Acton","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Picture_of_John_Dalberg-Acton%2C_1st_Baron_Acton.jpg","license":"Public domain","artist":"Allen & Co.","pd":1}},"aubrey-de-vere":{"extract":"Aubrey Thomas de Vere was an Irish poet and critic.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/2360","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Aubrey%20de%20Vere%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Aubrey_Thomas_de_Vere","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Aubrey_de_Vere_by_Julia_Margaret_Cameron.jpg","license":"Public domain","artist":"Julia Margaret Cameron","pd":1}},"mother-mary-loyola":{"extract":"Mother Mary Loyola (1845–1930) was an English Roman Catholic nun and an author of bestselling Catholic books. James Fallon SJ, writing for the Jesuit magazine America in 1931, called her one of the \"most prolific and popular\" writers in the Catholic literary world. She published her first book in 1896 at age 51, and produced at least 27 more in the ensuing 30 years. Her works sold globally and were translated into many languages.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/58653","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Mother%20Mary%20Loyola%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mother_Mary_Loyola","kind":"about"}]},"joseph-gredt":{"extract":"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Joseph%20Gredt%22","kind":"search"}],"isidoreFolder":"Gredt, Josephus, O.S.B_"},"desire-joseph-mercier":{"extract":"Désiré Félicien François Joseph Mercier was a Belgian Catholic prelate who served as Archbishop of Mechelen from 1906 until his death in 1926. A Thomist scholar, he had several of his works translated into other European languages. He was known for his book, Les origines de la psychologie contemporaine (1897). He was elevated to the cardinalate in 1907.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22D%C3%A9sir%C3%A9-Joseph%20Mercier%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/D%C3%A9sir%C3%A9-Joseph_Mercier","kind":"about"}],"isidoreFolder":"Mercier, Desire Joseph, 1851-1926","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Cardinal_Mercier.png","license":"Public domain","artist":"Published by NY Times","pd":1}},"adrian-fortescue":{"extract":"Adrian Henry Timothy Knottesford Fortescue was an English Catholic priest and polymath. An influential liturgist, artist, calligrapher, composer, polyglot, amateur photographer, Byzantine scholar, and adventurer, he was also the founder of the Church of St Hugh of Lincoln in Letchworth.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Adrian%20Fortescue%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Adrian_Fortescue","kind":"about"}],"isidoreFolder":"Fortescue, Adrian, 1874-1923","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Adrian_Fortescue_portrait.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"herbert-thurston":{"extract":"Herbert Henry Charles Thurston was an English priest of the Roman Catholic Church, a member of the Jesuit order, and a prolific scholar on liturgical, literary, historical, and spiritual matters. In his day, he was regarded as an expert on spiritualism. Today he is remembered chiefly for his extensive contributions to the Catholic Encyclopedia. He also served as editor of Mother Mary Loyola, an international bestselling author of popular religious books.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/58654","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Herbert%20Thurston%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Herbert_Thurston","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Herbert_Thurston_%281856%E2%80%931939%29.png","license":"Public domain","artist":"Author unknown","pd":1}},"cuthbert-butler":{"extract":"Cuthbert Butler was an Irish ecclesiastical historian much of whose career was spent as Benedictine of Downside Abbey in England. He was sometimes referred to as Dom Cuthbert Butler.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Cuthbert%20Butler%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Edward_Cuthbert_Butler","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Edward_Cuthbert_Butler_%281858%E2%80%931934%29.png","license":"Public domain","artist":"Author unknown","pd":1}},"john-chapman":{"extract":"John Chapman was an English Roman Catholic abbot of Downside Abbey of the English Benedictine Congregation from 1929 until his death, and a New Testament and patristics scholar.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22John%20Chapman%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Chapman_(priest)","kind":"about"}],"isidoreFolder":"Chapman, John, 1865-1933","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:John_Chapman.jpg","license":"CC BY 4.0","artist":"Christian Daw","licenseUrl":"https://creativecommons.org/licenses/by/4.0"},"img":"https://upload.wikimedia.org/wikipedia/commons/b/b4/John_Chapman.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled"},"vincent-mcnabb":{"extract":"Vincent McNabb was an Irish Catholic scholar and Dominican priest based in London who was active in evangelisation and apologetics.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Vincent%20McNabb%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Vincent_McNabb","kind":"about"}],"isidoreFolder":"McNabb, Vincent, O.P_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Vincent_McNabb.png","license":"CC BY 4.0","artist":"St. Dominic's Press","licenseUrl":"https://creativecommons.org/licenses/by/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c2/Vincent_McNabb.png/330px-Vincent_McNabb.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"bede-jarrett":{"extract":"Bede Jarrett OP was an English Dominican friar and Catholic priest who was also a noted historian and author. Known for works including Mediæval Socialism and The Emperor Charles IV, Jarrett also founded Blackfriars Priory at the University of Oxford in 1921, formally reinstating the Dominican Order at that university for the first time since the Dissolution of the Monasteries under King Henry VIII.","qidWork":null,"links":[{"label":"Free e-books at Project Gutenberg","url":"https://www.gutenberg.org/ebooks/author/8696","kind":"read"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Bede%20Jarrett%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Bede_Jarrett","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Bede_Jarrett_%281881%E2%80%931934%29.png","license":"Public domain","artist":"Author unknown","pd":1}},"c-c-martindale":{"extract":"Cyril Charlie Martindale was a Roman Catholic priest, scholar, and writer. Along with Martin D'Arcy, he was one of England's foremost Catholics of the first half of the 20th century, and was a correspondent of figures including Graham Greene, Evelyn Waugh, and Ronald Knox.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22C.%20C.%20Martindale%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/C._C._Martindale","kind":"about"}],"isidoreFolder":"Martindale, Cyril Charles, S.J_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Cyril_Charlie_Martindale%2C_negative%2C_1927_%28Lafayette%3B_NPG_x69313%29_%28edges_trimmed%29.png","license":"Public domain","artist":"Lafayette Ltd","pd":1}},"anscar-vonier":{"extract":"Anscar Vonier was abbot of Buckfast Abbey from 1906 until his death in 1938.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Anscar%20Vonier%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Anscar_Vonier","kind":"about"}],"isidoreFolder":"Vonier, Anscar, 1875-1938","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Anscar_Vonier.jpg","license":"Public domain","artist":"Author unknown","pd":1}},"josef-jungmann":{"extract":"Josef Andreas Jungmann, SJ was an Austrian Jesuit priest and liturgist. He was an influential advocate of the Liturgical Movement, and is known for his 2-volume history Mass of the Roman Rite, which contributed to informing the reforms to the Mass during and following the Second Vatican Council, as well as his work in the post-Vatican II catechetical movement in the Catholic Church.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Josef%20Jungmann%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Josef_Andreas_Jungmann","kind":"about"}],"isidoreFolder":"Jungmann, Josef A., S.J_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Josef_Andreas_Jungmann.jpg","license":"Public domain","artist":"Society of Jesus (Innbruck)","pd":1}},"pius-parsch":{"extract":"Pius Parsch, born John Bruno Parsch was a priest of the Roman Catholic Church.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Pius%20Parsch%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pius_Parsch","kind":"about"}]},"odo-casel":{"extract":"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Odo%20Casel%22","kind":"search"}]},"charles-de-koninck":{"extract":"Charles De Koninck was a Belgian-Canadian Thomist philosopher and theologian. As director of the Department of Philosophy at the Université Laval in Quebec, he influenced Catholic philosophy in French Canada and also influenced Catholic philosophers in English Canada and the United States. The author of many books and articles in French and English, he contributed to a variety of philosophical fields including natural philosophy, philosophy of science, philosophy of mathematics, and political philosophy, but he also wrote on theology, especially Mariology.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Charles%20De%20Koninck%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Charles_De_Koninck","kind":"about"}],"isidoreFolder":"de Koninck, Charles","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Charles_De_Koninck_Quebec%2C_18_novembre_1945_%283x4_cropped%29.jpg","license":"Public domain","artist":"Photo : Roger Bédard","pd":1}},"yves-simon":{"extract":"Yves René Marie Simon was a French Catholic political philosopher.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Yves%20Simon%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Yves_Simon_(philosopher)","kind":"about"}],"isidoreFolder":"Simon, Yves R_"},"antonio-royo-marin":{"extract":"Antonio Royo Marín, O.P., was a Spanish Dominican priest and theologian. He was an influential theologian and moralist, specially as a Thomist.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Antonio%20Royo%20Mar%C3%ADn%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Antonio_Royo_Mar%C3%ADn","kind":"about"}],"isidoreFolder":"Royo Marin, Antonio, O.P_"},"jean-leclercq":{"extract":"Jean Leclercq OSB, was a French Benedictine monk, the author of classic studies on Lectio Divina and the history of inter-monastic dialogue, as well as the life and theology of Saint Bernard of Clairvaux. LeClercq is perhaps best known in the English speaking world for his seminal work The Love of Learning and the Desire for God: A Study of Monastic Culture.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Jean%20Leclercq%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jean_Leclercq_(monk)","kind":"about"}],"isidoreFolder":"Leclercq, Jean, O.S.B_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Dom_Jean_Leclercq.jpg","license":"CC0","artist":"Author unknown","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","pd":1}},"bernard-haring":{"extract":"Bernard Häring was a German moral theologian and a Redemptorist priest in the Catholic Church. The National Catholic Reporter, upon his death, called him \"the foremost Catholic moral theologian of the 20th century and a leading advocate for church reform before, during and after the Second Vatican Council.\"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Bernard%20H%C3%A4ring%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Bernhard_H%C3%A4ring","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:BernhardH%C3%A4ring0001.jpg","license":"Copyrighted free use","artist":"Pater Josef Steinle AMPR"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5c/BernhardH%C3%A4ring0001.jpg/330px-BernhardH%C3%A4ring0001.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"romano-amerio":{"extract":"\nRomano Amerio was a Swiss-Italian theologian and a late critic of post-Conciliar evolutions in liturgy and ecclesiology. His magnum opus is Iota Unum. It is a work dedicated to the study of the ruptures in Church teaching and tradition following the Second Vatican Council.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Romano%20Amerio%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Romano_Amerio","kind":"about"}],"isidoreFolder":"Amerio, Romano","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:FOTO_AMERIO_CHIARA.jpg","license":"Attribution","artist":"Enrico Maria Radaelli"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c3/FOTO_AMERIO_CHIARA.jpg/330px-FOTO_AMERIO_CHIARA.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"michael-davies":{"extract":"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Michael%20Davies%22","kind":"search"}],"isidoreFolder":"Davies, Michael"},"martin-mosebach":{"extract":"Martin Mosebach is a German writer.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Martin%20Mosebach%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Martin_Mosebach","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Mosebachduess2014.jpg","license":"CC BY-SA 3.0","artist":"Udoweier","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d0/Mosebachduess2014.jpg/330px-Mosebachduess2014.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"fabrice-hadjadj":{"extract":"Fabrice Hadjadj is a French philosopher. Hadjadj was born in Nanterre to Jewish parents of Tunisian heritage. In his teens he was an atheist and anarchist, and he maintained a nihilistic attitude for most of his twenties until, in 1998, he converted to Catholicism.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Fabrice%20Hadjadj%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Fabrice_Hadjadj","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Fabrice_Hadjadj.jpg","license":"Public domain","artist":"Djares","pd":1}},"chiara-lubich":{"extract":"Chiara Lubich was an Italian teacher and Catholic author who founded the Focolare Movement, which aims to bring unity among people and promote universal family.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Chiara%20Lubich%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Chiara_Lubich","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Chiara_Lubich_primo_piano.jpg","license":"CC BY-SA 4.0","artist":"CSC Audiovisivi","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/Chiara_Lubich_primo_piano.jpg/330px-Chiara_Lubich_primo_piano.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"luigi-giussani":{"extract":"Luigi Giovanni Giussani was an Italian Catholic priest, theologian, educator, public intellectual, and founder of the international Catholic movement Communion and Liberation. His canonization process was opened in 2012.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Luigi%20Giussani%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Luigi_Giussani","kind":"about"}]},"catherine-doherty":{"extract":"Catherine de Hueck Doherty was a Russian-born Catholic activist who founded the Madonna House Apostolate in 1947. She was a pioneer in the struggle for interracial justice, spiritual writer, lecturer, and spiritual mother to priests and laity.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Catherine%20Doherty%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Catherine_Doherty","kind":"about"}]},"thomas-dubay":{"extract":"Father Thomas Edward Dubay, S.M., was an American Catholic priest, author, and retreat director. He wrote over 20 books on Catholic spirituality, in which he emphasized the importance of renewed conversion and contemplative prayer, and he traveled worldwide to teach at parishes, seminaries, and monasteries.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Thomas%20Dubay%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Thomas_Dubay","kind":"about"}],"isidoreFolder":"Dubay, Thomas, S.M_"},"mortimer-adler":{"extract":"Mortimer Jerome Adler was an American philosopher, educator, encyclopedist, author, and lay theologian. His philosophical work was situated within the Aristotelian and Thomistic traditions. Adler taught at Columbia University and the University of Chicago, served as chairman of the board of editors of Encyclopædia Britannica, and founded the Institute for Philosophical Research.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Mortimer%20Adler%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mortimer_J._Adler","kind":"about"}],"isidoreFolder":"Adler, Mortimer J_","imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Mortimer_Adler.jpg","license":"CC BY-SA 3.0","artist":"Center for the Study of The Great Ideas","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/Mortimer_Adler.jpg/330px-Mortimer_Adler.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"ralph-martin":{"extract":"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Ralph%20Martin%22","kind":"search"}]},"mary-healy":{"extract":"Mary Healy is a Catholic theologian and an international speaker. She teaches sacred scripture at Sacred Heart Major Seminary in Detroit, Michigan. Her main interests include faith healing, evangelization, and Catholic spirituality. Healy was one of the first women appointed by Pope Francis in 2014 to the Pontifical Biblical Commission.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Mary%20Healy%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mary_Healy_(theologian)","kind":"about"}]},"michael-pakaluk":{"extract":"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Michael%20Pakaluk%22","kind":"search"}],"isidoreFolder":"Pakaluk, Michael"},"john-senior":{"extract":"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22John%20Senior%22","kind":"search"}],"isidoreFolder":"Senior, John, 1923-1999"},"steve-ray":{"extract":"","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Steve%20Ray%22","kind":"search"}]},"marcus-grodi":{"extract":"","qidWork":null,"links":[{"label":"Coming Home Network","url":"https://chnetwork.org/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Marcus%20Grodi%22","kind":"search"}]},"raymond-arroyo":{"extract":"Raymond Arroyo is an American author, journalist, and producer. In 1996, he created the EWTN news program The World Over Live and authored the Will Wilder series. He also presents the \"Seen and Unseen\" and \"Friday Follies\" segments on Fox News Channel's The Ingraham Angle.","qidWork":null,"links":[{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Raymond%20Arroyo%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Raymond_Arroyo","kind":"about"}],"imgCredit":{"page":"https://commons.wikimedia.org/wiki/File:Raymond_Arroyo_by_Gage_Skidmore_%28cropped%29.jpg","license":"CC BY-SA 3.0","artist":"Gage Skidmore","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9e/Raymond_Arroyo_by_Gage_Skidmore_%28cropped%29.jpg/330px-Raymond_Arroyo_by_Gage_Skidmore_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},"mother-angelica":{"extract":"Mary Angelica of the Annunciation, commonly referred to as \"Mother Angelica\", was an American Catholic nun of the Poor Clares of Perpetual Adoration.","qidWork":null,"links":[{"label":"EWTN","url":"https://www.ewtn.com/","kind":"site"},{"label":"Search the Internet Archive","url":"https://archive.org/search?query=%22Mother%20Angelica%22","kind":"search"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mother_Angelica","kind":"about"}]}}};
